(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("demosthenes-minor-e", [{"sp": "HDR", "t": "Ἐπιτάφιος, Ἐρωτικός, Προοίμια, Ἐπιστολαί"}, {"sp": "HDR", "t": "Ἐπιτάφιος", "st": "60"}, {"sp": "N", "t": "ἐπειδὴ τοὺς ἐν τῷδε τῷ τάφῳ κειμένους, ἄνδρας ἀγαθοὺς ἐν τῷ πολέμῳ γεγονότας, ἔδοξεν τῇ πόλει δημοσίᾳ θάπτειν καὶ προσέταξεν ἐμοὶ τὸν νομιζόμενον λόγον εἰπεῖν ἐπ’ αὐτοῖς, ἐσκόπουν μὲν εὐθὺς ὅπως τοῦ προσήκοντος ἐπαίνου τεύξονται, ἐξετάζων δὲ καὶ σκοπῶν ἀξίως εἰπεῖν τῶν τετελευτηκότων ἕν τι τῶν ἀδυνάτων ηὕρισκον ὄν. οἳ γὰρ τὴν ὑπάρχουσαν πᾶσιν ἔμφυτον τοῦ ζῆν ὑπερεῖδον ἐπιθυμίαν, καὶ τελευτῆσαι καλῶς μᾶλλον ἠβουλήθησαν ἢ ζῶντες τὴν Ἑλλάδ’ ἰδεῖν ἀτυχοῦσαν, πῶς οὐκ ἀνυπέρβλητον παντὶ λόγῳ τὴν αὑτῶν ἀρετὴν καταλελοίπασιν; ὁμοίως μέντοι διαλεχθῆναι τοῖς πρότερόν ποτ’ εἰρηκόσιν ἐνθάδ’ εἶναι μοι δοκεῖ.", "st": "60.1"}, {"sp": "N", "t": "ὡς μὲν οὖν ἡ πόλις σπουδάζει περὶ τοὺς ἐν τῷ πολέμῳ τελευτῶντας, ἔκ τε τῶν ἄλλων ἔστιν ἰδεῖν καὶ μάλιστ’ ἐκ τοῦδε τοῦ νόμου, καθ’ ὃν αἱρεῖται τὸν ἐροῦντ’ ἐπὶ ταῖς δημοσίαις ταφαῖς· εἰδυῖα γὰρ παρὰ τοῖς ἀγαθοῖς ἀνδράσιν τὰς μὲν τῶν χρημάτων κτήσεις καὶ τῶν κατὰ τὸν βίον ἡδονῶν ἀπολαύσεις ὑπερεωραμένας, τῆς δ’ ἀρετῆς καὶ τῶν ἐπαίνων πᾶσαν τὴν ἐπιθυμίαν οὖσαν, ἐξ ὧν ταῦτ’ ἂν αὐτοῖς μάλιστα γένοιτο λόγων, τούτοις ᾠήθησαν δεῖν αὐτοὺς τιμᾶν, ἵν’ ἣν ζῶντες ἐκτήσαντ’ εὐδοξίαν, αὕτη καὶ τετελευτηκόσιν αὐτοῖς ἀποδοθείη.", "st": "60.2"}, {"sp": "N", "t": "εἰ μὲν οὖν τὴν ἀνδρείαν μόνον αὐτοῖς τῶν εἰς ἀρετὴν ἀνηκόντων ὑπάρχουσαν ἑώρων, ταύτην ἂν ἐπαινέσας ἀπηλλαττόμην τῶν λοιπῶν· ἐπειδὴ δὲ καὶ γεγενῆσθαι καλῶς καὶ πεπαιδεῦσθαι σωφρόνως καὶ βεβιωκέναι φιλοτίμως συμβέβηκεν αὐτοῖς, ἐξ ὧν εἰκότως ἦσαν σπουδαῖοι, αἰσχυνοίμην ἂν εἴ τι τούτων φανείην παραλιπών. ἄρξομαι δ’ ἀπὸ τῆς τοῦ γένους αὐτῶν ἀρχῆς.", "st": "60.3"}, {"sp": "N", "t": "ἡ γὰρ εὐγένεια τῶνδε τῶν ἀνδρῶν ἐκ πλείστου χρόνου παρὰ πᾶσιν ἀνθρώποις ἀνωμολόγηται. οὐ γὰρ μόνον εἰς πατέρ’ αὐτοῖς καὶ τῶν ἄνω προγόνων κατ’ ἄνδρ’ ἀνενεγκεῖν ἑκάστῳ τὴν φύσιν ἔστιν, ἀλλ’ εἰς ὅλην κοινῇ τὴν ὑπάρχουσαν πατρίδα, ἧς αὐτόχθονες ὁμολογοῦνται εἶναι. μόνοι γὰρ πάντων ἀνθρώπων, ἐξ ἧσπερ ἔφυσαν, ταύτην ᾤκησαν καὶ τοῖς ἐξ αὑτῶν παρέδωκαν, ὥστε δικαίως ἄν τις ὑπολάβοι τοὺς μὲν ἐπήλυδας ἐλθόντας εἰς τὰς πόλεις καὶ τούτων πολίτας προσαγορευομένους ὁμοίους εἶναι τοῖς εἰσποιητοῖς τῶν παίδων, τούτους δὲ γνησίους γόνῳ τῆς πατρίδος πολίτας εἶναι.", "st": "60.4"}, {"sp": "N", "t": "δοκεῖ δέ μοι καὶ τὸ τοὺς καρπούς, οἷς ζῶσιν ἅνθρωποι, παρ’ ἡμῖν πρώτοις φανῆναι, χωρὶς τοῦ μέγιστον εὐεργέτημ’ εἰς πάντας γενέσθαι, ὁμολογούμενον σημεῖον ὑπάρχειν τοῦ μητέρα τὴν χώραν εἶναι τῶν ἡμετέρων προγόνων. πάντα γὰρ τὰ τίκτονθ’ ἅμα καὶ τροφὴν τοῖς γιγνομένοις ἀπ’ αὐτῆς τῆς φύσεως φέρει· ὅπερ ἥδ’ ἡ χώρα πεποίηκεν.", "st": "60.5"}, {"sp": "N", "t": "τὰ μὲν οὖν εἰς γένος ἀνήκοντα τοιαῦτα δι’ αἰῶνος ὑπάρχει τοῖς τῶνδε τῶν ἀνδρῶν προγόνοις. τὰ δ’ εἰς ἀνδρείαν καὶ τὴν ἄλλην ἀρετὴν πάντα μὲν κατοκνῶ λέγειν, φυλαττόμενος μὴ μῆκος ἄκαιρον ἐπιγένηται τῷ λόγῳ· ἃ δὲ καὶ τοῖς εἰδόσιν χρήσιμ’ ἀναμνησθῆναι καὶ τοῖς ἀπείροις κάλλιστ’ ἀκοῦσαι, καὶ ζῆλον ἔχει πολὺν καὶ μῆκος λόγου ἄλυπον, ταῦτ’ ἐπὶ κεφαλαίων εἰπεῖν πειράσομαι.", "st": "60.6"}, {"sp": "N", "t": "οἱ γὰρ τῆς κατὰ τὸν παρόντα χρόνον γενεᾶς πρόγονοι, καὶ πατέρες καὶ τούτων ἐπάνω τὰς προσηγορίας ἔχοντες, αἷς ὑπὸ τῶν ἐν γένει γνωρίζονται, ἠδίκησαν μὲν οὐδένα πώποτ’ οὔθ’ Ἕλλην’ οὔτε βάρβαρον, ἀλλ’ ὑπῆρχεν αὐτοῖς πρὸς ἅπασι τοῖς ἄλλοις καλοῖς κἀγαθοῖς καὶ δικαιοτάτοις εἶναι, ἀμυνόμενοι δὲ πολλὰ καὶ καλὰ διεπράξαντο.", "st": "60.7"}, {"sp": "N", "t": "καὶ γὰρ τὸν Ἀμαζόνων στρατὸν ἐλθόντ’ ἐκράτησαν οὕτως ὥστ’ ἔξω Φάσιδος ἐκβαλεῖν, καὶ τὸν Εὐμόλπου καὶ τῶν πολλῶν ἄλλων στόλον οὐ μόνον ἐκ τῆς οἰκείας, ἀλλὰ καὶ ἐκ τῆς τῶν ἄλλων Ἑλλήνων χώρας ἐξήλασαν, οὓς οἱ πρὸ ἡμῶν οἰκοῦντες πρὸς ἑσπέραν πάντες οὔθ’ ὑπέμειναν οὔτ’ ἐδυνήθησαν κωλῦσαι. καὶ μὴν καὶ τῶν Ἡρακλέους παίδων, ὃς τοὺς ἄλλους ἔσῳζεν, σωτῆρες ὠνομάσθησαν, ἡνίκ’ ἦλθον εἰς τήνδε τὴν γῆν ἱκέται, φεύγοντες Εὐρυσθέα. καὶ πρὸς πᾶσι τούτοις καὶ πολλοῖς ἄλλοις καὶ καλοῖς ἔργοις τὰ τῶν κατοιχομένων νόμιμ’ οὐ περιεῖδον ὑβριζόμενα, ὅτε τοὺς ἕπτ’ ἐπὶ Θήβας θάπτειν ἐκώλυεν Κρέων.", "st": "60.8"}, {"sp": "N", "t": "τῶν μὲν οὖν εἰς μύθους ἀνενηνεγμένων ἔργων πολλὰ παραλιπὼν τούτων ἐπεμνήσθην, ὧν οὕτως ἕκαστον εὐσχήμονας καὶ πολλοὺς ἔχει λόγους ὥστε καὶ τοὺς ἐν μέτροις καὶ τοὺς τῶν ᾀδομένων ποιητὰς καὶ πολλοὺς τῶν συγγραφέων ὑποθέσεις τἀκείνων ἔργα τῆς αὑτῶν μουσικῆς πεποιῆσθαι· ἃ δὲ τῇ μὲν ἀξίᾳ τῶν ἔργων οὐδέν ἐστι τούτων ἐλάττω, τῷ δ’ ὑπογυώτερ’ εἶναι τοῖς χρόνοις οὔπω μεμυθολόγηται, οὐδ’ εἰς τὴν ἡρωϊκὴν ἐπανῆκται τάξιν, ταῦτ’ ἤδη λέξω.", "st": "60.9"}, {"sp": "N", "t": "ἐκεῖνοι τὸν ἐξ ἁπάσης τῆς Ἀσίας στόλον ἐλθόντα μόνοι δὶς ἠμύναντο καὶ κατὰ γῆν καὶ κατὰ θάλατταν, καὶ διὰ τῶν ἰδίων κινδύνων κοινῆς σωτηρίας πᾶσι τοῖς Ἕλλησιν αἴτιοι κατέστησαν. καὶ προείρηται μὲν ὃ μέλλω λέγειν ὑπ’ ἄλλων πρότερον, δεῖ δὲ μηδὲ νῦν τοῦ δικαίου καὶ καλῶς ἔχοντος ἐπαίνου τοὺς ἄνδρας ἐκείνους στερηθῆναι· τοσούτῳ γὰρ ἀμείνους τῶν ἐπὶ Τροίαν στρατευσαμένων νομίζοιντ’ ἂν εἰκότως, ὅσον οἱ μὲν ἐξ ἁπάσης τῆς Ἑλλάδος ὄντες ἀριστεῖς δέκ’ ἔτη τῆς Ἀσίας ἓν χωρίον πολιορκοῦντες μόλις εἷλον,", "st": "60.10"}, {"sp": "N", "t": "οὗτοι δὲ τὸν ἐκ πάσης τῆς ἠπείρου στόλον ἐλθόντα μόνοι, τἄλλα πάντα κατεστραμμένον, οὐ μόνον ἠμύναντο, ἀλλὰ καὶ τιμωρίαν ὑπὲρ ὧν τοὺς ἄλλους ἠδίκουν ἐπέθηκαν. ἔτι τοίνυν τὰς ἐν αὐτοῖς τοῖς Ἕλλησιν πλεονεξίας κωλύοντες πάντας ὅσους συνέβη γενέσθαι κινδύνους ὑπέμειναν, ὅπου τὸ δίκαιον εἴη τεταγμένον, ἐνταῦθα προσνέμοντες ἑαυτούς, ἕως εἰς τὴν νῦν ζῶσαν ἡλικίαν ὁ χρόνος προήγαγεν ἡμᾶς.", "st": "60.11"}, {"sp": "N", "t": "μηδεὶς δ’ ἡγείσθω μ’ ἀποροῦντα τί χρὴ περὶ τούτων εἰπεῖν ἑκάστου, ταῦτα τὰ πραχθέντ’ ἀπηριθμηκέναι. εἰ γὰρ ἁπάντων ἀμηχανώτατος ἦν ὅ τι χρὴ λέγειν πορίσασθαι, ἡ ’κείνων ἀρετὴ δείκνυσιν αὐτὴ ἃ καὶ πρόχειρα καὶ ῥᾴδι’ ἐπελθεῖν ἐστιν. ἀλλὰ προαιροῦμαι τῆς εὐγενείας καὶ τῶν παρὰ τοῖς προγόνοις μεγίστων μνησθεὶς ὡς τάχιστα συνάψαι τὸν λόγον πρὸς τὰ τοῖσδε πεπραγμένα, ἵνα, ὥσπερ τὰς φύσεις ἦσαν συγγενεῖς, οὕτω τοὺς ἐπαίνους ἐπ’ αὐτῶν κοινοὺς ποιήσωμαι, ὑπολαμβάνων ταῦτ’ ἂν εἶναι κεχαρισμένα [κἀκείνοις] καὶ μάλιστ’ ἀμφοτέροις, εἰ τῆς ἀλλήλων ἀρετῆς μὴ μόνον τῇ φύσει μετάσχοιεν, ἀλλὰ καὶ τοῖς ἐπαίνοις.", "st": "60.12"}, {"sp": "N", "t": "ἀνάγκη δ’ ἐν τῷ μεταξὺ διαλαβεῖν, καὶ πρὸ τοῦ τὰ τοῖσδε πεπραγμένα τοῖς ἀνδράσιν δηλοῦν καὶ τοὺς ἔξω τοῦ γένους πρὸς τὸν τάφον ἠκολουθηκότας πρὸς εὔνοιαν παρα- καλέσαι. καὶ γὰρ εἰ μὲν εἰς χρημάτων δαπάνην ἤ τιν’ ἄλλην θεωρίαν ἱππικῶν ἢ γυμνικῶν ἄθλων ἐτάχθην κοσμῆσαι τὸν τάφον, ὅσῳπερ ἂν προθυμότερον καὶ ἀφειδέστερον ταῦτα παρεσκευάσμην, τοσούτῳ μᾶλλον ἂν προσήκοντ’ ἔδοξα πεποιηκέναι· λόγῳ δ’ ἐπαινέσαι τούτους τοὺς ἄνδρας αἱρεθείς, ἂν μὴ τοὺς ἀκούοντας συμβουλομένους λάβω, φοβοῦμαι μὴ τῇ προθυμίᾳ τοὐναντίον οὗ δεῖ ποιήσω.", "st": "60.13"}, {"sp": "N", "t": "ὁ μὲν γὰρ πλοῦτος καὶ τὸ τάχος καὶ ἡ ἰσχὺς καὶ ὅσ’ ἄλλα τούτοις ὅμοια, αὐτάρκεις ἔχει τὰς ὀνήσεις τοῖς κεκτημένοις, καὶ κρατοῦσιν ἐν αὐτοῖς, οἷς ἂν παρῇ, κἂν μηδεὶς τῶν ἄλλων βούληται· ἡ δὲ τῶν λόγων πειθὼ τῆς τῶν ἀκουόντων εὐνοίας προσδεῖται, καὶ μετὰ ταύτης μέν, κἂν μετρίως ῥηθῇ, δόξαν ἤνεγκε καὶ χάριν προσποιεῖ, ἄνευ δὲ ταύτης, κἂν ὑπερβάλῃ τῷ λέγειν καλῶς, προσέστη τοῖς ἀκούουσιν.", "st": "60.14"}, {"sp": "N", "t": "πολλὰ τοίνυν ἔχων εἰπεῖν ὧν οἵδε πράξαντες δικαίως ἐπαινεθήσονται, ἐπειδὴ πρὸς αὐτοῖς εἰμι τοῖς ἔργοις, ἀπορῶ τί πρῶτον εἴπω· προσιστάμενα γάρ μοι πάντ’ εἰς ἕνα καιρὸν δύσκριτον καθίστησιν τὴν αἵρεσιν αὐτῶν. οὐ μὴν ἀλλὰ πειράσομαι τὴν αὐτὴν ποιήσασθαι τοῦ λόγου τάξιν ἥπερ ὑπῆρξεν τοῦ βίου τούτοις.", "st": "60.15"}, {"sp": "N", "t": "οἵδε γὰρ ἐξ ἀρχῆς ἐν πᾶσιν τοῖς παιδεύμασιν ἦσαν ἐπιφανεῖς, τὰ πρέποντα καθ’ ἡλικίαν ἀσκοῦντες ἑκάστην, καὶ πᾶσιν ἀρέσκοντες οἷς χρή, γονεῦσιν, φίλοις, οἰκείοις. τοιγαροῦν ὥσπερ ἴχνη γνωρίζουσα νῦν ἡ τῶν οἰκείων αὐτοῖς καὶ φίλων μνήμη πᾶσαν ὥραν ἐπὶ τούτους φέρεται τῷ πόθῳ,", "st": "60.16"}, {"sp": "N", "t": "πόλλ’ ὑπομνήματα λαμβάνουσα, ἐν οἷς συνῄδει τούτοις ἀρίστοις οὖσιν. ἐπειδὴ δ’ εἰς ἄνδρας ἀφίκοντο, οὐ μόνον τοῖς πολίταις γνώριμον τὴν αὑτῶν φύσιν ἀλλὰ καὶ πᾶσιν ἀνθρώποις κατέστησαν. ἔστιν γάρ, ἔστιν ἁπάσης ἀρετῆς ἀρχὴ μὲν σύνεσις, πέρας δ’ ἀνδρεία· καὶ τῇ μὲν δοκιμάζεται τί πρακτέον ἐστί, τῇ δὲ σῴζεται. ἐν τούτοις ἀμφοτέροις οἵδε πολὺ διήνεγκαν.", "st": "60.17"}, {"sp": "N", "t": "καὶ γὰρ εἴ τις ἐφύετο κοινὸς πᾶσιν κίνδυνος τοῖς Ἕλλησιν, οὗτοι πρῶτοι προείδοντο καὶ πολλάκις εἰς σωτηρίαν ἅπαντας παρεκάλεσαν, ὅπερ γνώμης ἀπόδειξίς ἐστιν εὖ φρονούσης· καὶ τῆς παρὰ τοῖς Ἕλλησιν ἀγνοίας μεμειγμένης κακίᾳ, ὅτ’ ἐνῆν ταῦτα κωλύειν ἀσφαλῶς, τὰ μὲν οὐ προορώσης τὰ δ’ εἰρωνευομένης, ὅμως, ἡνίχ’ ὑπήκουσαν καὶ τὰ δέοντα ποιεῖν ἠθέλησαν, οὐκ ἐμνησικάκησαν, ἀλλὰ προστάντες καὶ παρασχόντες ἅπαντα προθύμως, καὶ σώματα καὶ χρήματα καὶ συμμάχους, εἰς πεῖραν ἦλθον ἀγῶνος, εἰς ὃν οὐδὲ τῆς ψυχῆς ἐφείσαντο.", "st": "60.18"}, {"sp": "N", "t": "ἐξ ἀνάγκης δὲ συμβαίνει, ὅταν μάχη γίγνηται, τοῖς μὲν ἡττᾶσθαι, τοῖς δὲ νικᾶν· οὐκ ἂν ὀκνήσαιμι δ’ εἰπεῖν ὅτι μοι δοκοῦσιν οἱ τελευτῶντες ἑκατέρων ἐν τάξει τῆς μὲν ἥττης οὐ μετέχειν, νικᾶν δ’ ὁμοίως ἀμφότεροι. τὸ μὲν γὰρ κρατεῖν ἐν τοῖς ζῶσιν, ὡς ἂν ὁ δαίμων παραδῷ, κρίνεται· ὃ δ’ εἰς τοῦθ’ ἕκαστον ἔδει παρασχέσθαι, πᾶς ὁ μένων [ἐν τάξει] πεποίηκεν. εἰ δὲ θνητὸς ὢν τὴν εἱμαρμένην ἔσχεν, τῇ τύχῃ πέπονθε τὸ συμβαῖνον, οὐχὶ τὴν ψυχὴν ἥττηται τῶν ἐναντίων.", "st": "60.19"}, {"sp": "N", "t": "νομίζω τοίνυν καὶ τοῦ τῆς χώρας ἡμῶν μὴ ἐπιβῆναι τοὺς πολεμίους πρὸς τῇ τῶν ἐναντίων ἀγνωμοσύνῃ τὴν τούτων ἀρετὴν αἰτίαν γεγενῆσθαι· κατ’ ἄνδρα γὰρ πεῖραν εἰληφότες οἱ τότε συμμείξαντες ἐκεῖ, οὐκ ἐβούλοντ’ αὖθις εἰς ἀγῶνα καθίστασθαι τοῖς ἐκείνων οἰκείοις, ὑπολαμβάνοντες ταῖς μὲν φύσεσιν ταῖς ὁμοίαις ἀπαντήσεσθαι, τύχην δ’ οὐκ εὔπορον εἶναι τὴν ὁμοίαν λαβεῖν. δηλοῖ δ’ οὐχ ἥκισθ’ ὅτι ταῦθ’ οὕτως ἔχει καὶ τὰ τῆς γεγονυίας εἰρήνης· οὐ γὰρ ἔνεστ’ εἰπεῖν οὔτ’ ἀληθεστέραν οὔτε καλλίω πρόφασιν τοῦ τῆς τῶν τετελευτηκότων ἀγασθέντ’ ἀρετῆς τὸν τῶν ἐναντίων κύριον φίλον γενέσθαι τοῖς ἐκείνων οἰκείοις βούλεσθαι μᾶλλον ἢ πάλιν τὸν ὑπὲρ τῶν ὅλων κίνδυνον ἄρασθαι.", "st": "60.20"}, {"sp": "N", "t": "οἶμαι δ’ ἄν, εἴ τις αὐτοὺς τοὺς παραταξαμένους ἐρωτήσειεν πότερ’ ἡγοῦνται ταῖς αὑτῶν ἀρεταῖς ἢ τῇ παραδόξῳ καὶ χαλεπῇ τύχῃ κατωρθωκέναι καὶ τῇ τοῦ προεστηκότος αὑτῶν ἐμπειρίᾳ καὶ τόλμῃ, οὐδέν’ οὔτ’ ἀναίσχυντον οὔτε τολμηρὸν οὕτως εἶναι, ὅντιν’ ἀντιποιήσεσθαι τῶν πεπραγμένων. ἀλλὰ μὴν ὑπὲρ ὧν ὁ πάντων κύριος δαίμων, ὡς ἐβούλετο, ἔνειμε τὸ τέλος, ἅπαντας ἀφεῖσθαι κακίας ἀνάγκη τοὺς λοιπούς, ἀνθρώπους γ’ ὄντας· [περὶ ὧν δ’ ὁ τῶν ἐναντίων ἡγεμὼν ὑπερῆρε τοὺς ἐπὶ τούτῳ ταχθέντας, οὐχὶ τοὺς πολλοὺς οὔτ’ ἐκείνων οὔθ’ ἡμῶν]", "st": "60.21"}, {"sp": "N", "t": "[αἰτιάσαιτ’ ἄν τις εἰκότως] εἰ δ’ ἄρ’ ἔστι τις ἀνθρώπων ὅτῳ περὶ τούτων ἐγκαλέσαι προσήκει, τοῖς ἐπὶ τούτῳ ταχθεῖσιν Θηβαίων, οὐχὶ τοῖς πολλοῖς οὔτ’ ἐκείνων οὔθ’ ἡμῶν ἐγκαλέσειεν ἄν τις εἰκότως· οἳ δύναμιν λαβόντες ἔχουσαν θυμὸν ἀήττητον καὶ ἀπροφάσιστον καὶ φιλοτιμίαν ἐφάμιλλον οὐδενὶ τούτων ὀρθῶς ἐχρήσαντο.", "st": "60.22"}, {"sp": "N", "t": "καὶ τὰ μὲν ἄλλ’ ἔστιν τούτων ὡς ἕκαστος ἔχει γνώμης, οὕτως ὑπολαμβάνειν· ὃ δ’ ἅπασιν ὁμοίως τοῖς οὖσιν ἀνθρώποις γεγένηται φανερόν, ὅτι ἡ πάσης τῆς Ἑλλάδος ἄρ’ ἐλευθερία ἐν ταῖς τῶνδε τῶν ἀνδρῶν ψυχαῖς διεσῴζετο· ἐπειδὴ γοῦν ἡ πεπρωμένη τούτους ἀνεῖλεν, οὐδεὶς ἀντέστη τῶν λοιπῶν. καὶ φθόνος μὲν ἀπείη τοῦ λόγου, δοκεῖ δέ μοί τις ἂν εἰπὼν ὡς ἡ τῶνδε τῶν ἀνδρῶν ἀρετὴ τῆς Ἑλλάδος ἦν ψυχὴ τἀληθὲς εἰπεῖν·", "st": "60.23"}, {"sp": "N", "t": "ἅμα γὰρ τά τε τούτων πνεύματ’ ἀπηλλάγη τῶν οἰκείων σωμάτων, καὶ τὸ τῆς Ἑλλάδος ἀξίωμ’ ἀνῄρηται. μεγάλην μὲν οὖν ἴσως ὑπερβολὴν δόξομεν λέγειν, ῥητέον δ’ ὅμως· ὥσπερ γάρ, εἴ τις ἐκ τοῦ καθεστηκότος κόσμου τὸ φῶς ἐξέλοι, δυσχερὴς καὶ χαλεπὸς ἅπας ὁ λειπόμενος ἂν ἡμῖν βίος γένοιτο, οὕτω τῶνδε τῶν ἀνδρῶν ἀναιρεθέντων ἐν σκότει καὶ πολλῇ δυσκλείᾳ πᾶς ὁ πρὸ τοῦ ζῆλος τῶν Ἑλλήνων γέγονεν.", "st": "60.24"}, {"sp": "N", "t": "διὰ πολλὰ δ’ εἰκότως ὄντες τοιοῦτοι, διὰ τὴν πολιτείαν οὐχ ἥκιστ’ ἦσαν σπουδαῖοι. αἱ μὲν γὰρ διὰ τῶν ὀλίγων δυναστεῖαι δέος μὲν ἐνεργάζονται τοῖς πολίταις, αἰσχύνην δ’ οὐ παριστᾶσιν· ἡνίκ’ ἂν οὖν ὁ ἀγὼν ἔλθῃ τοῦ πολέμου, πᾶς τις εὐχερῶς ἑαυτὸν σῴζει, συνειδὼς ὅτι, ἐὰν τοὺς κυρίους ἢ δώροις ἢ δι’ ἄλλης ἡστινοσοῦν ὁμιλίας ἐξαρέσηται, κἂν τὰ δεινότατ’ ἀσχημονήσῃ, μικρὸν ὄνειδος τὸ λοιπὸν αὐτῷ καταστήσεται·", "st": "60.25"}, {"sp": "N", "t": "αἱ δὲ δημοκρατίαι πολλά τ’ ἄλλα καὶ καλὰ καὶ δίκαι’ ἔχουσιν, ὧν τὸν εὖ φρονοῦντ’ ἀντέχεσθαι δεῖ, καὶ τὴν παρρησίαν ἐκ τῆς ἀληθείας ἠρτημένην οὐκ ἔστι τἀληθὲς δηλοῦν ἀποτρέψαι. οὔτε γὰρ πάντας ἐξαρέσασθαι τοῖς αἰσχρόν τι ποιήσασιν δυνατόν, οὔτε μόνος ὁ τἀληθὲς ὄνειδος λέγων λυπεῖ· καὶ γὰρ οἱ μηδὲν ἂν εἰπόντες αὐτοὶ βλάσφημον ἄλλου γε λέγοντος χαίρουσιν ἀκούοντες. ἃ φοβούμενοι πάντες εἰκότως τῇ τῶν μετὰ ταῦτ’ ὀνειδῶν αἰσχύνῃ τόν τε προσιόντ’ ἀπὸ τῶν ἐναντίων κίνδυνον εὐρώστως ὑπέμειναν, καὶ θάνατον καλὸν εἵλοντο μᾶλλον ἢ βίον αἰσχρόν.", "st": "60.26"}, {"sp": "N", "t": "ἃ μὲν οὖν κοινῇ πᾶσιν ὑπῆρχεν τοῖσδε τοῖς ἀνδράσιν εἰς τὸ καλῶς ἐθέλειν ἀποθνῄσκειν, εἴρηται, γένος, παιδεία, χρηστῶν ἐπιτηδευμάτων συνήθεια, τῆς ὅλης πολιτείας ὑπόθεσις· ἃ δὲ κατὰ φυλὰς παρεκάλεσεν ἑκάστους εὐρώστους εἶναι, ταῦτ’ ἤδη λέξω. ᾔδεσαν πάντες Ἐρεχθεῖδαι τὸν ἐπώνυμον ⟨τὸν⟩ αὑτῶν Ἐρεχθέα, ἕνεκα τοῦ σῷσαι τὴν χώραν τὰς αὑτοῦ παῖδας, ἃς Ὑακινθίδας καλοῦσιν, εἰς προῦπτον θάνατον δόντ’ ἀναλῶσαι. αἰσχρὸν οὖν ἡγοῦντο τὸν μὲν ἀπ’ ἀθανάτων πεφυκότα πάντα ποιεῖν ἕνεκα τοῦ τὴν πατρίδ’ ἐλευθερῶσαι, αὐτοὶ δὲ φανῆναι θνητὸν σῶμα ποιούμενοι περὶ πλείονος ἢ δόξαν ἀθάνατον.", "st": "60.27"}, {"sp": "N", "t": "οὐκ ἠγνόουν Αἰγεῖδαι Θησέα τὸν Αἰγέως πρῶτον ἰσηγορίαν καταστησάμενον τῇ πόλει. δεινὸν οὖν ἡγοῦντο τὴν ἐκείνου προδοῦναι προαίρεσιν, καὶ τεθνάναι μᾶλλον ᾑροῦνθ’ ἢ καταλυομένης ταύτης παρὰ τοῖς Ἕλλησιν ζῆν φιλοψυχήσαντες. παρειλήφεσαν Πανδιονίδαι Πρόκνην καὶ Φιλομήλαν τὰς Πανδίονος θυγατέρας, ὡς ἐτιμωρήσαντο Τηρέα διὰ τὴν εἰς αὑτὰς ὕβριν. οὐ βιωτὸν οὖν ἐνόμιζον αὑτοῖς, εἰ μὴ συγγενῆ φανήσονται τὸν θυμὸν ἔχοντες ἐκείναις, ἐφ’ οἷς τὴν Ἑλλάδ’ ἑώρων ὑβριζομένην.", "st": "60.28"}, {"sp": "N", "t": "ἠκηκόεσαν Λεωντίδαι μυθολογουμένας τὰς Λεὼ κόρας, ὡς ἑαυτὰς ἔδοσαν σφάγιον τοῖς πολίταις ὑπὲρ τῆς χώρας. ὅτε δὴ γυναῖκες ἐκεῖναι τοιαύτην ἔσχον ἀνδρείαν, οὐ θεμιτὸν αὑτοῖς ὑπελάμβανον χείροσιν ἀνδράσιν οὖσιν ἐκείνων φανῆναι. ἐμέμνηντ’ Ἀκαμαντίδαι τῶν ἐπῶν ἐν οἷς Ὅμηρος ἕνεκα τῆς μητρός φησιν Αἴθρας Ἀκάμαντ’ εἰς Τροίαν στεῖλαι. ὁ μὲν οὖν παντὸς ἐπειρᾶτο κινδύνου τοῦ σῷσαι τὴν ἑαυτοῦ μητέρ’ ἕνεκα· οἱ δὲ τοὺς οἴκοι σύμπαντας γονέας πῶς οὐκ ἤμελλον ὑπὲρ τοῦ σῷσαι πάντα κίνδυνον ὑπομένειν;", "st": "60.29"}, {"sp": "N", "t": "οὐκ ἐλάνθανεν Οἰνείδας ὅτι Κάδμου μὲν Σεμέλη, τῆς δ’ ὃν οὐ πρέπον ἐστὶν ὀνομάζειν ἐπὶ τοῦδε τοῦ τάφου, τοῦ δ’ Οἰνεὺς γέγονεν, ὃς ἀρχηγὸς αὐτῶν ἐκαλεῖτο. κοινοῦ δ’ ὄντος ἀμφοτέραις ταῖς πόλεσιν τοῦ παρόντος κινδύνου, ὑπὲρ ἀμφοτέρων ἅπασαν ᾤοντο δεῖν ἀγωνίαν ἐκτεῖναι. ᾔδεσαν Κεκροπίδαι τὸν ἑαυτῶν ἀρχηγὸν τὰ μὲν ὡς ἔστιν δράκων, τὰ δ’ ὡς ἔστιν ἄνθρωπος λεγόμενον, οὐκ ἄλλοθέν ποθεν ἢ τῷ τὴν σύνεσιν αὐτοῦ προσομοιοῦν ἀνθρώπῳ, τὴν ἀλκὴν δὲ δράκοντι. ἄξια δὴ τούτων πράττειν ὑπελάμβανον αὑτοῖς προσήκειν.", "st": "60.30"}, {"sp": "N", "t": "ἐμέμνηνθ’ Ἱπποθωντίδαι τῶν Ἀλόπης γάμων, ἐξ ὧν Ἱπποθῶν ἔφυ, καὶ τὸν ἀρχηγὸν ᾔδεσαν· ὧν, τὸ πρέπον φυλάττων ἐγὼ τῷδε τῷ καιρῷ, τὸ σαφὲς εἰπεῖν ὑπερβαίνω. ἄξια δὴ τούτων ᾤοντο δεῖν ποιοῦντες ὀφθῆναι. οὐκ ἐλάνθανεν Αἰαντίδας ὅτι τῶν ἀριστείων στερηθεὶς Αἴας ἀβίωτον ἑαυτῷ ἡγήσατο τὸν βίον. ἡνίκ’ οὖν ὁ δαίμων ἄλλῳ τἀριστεῖ’ ἐδίδου, τότε τοὺς ἐχθροὺς ἀμυνόμενοι τεθνάναι δεῖν ᾤοντο, ὥστε μηδὲν ἀνάξιον αὑτῶν παθεῖν. οὐκ ἠμνημόνουν Ἀντιοχίδαι Ἡρακλέους ὄντ’ Ἀντίοχον. δεῖν οὖν ἡγήσαντ’ ἢ ζῆν ἀξίως τῶν ὑπαρχόντων ἢ τεθνάναι καλῶς.", "st": "60.31"}, {"sp": "N", "t": "οἱ μὲν οὖν ζῶντες οἰκεῖοι τούτων ἐλεινοί, τοιούτων ἀνδρῶν ἐστερημένοι καὶ συνηθείας πολλῆς καὶ φιλανθρώπου διεζευγμένοι, καὶ τὰ τῆς πατρίδος πράγματ’ ἔρημα καὶ δακρύων καὶ πένθους πλήρη· οἱ δ’ εὐδαίμονες τῷ δικαίῳ λογισμῷ. πρῶτον μὲν ἀντὶ μικροῦ χρόνου πολὺν καὶ τὸν ἅπαντ’ εὔκλειαν ἀγήρω καταλείπουσιν, ἐν ᾗ καὶ παῖδες οἱ τούτων ὀνομαστοὶ τραφήσονται καὶ γονεῖς [οἱ τούτων] περίβλεπτοι γηροτροφήσονται, παραψυχὴν τῷ πένθει τὴν τούτων εὔκλειαν ἔχοντες.", "st": "60.32"}, {"sp": "N", "t": "ἔπειτα νόσων ἀπαθεῖς τὰ σώματα καὶ λυπῶν ἄπειροι τὰς ψυχάς, ἃς ἐπὶ τοῖς συμβεβηκόσιν οἱ ζῶντες ἔχουσιν, ἐν μεγάλῃ τιμῇ καὶ πολλῷ ζήλῳ τῶν νομιζομένων τυγχάνουσιν. οὓς γὰρ ἅπασα μὲν ἡ πατρὶς θάπτει δημοσίᾳ, κοινῶν δ’ ἐπαίνων μόνοι τυγχάνουσιν, ποθοῦσι δ’ οὐ μόνοι συγγενεῖς καὶ πολῖται, ἀλλὰ πᾶσαν ὅσην Ἑλλάδα χρὴ προσειπεῖν, συμπεπένθηκεν δὲ καὶ τῆς οἰκουμένης τὸ πλεῖστον μέρος, πῶς οὐ χρὴ τούτους εὐδαίμονας νομίζεσθαι;", "st": "60.33"}, {"sp": "N", "t": "οὓς παρέδρους εἰκότως ἄν τις φήσαι τοῖς κάτω θεοῖς εἶναι, τὴν αὐτὴν τάξιν ἔχοντας τοῖς προτέροις ἀγαθοῖς ἀνδράσιν ἐν μακάρων νήσοις. οὐ γὰρ ἰδών τις οὐδὲ περὶ ἐκείνων ταῦτ’ ἀπήγγελκεν, ἀλλ’ οὓς οἱ ζῶντες ἀξίους ὑπειλήφαμεν τῶν ἄνω τιμῶν, τούτους τῇ δόξῃ καταμαντευόμενοι κἀκεῖ τῶν αὐτῶν τιμῶν ἡγούμεθ’ αὐτοὺς τυγχάνειν.", "st": "60.34"}, {"sp": "N", "t": "ἔστι μὲν οὖν ἴσως χαλεπὸν τὰς παρούσας συμφορὰς λόγῳ κουφίσαι· δεῖ δ’ ὅμως πειρᾶσθαι καὶ πρὸς τὰ παρηγοροῦντα τρέπειν τὴν ψυχήν, ὡς τοὺς τοιούτους ἄνδρας γεγεννηκότας καὶ πεφυκότας αὐτοὺς ἐκ τοιούτων ἑτέρων καλόν ἐστιν τὰ δείν’ εὐσχημονέστερον τῶν ἄλλων φέροντας ὁρᾶσθαι καὶ πάσῃ τύχῃ χρωμένους ὁμοίους εἶναι.", "st": "60.35"}, {"sp": "N", "t": "καὶ γὰρ ἐκείνοις ταῦτ’ ἂν εἴη μάλιστ’ ἐν κόσμῳ καὶ τιμῇ, καὶ πάσῃ τῇ πόλει καὶ τοῖς ζῶσιν ταῦτ’ ἂν ἐνέγκοι πλείστην εὐδοξίαν. χαλεπὸν πατρὶ καὶ μητρὶ παίδων στερηθῆναι καὶ ἐρήμοις εἶναι τῶν οἰκειοτάτων γηροτρόφων· σεμνὸν δέ γ’ ἀγήρως τιμὰς καὶ μνήμην ἀρετῆς δημοσίᾳ κτησαμένους ἐπιδεῖν, καὶ θυσιῶν καὶ ἀγώνων ἠξιωμένους ἀθανάτων.", "st": "60.36"}, {"sp": "N", "t": "λυπηρὸν παισὶν ὀρφανοῖς γεγενῆσθαι πατρός· καλὸν δέ γε κληρονομεῖν πατρῴας εὐδοξίας. καὶ τοῦ μὲν λυπηροῦ τούτου τὸν δαίμον’ αἴτιον εὑρήσομεν ὄντα, ᾧ φύντας ἀνθρώπους εἴκειν ἀνάγκη, τοῦ δὲ τιμίου καὶ καλοῦ τὴν τῶν ἐθελησάντων καλῶς ἀποθνῄσκειν αἵρεσιν.", "st": "60.37"}, {"sp": "N", "t": "ἐγὼ μὲν οὖν οὐχ ὅπως πολλὰ λέξω, τοῦτ’ ἐσκεψάμην, ἀλλ’ ὅπως τἀληθῆ. ὑμεῖς δ’ ἀποδυράμενοι καὶ τὰ προσήκονθ’ ὡς χρὴ καὶ νόμιμα ποιήσαντες ἄπιτε.", "st": "60.37"}, {"sp": "HDR", "t": "Ἐρωτικὸς", "st": "61"}, {"sp": "N", "t": "ἀλλ’ ἐπειδήπερ ἀκούειν βούλει τοῦ λόγου, δείξω σοι καὶ ἀναγνώσομαι. δεῖ δέ σε τὴν προαίρεσιν αὐτοῦ πρῶτον εἰδέναι. βούλεται μὲν γὰρ ὁ τὸν λόγον ποιῶν ἐπαινεῖν Ἐπικράτην, ὃν ᾤετο πολλῶν καὶ καλῶν κἀγαθῶν ὄντων νέων ἐν τῇ πόλει χαριέστατον εἶναι, καὶ πλέον τῇ συνέσει προέχειν ἢ τῷ κάλλει τῶν ἡλικιωτῶν. ὁρῶν δ’ ὡς ἔπος εἰπεῖν τὰ πλεῖστα τῶν ἐρωτικῶν συνταγμάτων αἰσχύνην μᾶλλον ἢ τιμὴν περιάπτοντα τούτοις περὶ ὧν ἐστι γεγραμμένα, τοῦθ’ ὅπως μὴ πείσεται πεφύλακται, καὶ ὅπερ καὶ πεπεῖσθαί φησιν τῇ γνώμῃ, τοῦτο καὶ γέγραφεν, ὡς δίκαιος ἐραστὴς οὔτ’ ἂν ποιήσειεν οὐδὲν αἰσχρὸν οὔτ’ ἀξιώσειεν. ὃ μὲν οὖν ὡσπερεὶ μάλιστ’ ἂν ἐρωτικὸν λάβοις τοῦ λόγου,", "st": "61.1"}, {"sp": "N", "t": "περὶ τοῦτ’ ἔστιν· ὁ δ’ ἄλλος λόγος τὰ μὲν αὐτὸν ἐπαινεῖ τὸν νεανίσκον, τὰ δ’ αὐτῷ συμβουλεύει περὶ παιδείας τε καὶ προαιρέσεως τοῦ βίου. πάντα δὲ ταῦτα γέγραπται τὸν τρόπον ὅν τις ἂν εἰς βιβλίον καταθεῖτο. τοῖς μὲν γὰρ λεκτικοῖς τῶν λόγων ἁπλῶς καὶ ὁμοίως οἷς ἂν ἐκ τοῦ παραχρῆμά τις εἴποι πρέπει γεγράφθαι, τοῖς δ’ εἰς τὸν πλείω χρόνον τεθησομένοις ποιητικῶς καὶ περιττῶς ἁρμόττει συγκεῖσθαι· τοὺς μὲν γὰρ πιθανούς, τοὺς δ’ ἐπιδεικτικοὺς εἶναι προσήκει. ἵν’ οὖν μὴ παρὰ τὸν λόγον σοι λέγω, μηδ’ ἃ γιγνώσκω περὶ τούτων αὐτὸς διεξίω, πρόσεχ’ ὡς αὐτοῦ τοῦ λόγου ἤδη ἀκουσόμενος, ἐπειδὴ καὶ αὐτὸς ἥκει, ὃν ἠβουλήθην ἀκούειν, Ἐπικράτης.", "st": "61.2"}, {"sp": "N", "t": "ὁρῶν ἐνίους τῶν ἐρωμένων καὶ κάλλους μετεσχηκότων οὐδετέρᾳ τῶν εὐτυχιῶν τούτων ὀρθῶς χρωμένους, ἀλλ’ ἐπὶ μὲν τῇ τῆς ὄψεως εὐπρεπείᾳ σεμνυνομένους, τὴν δὲ πρὸς τοὺς ἐραστὰς ὁμιλίαν δυσχεραίνοντας, καὶ τοσοῦτον διημαρτηκότας τοῦ τὰ βέλτιστα κρίνειν ὥστε διὰ τοὺς λυμαινομένους τῷ πράγματι καὶ πρὸς τοὺς μετὰ σωφροσύνης πλησιάζειν ἀξιοῦντας δυσκόλως διακειμένους, ἡγησάμην τοὺς μὲν τοιούτους οὐ μόνον αὑτοῖς ἀλυσιτελῶς ἔχειν, ἀλλὰ καὶ τοῖς ἄλλοις μοχθηρὰς συνηθείας ἐνεργάζεσθαι,", "st": "61.3"}, {"sp": "N", "t": "τοῖς δὲ καλῶς φρονοῦσιν οὐκ ἐπακολουθητέον εἶναι τῇ τούτων ἀπονοίᾳ, μάλιστα μὲν ἐνθυμουμένοις ὅτι τῶν πραγμάτων οὔτε καλῶν οὔτ’ αἰσχρῶν ἀποτόμως ὄντων, ἀλλὰ παρὰ τοὺς χρωμένους τὸ πλεῖστον διαλλαττόντων, ἄλογον μιᾷ γνώμῃ περὶ ἀμφοτέρων χρῆσθαι, ἔπειθ’ ὅτι πάντων ἀτοπώτατόν ἐστιν ζηλοῦν μὲν τοὺς πλείστους φίλους καὶ βεβαιοτάτους ἔχοντας, ἀποδοκιμάζειν δὲ τοὺς ἐραστάς, ὃ μόνον ἴδιον ἔθνος οὐχ ἅπασιν ἀλλὰ τοῖς καλοῖς καὶ σώφροσιν οἰκειοῦσθαι πέφυκεν.", "st": "61.4"}, {"sp": "N", "t": "ἔτι δὲ τοῖς μὲν μηδεμίαν πω τοιαύτην φιλίαν ἑορακόσιν καλῶς ἀποβᾶσαν, ἢ σφόδρα κατεγνωκόσιν αὑτῶν ὡς οὐκ ἂν δυνηθεῖεν σωφρόνως τοῖς ἐντυγχάνουσιν ὁμιλεῖν, ἴσως οὐκ ἄλογον ταύτην ἔχειν τὴν διάνοιαν· τοῖς δ’ ὥσπερ σὺ διακειμένοις, καὶ μήτε παντάπασιν ἀνηκόοις οὖσιν ὅσαι δὴ χρεῖαι δι’ ἔρωτος χωρὶς αἰσχύνης ηὐξήθησαν, καὶ μετὰ τῆς ἀκριβεστάτης εὐλαβείας τὸν ἄλλον χρόνον βεβιωκόσιν, οὐδ’ ὑποψίαν ἔχειν εὔλογον ὡς ἄν τι πράξειαν αἰσχρόν.", "st": "61.5"}, {"sp": "N", "t": "διὸ δὴ καὶ μᾶλλον ἐπήρθην τοῦτον γράψαι τὸν λόγον, ἡγούμενος δυοῖν τοῖν καλλίστοιν οὐ διαμαρτήσεσθαι. τὰ μὲν γὰρ ὑπάρχοντά σοι ἀγαθὰ διελθὼν ἅμα σέ τε ζηλωτὸν καὶ ἐμαυτὸν οὐκ ἀνόητον ἐπιδείξειν ἐλπίζω, εἴ σε τοιοῦτον ὄντ’ ἀγαπῶ· συμβουλεύσας δ’ ἃ μάλιστα κατεπείγει, νομίζω τῆς μὲν εὐνοίας τῆς ἐμῆς δεῖγμα, τῆς δὲ κοινῆς φιλίας ἀφορμὴν ἀμφοτέροις εἰσοίσειν.", "st": "61.6"}, {"sp": "N", "t": "καίτοι μ’ οὐ λέληθεν ὅτι χαλεπὸν μέν ἐστιν καὶ τὴν σὴν φύσιν ἀξίως τῶν ὑπαρχόντων διελθεῖν, ἔτι δ’ ἐπικινδυνότερον τὸ συμβουλεύειν μέλλονθ’ αὑτὸν ὑπεύθυνον τῷ πεισθέντι καταστῆσαι. ἀλλὰ νομίζω τοῖς μὲν δικαίως ἐγκωμίων τυγχάνουσιν περιγενέσθαι τῆς τῶν ἐπαινούντων δυνάμεως προσήκειν τῇ τῆς ἀληθείας ὑπερβολῇ, τῆς δὲ συμβουλῆς οὐ διαμαρτήσεσθαι, συνειδὼς ὅτι διὰ μὲν ἀνοήτων καὶ παντελῶς ὑπ’ ἀκρασίας διεφθαρμένων οὐδὲ τῶν καθ’ ὑπερβολὴν ὀρθῶς βουλευθέντων οὐδὲν ἂν καλῶς ἐξενεχθείη, διὰ δὲ τῶν σωφρόνως καὶ καθαρῶς ζῆν αἱρουμένων οὐδὲ τὰ μετρίως ἐσκεμμένα διαμαρτάνεσθαι πέφυκεν.", "st": "61.7"}, {"sp": "N", "t": "τὰς μὲν οὖν ἐλπίδας ἔχων τοιαύτας ἐγχειρῶ τῷ λόγῳ· ἡγοῦμαι δὲ πάντας ἂν ὁμολογῆσαί μοι τοῖς τηλικούτοις μάλιστα κατεπείγειν κάλλος μὲν ἐπὶ τῆς ὄψεως, σωφροσύνην δ’ ἐπὶ τῆς ψυχῆς, ἀνδρείαν δ’ ἐπ’ ἀμφοτέρων τούτων, χάριν δ’ ἐπὶ τῶν λόγων διατελεῖν ἔχοντας. ὧν τὰ μὲν τῆς φύσεως οὕτω καλῶς ἡ τύχη σοι παραδέδωκεν ὥστε περίβλεπτον καὶ θαυμαζόμενον διατελεῖν, τὰ δ’ αὐτὸς παρὰ τὴν ἐπιμέλειαν εἰς τοῦτο προαγαγὼν ἥκεις ὥστε μηδέν’ ἄν σοι τῶν εὖ φρονούντων ἐπιτιμῆσαι.", "st": "61.8"}, {"sp": "N", "t": "καίτοι τί χρὴ τὸν τῶν μεγίστων ἐπαίνων ἄξιον; οὐχ ὑπὸ μὲν τῶν θεῶν ἠγαπημένον φαίνεσθαι, παρὰ δὲ τοῖς ἀνθρώποις τὰ μὲν δι’ αὑτόν, τὰ δὲ διὰ τὴν τύχην θαυμάζεσθαι; καθ’ ὅλου μὲν τοίνυν τῶν ὑπαρχόντων σοι πρὸς ἀρετὴν ἴσως ὕστερον ἁρμόσει τὰ πλείω διελθεῖν· ἃ δ’ ἑκάστου τούτων ἐγκώμι’ εἰπεῖν ἔχω, ταῦτα δηλῶσαι πειράσομαι μετ’ ἀληθείας.", "st": "61.9"}, {"sp": "N", "t": "ἄρξομαι δὲ πρῶτον ἐπαινεῖν, ὅπερ πρῶτον ἰδοῦσιν ἅπασιν ἔστιν γνῶναί σου, τὸ κάλλος, καὶ τούτου τὸ χρῶμα, δι’ οὗ καὶ τὰ μέλη καὶ ὅλον τὸ σῶμα φαίνεται. ᾧ τίν’ ἁρμόττουσαν εἰκόν’ ἐνέγκω σκοπῶν οὐχ ὁρῶ, ἀλλὰ παρίσταταί μοι δεῖσθαι τῶν ἀναγνόντων τόνδε τὸν λόγον σὲ θεωρῆσαι καὶ ἰδεῖν, ἵνα συγγνώμης τύχω μηδὲν ὅμοιον ἔχων εἰπεῖν.", "st": "61.10"}, {"sp": "N", "t": "τῷ γὰρ ⟨ἂν⟩ εἰκάσειέ τις, ὃ θνητὸν ὂν ἀθάνατον τοῖς ἰδοῦσιν ἐνεργάζεται πόθον, καὶ ὁρώμενον οὐκ ἀποπληροῖ, καὶ μεταστὰν μνημονεύεται, καὶ τὴν τῶν θεῶν ἀξίαν ἐπ’ ἀνθρώπου φύσιν ἔχει, πρὸς μὲν τὴν εὐπρέπειαν ἀνθηρόν, πρὸς δὲ τὰς αἰτίας ἀνυπονόητον; ἀλλὰ μὴν οὐδὲ ταῦτ’ ἔστιν αἰτιάσασθαι [πρὸς] τὴν σὴν ὄψιν, ἃ πολλοῖς ἄλλοις ἤδη συνέπεσεν τῶν κάλλους μετασχόντων.", "st": "61.11"}, {"sp": "N", "t": "ἢ γὰρ δι’ ἀρρυθμίαν τοῦ σχήματος ἅπασαν συνετάραξαν τὴν ὑπάρχουσαν εὐπρέπειαν, ἢ δι’ ἀτύχημά τι καὶ τὰ καλῶς πεφυκότα συνδιέβαλον αὐτῷ. ὧν οὐδενὶ τὴν σὴν ὄψιν εὕροιμεν ἂν ἔνοχον γεγενημένην· οὕτω γὰρ σφόδρ’ ἐφυλάξατο πάσας τὰς τοιαύτας κῆρας ὅστις ποτ’ ἦν θεῶν ὁ τῆς σῆς ὄψεως προνοηθείς, ὥστε μηδὲν μέμψεως ἄξιον, τὰ δὲ πλεῖστα περίβλεπτά σου καταστῆσαι.", "st": "61.12"}, {"sp": "N", "t": "καὶ μὲν δὴ καὶ τῶν ὁρωμένων ἐπιφανεστάτου μὲν ὄντος τοῦ προσώπου, τούτου δ’ αὐτοῦ τῶν ὀμμάτων, ἔτι μᾶλλον ἐν τούτοις ἐπεδείξατο τὴν εὔνοιαν ἣν εἶχεν εἰς σὲ τὸ δαιμόνιον. οὐ γὰρ μόνον πρὸς τὸ τὰ κατεπείγονθ’ ὁρᾶν αὐτάρκη παρέσχηται, ἀλλ’ ἐνίων οὐδ’ ἐκ τῶν πραττομένων γιγνωσκομένης τῆς ἀρετῆς, σοῦ διὰ τῶν τῆς ὄψεως σημείων τὰ κάλλιστα τῶν ἠθῶν ἐνεφάνισεν, πρᾶον μὲν καὶ φιλάνθρωπον τοῖς ὁρῶσιν, μεγαλοπρεπῆ δὲ καὶ σεμνὸν τοῖς ὁμιλοῦσιν, ἀνδρεῖον δὲ καὶ σώφρονα πᾶσιν ἐπιδείξας.", "st": "61.13"}, {"sp": "N", "t": "ὃ καὶ μάλιστ’ ἄν τις θαυμάσειεν· τῶν γὰρ ἄλλων ἐπὶ μὲν τῆς πραότητος ταπεινῶν, ἐπὶ δὲ τῆς σεμνότητος αὐθαδῶν ὑπολαμβανομένων, καὶ διὰ μὲν τὴν ἀνδρείαν θρασυτέρων, διὰ δὲ τὴν ἡσυχίαν ἀβελτέρων εἶναι δοκούντων, τοσαύτας ὑπεναντιώσεις πρὸς ἄλληλα λαβοῦσ’ ἡ τύχη πρὸς τὸ δέον ἅπανθ’ ὁμολογούμεν’ ἀπέδωκεν, ὥσπερ εὐχὴν ἐπιτελοῦσ’ ἢ παράδειγμα τοῖς ἄλλοις ὑποδεῖξαι βουληθεῖσα, ἀλλ’ οὐ θνητήν, ὡς εἴθιστο, φύσιν συνιστᾶσα.", "st": "61.14"}, {"sp": "N", "t": "εἰ μὲν οὖν οἷόν τ’ ἦν ἐφικέσθαι τῷ λόγῳ τοῦ κάλλους τοῦ σοῦ, ἢ τοῦτ’ ἦν μόνον τῶν σῶν ἀξιέπαινον, οὐδὲν ἂν παραλιπεῖν ᾠόμεθα δεῖν ἐπαινοῦντες τῶν προσόντων· νῦν δὲ δέδοικα μὴ πρός ⟨τε⟩ τὰ λοίπ’ ἀπειρηκόσι χρησώμεθα τοῖς ἀκροαταῖς, καὶ περὶ τούτου μάτην τερθρευώμεθα.", "st": "61.15"}, {"sp": "N", "t": "πῶς γὰρ ἄν τις ὑπερβάλοι τῷ λόγῳ τὴν σὴν ὄψιν, ἧς μηδ’ ἃ τέχνῃ πεποίηται τῶν ἔργων τοῖς ἀρίστοις δημιουργοῖς δύναται ὑπερτεῖναι; καὶ θαυμαστὸν οὐδέν· τὰ μὲν γὰρ ἀκίνητον ἔχει τὴν θεωρίαν, ὥστ’ ἄδηλ’ εἶναι τί ποτ’ ἂν ψυχῆς μετασχόντα φανείη, σοῦ δὲ τὸ τῆς γνώμης ἦθος ἐν πᾶσιν οἷς ποιεῖς μεγάλην εὐπρέπειαν ἐπαυξάνει τῷ σώματι. περὶ μὲν οὖν τοῦ κάλλους πολλὰ παραλιπών, τοσαῦτ’ ἐπαινέσαι ἔχω.", "st": "61.16"}, {"sp": "N", "t": "περὶ δὲ τῆς σωφροσύνης κάλλιστον μὲν τοῦτ’ ἔχοιμ’ ἂν εἰπεῖν, ὅτι τῆς ἡλικίας τῆς τοιαύτης εὐδιαβόλως ἐχούσης, σοὶ μᾶλλον ἐπαινεῖσθαι συμβέβηκεν. οὐ γὰρ μόνον οὐδὲν ἐξαμαρτάνειν, ἀλλὰ καὶ φρονιμώτερον ἢ κατὰ τὴν ὥραν ζῆν προῄρησαι. καὶ τούτου μέγιστον τεκμήριον ἡ πρὸς τοὺς ἀνθρώπους ὁμιλία· πολλῶν γὰρ ἐντυγχανόντων σοι καὶ παντοδαπὰς φύσεις ἐχόντων, ἔτι δὲ προσαγομένων ἁπάντων ἐπὶ τὰς ἑαυτῶν συνηθείας, οὕτω καλῶς προέστης τῶν τοιούτων ὥστε πάντας τὴν πρὸς σὲ φιλίαν ἠγαπηκότας ἔχειν.", "st": "61.17"}, {"sp": "N", "t": "ὃ σημεῖον τῶν ἐνδόξως καὶ φιλανθρώπως ζῆν προαιρουμένων ἐστίν. καίτοι τινὲς ηὐδοκίμησαν ἤδη τῶν τε συμβουλευσάντων ὡς οὐ χρὴ τὰς τῶν τυχόντων ὁμιλίας προσδέχεσθαι, καὶ τῶν πεισθέντων τούτοις· ἢ γὰρ πρὸς χάριν ὁμιλοῦντα τοῖς φαύλοις ἀναγκαῖον εἶναι διαβάλλεσθαι παρὰ τοῖς πολλοῖς, ἢ διευλαβούμενον τὰς τοιαύτας ἐπιπλήξεις ὑπ’ αὐτῶν τῶν ἐντυγχανόντων δυσχεραίνεσθαι συμπίπτειν.", "st": "61.18"}, {"sp": "N", "t": "ἐγὼ δὲ διὰ τοῦτο καὶ μᾶλλον οἶμαί σε δεῖν ἐγκωμιάζειν, ὅτι τῶν ἄλλων ἕν τι τῶν ἀδυνάτων οἰομένων εἶναι τὸ τοῖς ἁπάντων τρόποις ἀρέσκειν, σὺ τοσοῦτο τούτων διήνεγκας ὥστε τῶν χαλεπῶν καὶ δυσκόλων ἁπάντων περιγεγενῆσθαι, τοῦ μὲν συνεξαμαρτάνειν τισὶν οὐδ’ ὑποψίαν ἐνδοὺς τοῖς ἄλλοις, τῆς δὲ πρὸς αὐτοὺς δυσχερείας τῇ τῶν τρόπων εὐαρμοστίᾳ κρατήσας.", "st": "61.19"}, {"sp": "N", "t": "πρὸς τοίνυν τοὺς ἐραστάς, εἰ χρὴ καὶ περὶ τούτων εἰπεῖν, οὕτω καλῶς μοι δοκεῖς καὶ σωφρόνως ὁμιλεῖν, ὥστε τῶν πλείστων οὐδ’ ὃν ἂν προέλωνται μετρίως ἐνεγκεῖν δυναμένων, σοὶ πᾶσιν καθ’ ὑπερβολὴν ἀρέσκειν συμβέβηκεν. ὃ τῆς σῆς ἀρετῆς σημεῖον ἐναργέστατόν ἐστιν. ὧν μὲν γὰρ δίκαιον καὶ καλόν, οὐδεὶς ἄμοιρος αὐτῶν παρὰ σοῦ καθέστηκεν· ἃ δ’ εἰς αἰσχύνην ἥκει, τούτων οὐδ’ εἰς ἐλπίδ’ οὐδεὶς ἔρχεται· τοσαύτην τοῖς μὲν τῶν βελτίστων ὀρεγομένοις ἐξουσίαν, τοῖς δ’ ἀποθρασύνεσθαι βουλομένοις ἀτολμίαν ἡ σὴ σωφροσύνη παρεσκεύακεν.", "st": "61.20"}, {"sp": "N", "t": "ἔτι τοίνυν τῶν πλείστων ἐκ τῆς σιωπῆς, ὅταν ὦσι νέοι, τὴν τῆς σωφροσύνης δόξαν θηρωμένων, σὺ τοσοῦτον τῇ φύσει διενήνοχας, ὥστ’ ἐξ ὧν λέγεις καὶ ὁμιλεῖς τοῖς ἐντυγχάνουσι μηδὲν ἐλάττω τὴν περὶ σεαυτὸν εὐδοξίαν ἢ διὰ πάντα τὰ λοιπὰ πεποιῆσθαι· τοσαύτη πειθὼ καὶ χάρις καὶ ἐν οἷς σπουδάζεις ἐστί σοι καὶ ἐν οἷς παίζεις. καὶ γὰρ εὐήθης ἀναμαρτήτως καὶ δεινὸς οὐ κακοήθως καὶ φιλάνθρωπος ἐλευθερίως, καὶ τὸ σύνολον τοιοῦτος εἶ, οἷος ἂν ἐξ Ἀρετῆς υἱὸς Ἔρωτι γένοιτο.", "st": "61.21"}, {"sp": "N", "t": "τὴν τοίνυν ἀνδρείαν (οὐδὲ γὰρ τοῦτ’ ἄξιόν ἐστιν παραλιπεῖν, οὐχ ὡς οὐ πολλὴν ἐπίδοσιν ἐχούσης ἔτι τῆς σῆς φύσεως, καὶ τοῦ μέλλοντος χρόνου πλείους ἀφορμὰς παραδώσοντος λόγων τοῖς ἐπαινεῖν σε βουλομένοις, ἀλλ’ ὡς καλλίστων ὄντων τῶν μετὰ ταύτης τῆς ἡλικίας ἐπαίνων, ἐν ᾗ τὸ μηδὲν ἐξαμαρτάνειν τοῖς ἄλλοις εὐκτόν ἐστι), σοῦ δ’ ἐπὶ πολλῶν μὲν ἄν τις καὶ ἑτέρων τὴν ἀνδρείαν διέλθοι, μάλιστα δ’ ἐπὶ τῆς ἀσκήσεως, ἧς καὶ πλεῖστοι γεγένηνται μάρτυρες.", "st": "61.22"}, {"sp": "N", "t": "ἀνάγκη δ’ ἴσως πρῶτον εἰπεῖν, ταύτην τὴν ἀγωνίαν ὡς καλῶς προείλου. τὸ γὰρ ὀρθῶς, ὅ τι πρακτέον ἐστίν, νέον ὄντα δοκιμάσαι, καὶ ψυχῆς ἀγαθῆς καὶ γνώμης φρονίμου κοινόν ἐστιν σημεῖον· δι’ ὧν οὐδέτερον παραλιπεῖν ἄξιον τὸν τῆς προαιρέσεως ἔπαινον. συνειδὼς τοίνυν τῶν μὲν ἄλλων ἀθλημάτων καὶ δούλους καὶ ξένους μετέχοντας, τοῦ δ’ ἀποβαίνειν μόνοις μὲν τοῖς πολίταις ἐξουσίαν οὖσαν, ἐφιεμένους δὲ τοὺς βελτίστους, οὕτως ἐπὶ τοῦτον τὸν ἀγῶν’ ὥρμησας.", "st": "61.23"}, {"sp": "N", "t": "ἔτι δὲ κρίνων τοὺς μὲν τὰ δρομικὰ γυμναζομένους οὐδὲν πρὸς ἀνδρείαν οὐδ’ εὐψυχίαν ἐπιδιδόναι, τοὺς δὲ τὴν πυγμὴν καὶ τὰ τοιαῦτ’ ἀσκήσαντας πρὸς τῷ σώματι καὶ τὴν γνώμην διαφθείρεσθαι, τὸ σεμνότατον καὶ κάλλιστον τῶν ἀγωνισμάτων καὶ μάλιστα πρὸς τὴν σεαυτοῦ φύσιν ἁρμόττον ἐξελέξω, τῇ μὲν συνηθείᾳ τῶν ὅπλων καὶ τῇ τῶν δρόμων φιλοπονίᾳ τοῖς ἐν τῷ πολέμῳ συμβαίνουσιν ὡμοιωμένον, τῇ δὲ μεγαλοπρεπείᾳ καὶ τῇ σεμνότητι τῆς παρασκευῆς πρὸς τὴν τῶν θεῶν δύναμιν εἰκασμένον,", "st": "61.24"}, {"sp": "N", "t": "πρὸς δὲ τούτοις ἡδίστην μὲν θέαν ἔχον, ἐκ πλείστων δὲ καὶ παντο- δαπῶν συγκείμενον, μεγίστων δ’ ἄθλων ἠξιωμένον· πρὸς γὰρ τοῖς τιθεμένοις τὸ γυμνασθῆναι καὶ μελετῆσαι τοιαῦτ’ οὐ μικρὸν ἆθλον προφανήσεται τοῖς καὶ μετρίως ἀρετῆς ἐφιεμένοις. τεκμήριον δὲ μέγιστον ἄν τις ποιήσαιτο τὴν Ὁμήρου ποίησιν, ἐν ᾗ καὶ τοὺς Ἕλληνας καὶ τοὺς βαρβάρους μετὰ τοιαύτης παρασκευῆς πολεμήσαντας πεποίηκεν ἀλλήλοις· ἔτι δὲ καὶ νῦν τῶν πόλεων τῶν Ἑλληνίδων οὐ ταῖς ταπεινοτάταις, ἀλλὰ ταῖς μεγίσταις ἐν τοῖς ἀγῶσι χρῆσθαι σύνηθές ἐστιν.", "st": "61.25"}, {"sp": "N", "t": "ἡ μὲν οὖν προαίρεσις οὕτω καλὴ καὶ παρὰ πᾶσιν ἀνθρώποις ἠγαπημένη· νομίζων δ’ οὐδὲν εἶναι προὔργου τῶν σπουδαιοτάτων ἐπιθυμεῖν οὐδὲ καλῶς πρὸς ἅπαντα πεφυκέναι τὸ σῶμα μὴ τῆς ψυχῆς φιλοτίμως παρεσκευασμένης, τὴν μὲν φιλοπονίαν ἐν τοῖς γυμνασίοις εὐθέως ἐπιδειξάμενος οὐδ’ ἐν τοῖς ἔργοις ἐψεύσω, τὴν δ’ ἄλλην ἐπιφάνειαν τῆς σαυτοῦ φύσεως καὶ τὴν τῆς ψυχῆς ἀνδρείαν ἐν τοῖς ἀγῶσι μάλιστ’ ἐνεδείξω.", "st": "61.26"}, {"sp": "N", "t": "περὶ ὧν ὀκνῶ μὲν ἄρξασθαι λέγειν, μὴ λειφθῶ τῷ λόγῳ τῶν τότε γεγενημένων, ὅμως δ’ οὐ παραλείψω· καὶ γὰρ αἰσχρὸν ἃ θεωροῦντας ἡμᾶς εὐφραίνει, ταῦτ’ ἀπαγγεῖλαι μὴ ’θέλειν. ἅπαντας μὲν οὖν εἰ διεξιοίην τοὺς ἀγῶνας, ἴσως ἂν ἄκαιρον μῆκος ἡμῖν ἐπιγένοιτο τῷ λόγῳ· ἑνὸς δέ, ἐν ᾧ πολὺ διήνεγκας, μνησθεὶς ταὐτά τε δηλώσω καὶ τῇ τῶν ἀκουόντων δυνάμει συμμετρώτερον φανήσομαι χρώμενος.", "st": "61.27"}, {"sp": "N", "t": "τῶν γὰρ ζευγῶν ἀφεθέντων, καὶ τῶν μὲν προορμησάντων, τῶν δ’ ὑφηνιοχουμένων, ἀμφοτέρων περιγενόμενος ὡς ἑκατέρων προσῆκε, τὴν νίκην ἔλαβες, τοιούτου στεφάνου τυχὼν ἐφ’ ᾧ, καίπερ καλοῦ τοῦ νικᾶν ὄντος, κάλλιον ἐδόκει καὶ παραλογώτερον εἶναι τὸ σωθῆναι. φερομένου γὰρ ἐναντίου μέν σοι τοῦ τῶν ἀντι- πάλων ἅρματος, ἁπάντων δ’ ἀνυπόστατον οἰομένων εἶναι τὴν τῶν ἵππων δύναμιν, ὁρῶν αὐτῶν ἐνίους καὶ μηδενὸς δεινοῦ παρόντος ὑπερηγωνιακότας, οὐχ ὅπως ἐξεπλάγης ἢ κατεδειλίασας, ἀλλὰ τῇ μὲν ἀνδρείᾳ καὶ τῆς τοῦ ζεύγους ὁρμῆς κρείττων ἐγένου, τῷ δὲ τάχει καὶ τοὺς διηυτυχηκότας τῶν ἀνταγωνιστῶν παρῆλθες.", "st": "61.28"}, {"sp": "N", "t": "καὶ γάρ τοι τοσοῦτον μετήλλαξας τῶν ἀνθρώπων τὰς διανοίας ὥστε πολλῶν θρυλούντων ὡς ἐν τοῖς ἱππικοῖς ἀγῶσιν ἡδίστην θέαν παρέχεται τὰ ναυαγοῦντα, καὶ δοκούντων ἀληθῆ ταῦτα λέγειν, ἐπὶ σοῦ τοὐναντίον τοὺς θεατὰς φοβεῖσθαι πάντας μή τι συμπέσῃ τοιοῦτον περὶ σέ· τοσαύτην εὔνοιαν καὶ φιλοτιμίαν ἡ σὴ φύσις αὐτοῖς παρέσχεν.", "st": "61.29"}, {"sp": "N", "t": "εἰκότως· καλὸν μὲν γὰρ καὶ τὸ καθ’ ἕν τι περίβλεπτον γενέσθαι, πολὺ δὲ κάλλιον τὸ πάντα περιλαβεῖν ἐφ’ οἷς ἄν τις νοῦν ἔχων φιλοτιμηθείη. δῆλον δ’ ἐκεῖθεν· εὑρήσομεν γὰρ Αἰακὸν μὲν καὶ Ῥαδάμανθυν διὰ σωφροσύνην, Ἡρακλέα δὲ καὶ Κάστορα καὶ Πολυδεύκην δι’ ἀνδρείαν, Γανυμήδην δὲ καὶ Ἄδωνιν καὶ ἄλλους τοιούτους διὰ κάλλος ὑπὸ θεῶν ἀγαπηθέντας. ὥστ’ ἔγωγ’ οὐ θαυμάζω τῶν ἐπιθυμούντων τῆς σῆς φιλίας, ἀλλὰ τῶν μὴ τοῦτον τὸν τρόπον διακειμένων· ὅπου γὰρ ἑνὸς ἑκάστου τῶν προειρημένων μετασχόντες τινὲς τῆς τῶν θεῶν ὁμιλίας ἠξιώθησαν, ἦ που τοῦ γ’ ἁπάντων κυρίου καταστάντος εὐκτὸν θνητῷ φύντι φίλον γενέσθαι.", "st": "61.30"}, {"sp": "N", "t": "δίκαιον μὲν οὖν καὶ πατέρα καὶ μητέρα καὶ τοὺς ἄλλους οἰκείους τοὺς σοὺς ζηλοῦσθαι, τοσοῦτον ὑπερέχοντος σοῦ τῶν ἡλικιωτῶν ἀρετῇ, πολὺ δὲ μᾶλλον οὓς σὺ ὁ τῶν τηλικούτων ἀγαθῶν ἠξιωμένος σαυτοῦ προκρίνας ἀξίους εἶναι φίλους ἐξ ἁπάντων αἱρεῖ. τοὺς μὲν γὰρ ἡ τύχη σοι μετόχους κατέστησεν, τοὺς δ’ ἡ σφετέρα καλοκἀγαθία προσσυνέστησεν·", "st": "61.31"}, {"sp": "N", "t": "οὓς οὐκ οἶδα πότερον ἐραστὰς ἢ μόνους ὀρθῶς γιγνώσκοντας προσαγορεῦσαι χρή. δοκεῖ γάρ μοι καὶ κατ’ ἀρχὰς ἡ τύχη, τῶν μὲν φαύλων καταφρονοῦσα, τὰς δὲ τῶν σπουδαίων ἀνδρῶν διανοίας ἐρεθίσαι βουληθεῖσα, τὴν σὴν φύσιν οὐ πρὸς ἡδονὴν ἐξαπατηθῆναι καλὴν ποιῆσαι, ἀλλὰ πρὸς ἀρετὴν εὐδαιμονῆσαι χρήσιμον.", "st": "61.32"}, {"sp": "N", "t": "πολλὰ δ’ ἔχων ἔτι περὶ σοῦ διελθεῖν, αὐτοῦ καταλύσειν μοι δοκῶ τὸν ἔπαινον, δεδιὼς μὴ καθ’ ὑπερβολὴν τῆς ἀνθρωπίνης φύσεως ὑπὲρ σοῦ διαλέγεσθαι δόξω· τοσοῦτον γὰρ ὡς ἔοικεν ἡ τῶν λόγων δύναμις ἔλαττον ἔχει τῆς ὄψεως, ὥστε τοῖς μὲν ὁρατοῖς οὐδεὶς ἀπιστεῖν ἀξιοῖ, τοὺς δὲ τούτων ἐπαίνους οὐδ’ ἂν ἐλλείπωσιν ἀληθεῖς εἶναι νομίζουσιν.", "st": "61.33"}, {"sp": "N", "t": "παυσάμενος οὖν περὶ τούτων, ἤδη πειράσομαί σοι συμβουλεύειν ἐξ ὧν ἐντιμότερον ἔτι τὸν σαυτοῦ βίον καταστήσεις. βουλοίμην δ’ ἄν σε μὴ πάρεργον ποιήσασθαι τὸ προσέχειν τὸν νοῦν τοῖς μέλλουσιν ῥηθήσεσθαι, μηδ’ ὑπολαμβάνειν τοῦθ’, ὡς ἄρ’ ἐγὼ τούτοις κέχρημαι τοῖς λόγοις οὐ τῆς σῆς ὠφελίας ἕνεκα, ἀλλ’ ἐπιδείξεως ἐπιθυμῶν, ἵνα μήτε διαμάρτῃς τῆς ἀληθείας, μήτ’ ἀντὶ τῶν βελτίστων τὰ τυχόνθ’ ἑλόμενος χεῖρον περὶ σαυτοῦ βουλεύσῃ.", "st": "61.34"}, {"sp": "N", "t": "καὶ γὰρ τοῖς μὲν ἀφανῆ καὶ ταπεινὴν τὴν φύσιν ἔχουσιν οὐδ’ ὅταν μὴ καλῶς τι πράξωσιν ἐπιπλήττομεν, τοῖς δ’ ὥσπερ σὺ περιβλέπτοις γεγενημένοις καὶ τὸ παραμελῆσαί τινος τῶν καλλίστων αἰσχύνην φέρει. ἔτι δ’ οἱ μὲν ἐπὶ τῶν ἄλλων λόγων ψευσθέντες καθ’ ἑνὸς μόνου πράγματος οὐ τὰ κράτιστ’ ἔγνωσαν· οἱ δὲ τῆς τῶν ἐπιτηδευμάτων συμβουλίας διαμαρτόντες ἢ καταφρονήσαντες παρ’ ὅλον τὸν βίον τῆς ἑαυτῶν ἀγνωσίας ὑπομνήματ’ ἔχουσιν.", "st": "61.35"}, {"sp": "N", "t": "τούτων μὲν οὐδὲν δεῖ σε παθεῖν, σκοπεῖσθαι δὲ τί τῶν ἀνθρωπείων μεγίστην δύναμιν ἔχει, καὶ τίνος καλῶς μὲν ἀποβάντος πλεῖστ’ ἂν κατορθοῖμεν, διαφθαρέντος δὲ μέγιστ’ ἂν βλαπτοίμεθα παρὰ τὸν βίον· οὐ γὰρ ἄδηλον ὅτι τούτου καὶ μάλιστ’ ἐπιμέλειαν ποιητέον, ὃ μεγίστην ῥοπὴν ἐφ’ ἑκάτερον ἐργάζεσθαι πέφυκεν.", "st": "61.36"}, {"sp": "N", "t": "τῶν μὲν τοίνυν ἐν ἀνθρώποις διάνοιαν ἁπάντων εὑρήσομεν ἡγεμονεύουσαν, ταύτην δὲ φιλοσοφίαν μόνην παιδεῦσαί τ’ ὀρθῶς καὶ γυμνάσαι δυναμένην. ἧς οἴομαι σε δεῖν μετασχεῖν, καὶ μὴ κατοκνῆσαι μηδὲ φυγεῖν τὰς ἐνούσας ἐν αὐτῇ πραγματείας, ἐνθυμούμενον ὅτι διὰ μὲν ἀργίας καὶ ῥᾳθυμίας καὶ τὰ παντελῶς ἐπιπολῆς δυσχείρωτ’ ἐστί, διὰ δὲ καρτερίας καὶ φιλοπονίας οὐδὲν τῶν ὄντων ἀγαθῶν ἀνάλωτον πέφυκεν,", "st": "61.37"}, {"sp": "N", "t": "καὶ διότι πάντων ἀλογώτατόν ἐστι πρὸς μὲν χρηματισμὸν καὶ ῥώμην καὶ τὰ τοιαῦτα φιλοτίμως ἔχειν καὶ πολλὰς ὑπομένειν κακοπαθίας, ἃ πάντα θνήτ’ ἐστὶν καὶ τῇ διανοίᾳ δουλεύειν εἴωθεν, τὴν δ’ ἐπιστατοῦσαν μὲν τῶν ἄλλων, συνδιατελοῦσαν δὲ τοῖς ἔχουσιν, ὅλου δ’ ἡγεμονεύουσαν τοῦ βίου μὴ ζητεῖν ὅπως διακείσεται βέλτιον.", "st": "61.38"}, {"sp": "N", "t": "καίτοι καλὸν μὲν καὶ διὰ τύχην ἐν τοῖς σπουδαιοτάτοις θαυμάζεσθαι, πολὺ δὲ κάλλιον διὰ τὴν ἐπιμέλειαν τὴν αὑτοῦ μηδενὸς τῶν ἐνδόξων ἄμοιρον γενέσθαι· τῆς μὲν γὰρ ἐνίοτε καὶ τοῖς φαύλοις μετασχεῖν συνέβη, τῆς δ’ οὐκ ἔστιν ἄλλοις μετουσία πλὴν τοῖς ἐν ἀνδραγαθίᾳ διαφέρουσιν.", "st": "61.39"}, {"sp": "N", "t": "ἀλλὰ μὴν περί γε τῆς φιλοσοφίας ἀκριβῶς μὲν ἕκαστα διελθεῖν ἡγοῦμαι τὸν μέλλοντα χρόνον ἡμῖν ἐπιτηδειοτέρους καιροὺς παραδώσειν· συντόμως δ’ εἰπεῖν οὐδὲ νῦν οὐδὲν κωλύσει περὶ αὐτῆς. ἓν οὖν πρῶτον ἐκεῖνό σε δεῖ καταμαθεῖν ἀκριβῶς, ὅτι πᾶσα μὲν παιδεία δι’ ἐπιστήμης καὶ μελέτης τινὸς συνέστηκεν, ἡ δὲ φιλοσοφία καὶ μᾶλλον τῶν ἄλλων· ὅσῳ γὰρ φρονιμωτέρους ἔχει τοὺς ἐφεστῶτας, τοσούτῳ κάλλιον αὐτὴν συγκεῖσθαι προσήκει.", "st": "61.40"}, {"sp": "N", "t": "καίτοι τί ποτ’ ἂν βουληθείημεν, τῆς μὲν διανοίας ἐπὶ τοῦ λέγειν καὶ βουλεύεσθαι τεταγμένης, τῆς δὲ φιλοσοφίας ἑκατέρου τούτων ἐμπειρίαν παραδιδούσης, μὴ ταύτην κατασχεῖν τὴν πραγματείαν, δι’ ἧς ἀμφοτέρων τούτων ἐγκρατῶς ἕξομεν; τότε γὰρ εἰκὸς καὶ τὸν βίον ἡμῶν μεγίστην ἐπίδοσιν λαβεῖν, ὅταν τῶν κρατίστων ὀρεγόμενοι τὰ μὲν διδακτὰ τέχνῃ, τὰ δὲ λοιπὰ γυμνασίᾳ καὶ συνηθείᾳ κατασχεῖν δυνηθῶμεν.", "st": "61.41"}, {"sp": "N", "t": "οὐ γὰρ δήπου τοῦτό γ’ ἔστιν εἰπεῖν, ὡς οὐδὲν πρὸς τὸ φρονεῖν εὖ παρὰ τὴν ἐπιστήμην διαφέρομεν ἀλλήλων· ὅλως μὲν γὰρ ἅπασα φύσις βελτίων γίγνεται παιδείαν προσλαβοῦσα τὴν προσήκουσαν, πολὺ δὲ μάλισθ’ ὅσαις ἐξ ἀρχῆς εὐφυέστερον τῶν ἄλλων ἔχειν ὑπῆρξεν· ταῖς μὲν γὰρ αὑτῶν μόνον βελτίοσιν γίγνεσθαι, ταῖς δὲ καὶ τῶν ἄλλων συμβαίνει διενεγκεῖν.", "st": "61.42"}, {"sp": "N", "t": "εὖ δ’ ἴσθι τὴν μὲν ἐκ τῶν πράξεων ἐμπειρίαν γιγνομένην σφαλερὰν οὖσαν καὶ πρὸς τὸν λοιπὸν βίον ἀχρήστως ἔχουσαν, τὴν δ’ ἐκ τοῦ φιλοσοφεῖν παιδείαν πρὸς ἅπαντα ταῦτ’ εὐκαίρως συγκεκραμένην. καίτοι τινὲς ἤδη καὶ δι’ εὐτυχίαν πραγμάτων γυμνασθέντες ἐθαυμάσθησαν· σοὶ δὲ προσήκει τούτων μὲν καταφρονεῖν, σαυτοῦ δ’ ἐπιμέλειαν ἔχειν· οὐ γὰρ αὐτοσχεδιάζειν, ἀλλ’ ἐπίστασθαί σε δεῖ περὶ τῶν μεγίστων, οὐδ’ ἐπὶ τῶν καιρῶν μελετᾶν, ἀλλ’ ἀγωνίζεσθαι καλῶς ἐπίστασθαι.", "st": "61.43"}, {"sp": "N", "t": "νόμιζε δὲ πᾶσαν μὲν τὴν φιλοσοφίαν μεγάλα τοὺς χρωμένους ὠφελεῖν, πολὺ δὲ μάλιστα τὴν περὶ τὰς πράξεις καὶ τοὺς πολιτικοὺς λόγους ἐπιστήμην. τῆς γὰρ γεωμετρίας καὶ τῆς ἄλλης τῆς τοιαύτης παιδείας ἀπείρως μὲν ἔχειν αἰσχρόν, ἄκρον δ’ ἀγωνιστὴν γενέσθαι ταπεινότερον τῆς σῆς ἀξίας· ἐν ἐκείνῃ δὲ τὸ μὲν διενεγκεῖν ζηλωτόν, τὸ δ’ ἄμοιρον γενέσθαι παντελῶς καταγέλαστον.", "st": "61.44"}, {"sp": "N", "t": "γνοίης δ’ ἂν ἐξ ἄλλων τε πολλῶν, καὶ παραθεωρήσας τοὺς πρὸ σαυτοῦ γεγενημένους ἐνδόξους ἄνδρας. τοῦτο μὲν γὰρ Περικλέα τὸν συνέσει πλεῖστον τῶν καθ’ αὑτὸν διενεγκεῖν δόξαντα πάντων, ἀκούσει πλησιάσαντ’ Ἀναξαγόρᾳ τῷ Κλαζομενίῳ καὶ μαθητὴν ἐκείνου γενόμενον ταύτης τῆς δυνάμεως μετασχόντα· τοῦτο δ’ Ἀλκιβιάδην εὑρήσεις φύσει μὲν πρὸς ἀρετὴν πολλῷ χεῖρον διακείμενον, καὶ τὰ μὲν ὑπερηφάνως, τὰ δὲ ταπεινῶς, τὰ δ’ ὑπερακρατῶς ζῆν προῃρημένον, ἀπὸ δὲ τῆς Σωκράτους ὁμιλίας πολλὰ μὲν ἐπανορθωθέντα τοῦ βίου, τὰ δὲ λοιπὰ τῷ μεγέθει τῶν ἄλλων ἔργων ἐπικρυψάμενον.", "st": "61.45"}, {"sp": "N", "t": "εἰ δὲ δεῖ μὴ παλαιὰ λέγοντας διατρίβειν, ἔχοντας ὑπογυωτέροις παραδείγμασιν χρῆσθαι, τοῦτο μὲν Τιμόθεον οὐκ ἐξ ὧν νεώτερος ὢν ἐπετήδευσεν, ἀλλ’ ἐξ ὧν Ἰσοκράτει συνδιατρίψας ἔπραξεν, μεγίστης δόξης καὶ πλείστων τιμῶν εὑρήσεις ἀξιωθέντα· τοῦτο δ’ Ἀρχύταν τὴν Ταραντίνων πόλιν οὕτω καλῶς καὶ φιλανθρώπως διοικήσαντα κύριον αὐτῆς καταστάντα, ὥστ’ εἰς ἅπαντας τὴν ἐκείνου μνήμην διενεγκεῖν· ὃς ἐν ἀρχῇ καταφρονούμενος, ἐκ τοῦ Πλάτωνι πλησιάσαι τοσαύτην ἔλαβεν ἐπίδοσιν.", "st": "61.46"}, {"sp": "N", "t": "καὶ τούτων οὐδὲν ἀλόγως ἀποβέβηκεν· πολὺ γὰρ ⟨ἄν⟩ ἦν ἀτοπώτερον, εἰ τὰ μὲν μικρὰ δι’ ἐπιστήμης καὶ μελέτης ἠναγκαζόμεθ’ ἐπιτελεῖν, τὰ δὲ μέγιστ’ ἄνευ ταύτης τῆς πραγματείας ἠδυνάμεθα πράττειν. περὶ μὲν οὖν τούτων οὐκ οἶδ’ ὅ τι δεῖ πλείω λέγειν· οὐδὲ γὰρ ἐξ ἀρχῆς ὡς παντελῶς ἀπείρως ἔχοντός σου περὶ αὐτῶν ἐμνήσθην, ἀλλ’ ἡγούμενος τὰς τοιαύτας παρακλήσεις τοὺς μὲν ἀγνοοῦντας προτρέπειν, τοὺς δ’ εἰδότας παροξύνειν.", "st": "61.47"}, {"sp": "N", "t": "μηδὲν δ’ ὑπολάβῃς τοιοῦτον, ὡς ἄρ’ ἐγὼ ταῦτ’ εἴρηκα διδάξειν αὐτὸς ἐπαγγελλόμενός σέ τι τούτων· οὐ γὰρ ἂν αἰσχυνθείην εἰπὼν ὅτι πολλὰ μαθεῖν αὐτὸς ἔτι δέομαι, καὶ μᾶλλον ἀγωνιστὴς προῄρημαι τῶν πολιτικῶν ἢ διδάσκαλος εἶναι τῶν ἄλλων. οὐχ ὡς ἀναινόμενος δὲ ταῦτα διορθοῦμαι τὴν τῶν σοφιστεύειν ἑλομένων δόξαν, ἀλλ’ ὅτι τἀληθὲς τοῦτον ἔχον τυγχάνει τὸν τρόπον·", "st": "61.48"}, {"sp": "N", "t": "ἐπεὶ σύνοιδά γε πολλοὺς μὲν ἐξ ἀδόξων καὶ ταπεινῶν ἐπιφανεῖς διὰ τῆς πραγματείας ταύτης γεγενημένους, Σόλωνα δὲ καὶ ζῶντα καὶ τελευτήσαντα μεγίστης δόξης ἠξιωμένον· ὃς οὐκ ἀπεληλαμένος τῶν ἄλλων τιμῶν, ἀλλὰ τῆς μὲν ἀνδρείας τὸ πρὸς Μεγαρέας τρόπαιον ὑπόμνημα καταλιπών, τῆς δ’ εὐβουλίας τὴν Σαλαμῖνος κομιδήν,", "st": "61.49"}, {"sp": "N", "t": "τῆς δ’ ἄλλης συνέσεως τοὺς νόμους, οἷς ἔτι καὶ νῦν οἱ πλεῖστοι τῶν Ἑλλήνων χρώμενοι διατελοῦσιν, ὅμως τοσούτων αὐτῷ καλῶν ὑπαρχόντων, ἐπ’ οὐδενὶ μᾶλλον ἐσπούδασεν ἢ τῶν ἑπτὰ σοφιστῶν ὅπως γένηται, νομίζων τὴν φιλοσοφίαν οὐκ ὄνειδος, ἀλλὰ τιμὴν τοῖς χρωμένοις φέρειν, καλῶς ἐγνωκὼς αὐτὸ τοῦτ’ οὐχ ἧττον ἢ καὶ τἄλλ’ ἐφ’ οἷς διήνεγκεν.", "st": "61.50"}, {"sp": "N", "t": "ἐγὼ μὲν οὖν οὔτ’ αὐτὸς ἄλλως γιγνώσκω, σοί τε παραινῶ φιλοσοφεῖν, μεμνημένῳ τῶν ἐξ ἀρχῆς ὑπαρξάντων σαυτῷ· τούτου γὰρ ἕνεκα διῆλθον ἐν ἀρχῇ τοῦ λόγου κἀγὼ περὶ αὐτῶν, οὐχ ὡς ἐκ τοῦ τὴν σὴν φύσιν ἐπαινεῖν ἀνακτήσεσθαί σε προσδοκῶν, ἀλλ’ ἵνα μᾶλλον προτρέψω σε πρὸς τὴν φιλοσοφίαν, ἐὰν μὴ παρὰ μικρὸν ποιήσῃ, μηδ’ ἐπὶ τοῖς ὑπάρχουσιν ἀγαθοῖς μέγα φρονήσας τῶν μελλόντων ὀλιγωρήσῃς.", "st": "61.51"}, {"sp": "N", "t": "μηδ’ εἰ τῶν ἐντυγχανόντων κρείττων εἶ, μηδὲν τῶν ἄλλων ζήτει διενεγκεῖν, ἀλλ’ ἡγοῦ κράτιστον μὲν εἶναι τὸ πρωτεύειν ἐν ἅπασιν, τούτου δ’ ὀρεγόμενον ὀφθῆναι μᾶλλον συμφέρειν ἢ προέχοντ’ ἐν τοῖς τυχοῦσιν. καὶ μὴ καταισχύνῃς τὴν φύσιν, μηδὲ ψευσθῆναι ποιήσῃς τῶν ἐλπίδων τοὺς ἐπὶ σοὶ μέγα φρονοῦντας, ἀλλ’ ὑπερβάλλεσθαι πειρῶ τῇ σαυτοῦ δυνάμει τὴν τῶν εὐνουστάτων ἐπιθυμίαν.", "st": "61.52"}, {"sp": "N", "t": "καὶ νόμιζε τοὺς μὲν ἄλλους λόγους, ὅταν ἐπιεικῶς ἔχωσιν, τοῖς εἰποῦσιν δόξαν περιτιθέναι, τὰς δὲ συμβουλίας τοῖς πεισθεῖσιν ὠφέλειαν καὶ τιμὴν προσάπτειν· καὶ τὰς μὲν περὶ τῶν ἄλλων κρίσεις τὴν αἴσθησιν ἣν ἔχομεν δηλοῦν, τὰς δὲ τῶν ἐπιτηδευμάτων αἱρέσεις τὴν ὅλην φύσιν ἡμῶν δοκιμάζειν. ἐν οἷς ἅμα κρίνων αὐτὸς κριθήσεσθαι προσδόκα παρὰ πᾶσιν, κἀμὲ τὸν οὕτως ἐγκωμιάσαντά σ’ ἑτοίμως ἐν ἀγῶνι γενήσεσθαι τῆς σῆς δοκιμασίας.", "st": "61.53"}, {"sp": "N", "t": "δι’ ἃ δεῖ σε τῶν ἐπαίνων ἄξιον εἶναι δόξαντα καὶ ἐμὲ τῆς σῆς φιλίας ἀνεπιτίμητον ἀφεῖναι. οὐχ οὕτως δ’ ἄν σε προθύμως ἐπὶ τὴν φιλοσοφίαν παρεκάλουν, εἰ μὴ τῆς μὲν εὐνοίας τῆς ἐμῆς τοῦτον ἄν σοι κάλλιστον ἔρανον εἰσενεγκεῖν ᾤμην, τὴν δὲ πόλιν ἑώρων διὰ μὲν ἀπορίαν τῶν καλῶν κἀγαθῶν ἀνδρῶν τοῖς τυχοῦσιν πολλάκις χρωμένην, διὰ δὲ τὰς τούτων ἁμαρτίας αὐτὴν ταῖς μεγίσταις ἀτυχίαις περιπίπτουσαν.", "st": "61.54"}, {"sp": "N", "t": "ἵν’ οὖν ἡ μὲν τῆς σῆς ἀρετῆς, σὺ δὲ τῶν παρὰ ταύτης τιμῶν ἀπολαύσῃς, προθυμότερόν σοι παρεκελευσάμην. καὶ γὰρ οὐδ’ ἐπὶ σοὶ νομίζω γενήσεσθαι ζῆν ὡς ἔτυχεν, ἀλλὰ προστάξειν σοι τὴν πόλιν τῶν αὑτῆς τι διοικεῖν, καὶ ὅσῳ τὴν φύσιν ἐπιφανεστέραν ἔχεις, τοσούτῳ μειζόνων ἀξιώσειν καὶ θᾶττον βουλήσεσθαι πεῖράν σου λαμβάνειν. καλὸν οὖν παρεσκευάσθαι τὴν γνώμην, ἵνα μὴ τότε πλημμελῇς.", "st": "61.55"}, {"sp": "N", "t": "τοῦτο μὲν οὖν ἐμὸν ἦν ἔργον, εἰπεῖν ἅ σοι συμφέρειν ἡγοῦμαι πεπρᾶχθαι, σὸν δὲ βουλεύσασθαι περὶ αὐτῶν. προσήκει δὲ καὶ τοὺς ἄλλους τοὺς ζητοῦντας οἰκείως πρὸς σὲ διακεῖσθαι μὴ τὰς ἐπιπολαίους ἡδονὰς καὶ διατριβὰς ἀγαπᾶν, μηδ’ ἐπὶ ταύτας προκαλεῖσθαι, ἀλλὰ φιλοπονεῖν καὶ σκοπεῖν ὅπως τὸν σὸν βίον ὡς λαμπρότατον καταστήσουσιν· αὐτοί τε γὰρ οὕτως ἂν μάλιστ’ ἐπαινοῖντο καὶ σοὶ πλείστων ἀγαθῶν αἴτιοι γένοιντο.", "st": "61.56"}, {"sp": "N", "t": "μέμφομαι μὲν οὖν οὐδὲ νῦν οὐδένα τῶν σοὶ πλησιαζόντων· καὶ γάρ μοι δοκεῖ τῆς ἄλλης εὐτυχίας τῆς σῆς καὶ τοῦθ’ ἓν εἶναι, τὸ μηδενὸς φαύλου τυχεῖν ἐραστοῦ, ἀλλ’ οὓς ἄν τις ἕλοιτο βουλόμενος φίλους ἐκ τῶν ἡλικιωτῶν ἐκλέγεσθαι· παραινῶ μέντοι σοι φιλοφρονεῖσθαι μὲν πρὸς ἅπαντας τούτους καὶ ἔχειν ἡδέως, πείθεσθαι δὲ τοῖς πλεῖστον νοῦν ἔχουσιν αὐτῶν, ἵνα καὶ τούτοις αὐτοῖς ἔτι σπουδαιότερος δοκῇς εἶναι καὶ τοῖς ἄλλοις πολίταις. εὐτύχει.", "st": "61.57"}, {"sp": "HDR", "t": "Προοίμια δημηγορικά", "st": "62"}, {"sp": "SEC", "t": "Προοίμιον Αʹ", "st": "62.1"}, {"sp": "N", "t": "εἰ μὲν περὶ καινοῦ τινος πράγματος προὐτίθετ’, ὦ ἄνδρες Ἀθηναῖοι, λέγειν, ἐπισχὼν ἂν ἕως οἱ πλεῖστοι τῶν εἰωθότων γνώμην ἀπεφήναντο, εἰ μὲν ἤρεσκέ τί μοι τῶν ῥηθέντων, ἡσυχίαν ἂν ἦγον, εἰ δὲ μή, τότ’ ἂν καὶ αὐτὸς ἐπειρώμην ἃ γιγνώσκω λέγειν· ἐπειδὴ δ’ ὑπὲρ ὧν πολλάκις εἰρήκασιν οὗτοι πρότερον, περὶ τούτων νυνὶ σκοπεῖτε, ἡγοῦμαι καὶ πρῶτος ἀναστὰς εἰκότως ἂν μετὰ τούτους δοκεῖν λέγειν.", "st": "62.1.1"}, {"sp": "N", "t": "εἰ μὲν οὖν εἶχεν καλῶς τὰ πράγματα, οὐδὲν ἂν ἔδει συμβουλεύειν· ἐπειδὴ δ’ ὅσην ἅπαντες ὁρᾶτ’ ἔχει δυσκολίαν, ὡς ἐκ τοιούτων πειράσομαι συμβουλεύειν ἃ κράτιστ’ εἶναι νομίζω. πρῶτον μὲν οὖν ὑμᾶς ἐκεῖν’ ἐγνωκέναι δεῖ, ὡς οὐδὲν ὧν ἐποιεῖτ’ ἐπὶ τοῦ πολεμεῖν ὄντες τοῦ λοιποῦ πρακτέον ἐστίν, ἀλλὰ πάντα τἀναντία· εἰ γὰρ ἐκεῖνα φαῦλα πεποίηκε τὰ πράγματα, τἀναντί’ εἰκὸς βελτίω ποιῆσαι.", "st": "62.1.2"}, {"sp": "N", "t": "ἔπειτα νομιστέον οὐχ ὃς ἂν ὑμῖν ἢ μηδὲν ἢ μικρὰ προστάττῃ, τοῦτον ὀρθῶς λέγειν ʽὁρᾶτε γὰρ ὡς ἐκ τῶν τοιούτων ἐλπίδων καὶ λόγων εἰς πᾶν προελήλυθε μοχθηρίας τὰ παρόντἀ, ἀλλ’ ὃς ἂν τὸ χαρίζεσθαι παρείς, ἃ δεῖ καὶ δι’ ὧν παυσαίμεθ’ ⟨ἂν⟩ αἰσχύνην ὀφλισκάνοντες καὶ ζημιούμενοι, ταῦτα λέγῃ. καὶ γὰρ ὡς ἀληθῶς, εἰ μέν, ὅσ’ ἂν τῷ λόγῳ τις ὑπερβῇ λυπῆσαι μὴ βουλόμενος, καὶ τὰ πράγμαθ’ ὑπερβήσεται, δεῖ πρὸς ἡδονὴν δημηγορεῖν· εἰ δ’ ἡ τῶν λόγων χάρις, ἂν ᾖ μὴ προσήκουσα, ἔργῳ ζημία γίγνεται, αἰσχρόν ἐστιν φενακίζειν ἑαυτοὺς καὶ μετὰ τῆς ἐσχάτης ἀνάγκης πρᾶξαι ταῦθ’ ἃ πάλαι ’θελοντὰς προσῆκεν ποιεῖν.", "st": "62.1.3"}, {"sp": "SEC", "t": "Προοίμιον Βʹ", "st": "62.2"}, {"sp": "N", "t": "οὐχὶ ταὐτὰ γιγνώσκειν, ὦ ἄνδρες Ἀθηναῖοι, παρίσταταί μοι, ὅταν τε τὸ τῆς πολιτείας ὄνομ’ ὑμῶν ἀκούσω, καὶ ὅταν τὸν τρόπον ὃν προσφέρονταί τινες ὑμῶν τοῖς ὑπὲρ ταύτης λέγουσιν ἴδω. τὴν μὲν γὰρ πολιτείαν δημοκρατίαν, ὥσπερ ἅπαντες ἴστε, ὀνομάζετε, τῶν δὲ τἀναντία ταύτῃ λεγόντων ἐνίους ἥδιον ἀκούοντας ὁρῶ.", "st": "62.2.1"}, {"sp": "N", "t": "ὃ καὶ θαυμάζω τίς ποθ’ ἡ πρόφασις. πότερον προῖκα λέγειν ταῦτ’ αὐτοὺς οἴεσθε; ἀλλ’ οἱ τῶν ὀλιγαρχιῶν, ὑπὲρ ὧν οὗτοι λέγουσιν, κύριοι καὶ πλείω σιωπῆς μᾶλλον ἂν δοῖεν. ἀλλὰ βελτίω ταῦτ’ εἶναι τῶν ἑτέρων ὑπειλήφατε; βελτίων ἄρ’ ὑμῖν ὀλιγαρχία δημοκρατίας φαίνεται. ἀλλ’ αὐτοὺς εἶναι βελτίους ἡγεῖσθε; καὶ τίς ἂν ὑφ’ ὑμῶν χρηστὸς νομίζοιτ’ εἰκότως, ἐναντία τῇ καθεστώσῃ πολιτείᾳ δημηγορῶν; οὐκοῦν λοιπὸν ἁμαρτάνειν ὑμᾶς, ὅταν οὕτως ἔχητε τὴν γνώμην. τοῦτο τοίνυν φυλάττεσθε μὴ πάσχειν, ὦ ἄνδρες Ἀθηναῖοι, ὅπως μή ποτε τοῖς ἐπιβουλεύουσιν λαβὴν δώσετε, εἶτα τότ’ αἰσθήσεσθ’ ἡμαρτηκότες, ἡνίκ’ οὐδ’ ὁτιοῦν ὑμῖν πλέον ἔσται.", "st": "62.2.2"}, {"sp": "N", "t": "β", "st": "62.2.3"}, {"sp": "N", "t": "τὸ μὲν [οὖν], ὦ ἄνδρες Ἀθηναῖοι, μὴ πάνθ’ ὡς ἂν ἡμεῖς βουλοίμεθ’ ἔχειν μήτε παρ’ αὐτοῖς ἡμῖν μήτε παρὰ τοῖς συμμάχοις, ἴσως οὐδέν ἐστι θαυμαστόν· πολλῶν γὰρ τὸ τῆς τύχης αὐτόματον κρατεῖ, καὶ πολλαὶ προφάσεις τοῦ μὴ πάντα κατὰ γνώμην συμβαίνειν ἀνθρώποις οὖσιν. τὸ δὲ μηδ’ ὁτιοῦν μεταλαμβάνειν τὸν δῆμον, ἀλλὰ τοὺς ἀντιπράττοντας περιεῖναι, τοῦτο καὶ θαυμαστόν, ὦ ἄνδρες Ἀθηναῖοι, καὶ φοβερὸν τοῖς εὖ φρονοῦσιν, ὡς ἐγὼ κρίνω. ἡ μὲν οὖν ἀρχὴ παντός ἐστιν αὕτη μοι τοῦ λόγου.", "st": "62.2.3"}, {"sp": "SEC", "t": "Προοίμιον Γʹ", "st": "62.3"}, {"sp": "N", "t": "ἀντὶ πολλῶν ἄν, ὦ ἄνδρες Ἀθηναῖοι, χρημάτων τὸ μέλλον συνοίσειν ὑμῖν περὶ ὧν νυνὶ τυγχάνετε σκοποῦντες, οἶμαι πάντας ἂν ὑμᾶς ἑλέσθαι. ὅτε τοίνυν τοῦθ’ οὕτως ἔχει, προσήκει παρέχειν ἐθέλοντας ἀκούειν ὑμᾶς αὐτοὺς τῶν βουλομένων συμβουλεύειν· οὐ γὰρ μόνον εἴ τι χρήσιμον ἐσκεμμένος ἥκει τις, τοῦτ’ ἂν ἀκούσαντες λάβοιτε, ἀλλὰ καὶ τῆς ὑμετέρας τύχης ὑπολαμβάνω πολλὰ τῶν δεόντων ἐκ τοῦ παραχρῆμ’ ἐνίοις ἐπελθεῖν ἂν εἰπεῖν, ὥστ’ ἐξ ἁπάντων ῥᾳδίαν τὴν τοῦ συμφέροντος ὑμῖν αἵρεσιν γενέσθαι.", "st": "62.3.1"}, {"sp": "SEC", "t": "Προοίμιον Δʹ", "st": "62.4"}, {"sp": "N", "t": "ἔστιν, ὦ ἄνδρες Ἀθηναῖοι, δίκαιον, ἐπειδὴ ἐφ’ ὑμῖν ἐστιν ἑλέσθαι τῶν ῥηθέντων ὅ τι ἂν βούλησθε, ἁπάντων ἀκοῦσαι. καὶ γὰρ πολλάκις συμβαίνει τὸν αὐτὸν ἄνθρωπον τοῦτο μὲν μὴ λέγειν ὀρθῶς, ἕτερον δέ τι· ἐκ μὲν οὖν τοῦ θορυβεῖν τάχ’ ἂν δυσχεράναντες πολλῶν χρησίμων ἀποστερηθείητε, ἐκ δὲ τοῦ μετὰ κόσμου καὶ σιγῆς ἀκοῦσαι καὶ τὰ καλῶς ἔχονθ’ ἅπαντα ποιήσετε, κἂν δοκῇ τις [παρα]ληρεῖν, παραλείψετε. ἐγὼ μὲν οὖν οὔτ’ εἴωθα μακρολογεῖν, οὔτ’ ἄν, εἰ τὸν ἄλλον εἰώθειν χρόνον, νῦν ἐχρησάμην τούτῳ, ἀλλ’ ἃ συμφέρειν ὑμῖν νομίζω, ταῦθ’ ὡς ἂν δύνωμαι διὰ βραχυτάτων ἐρῶ πρὸς ὑμᾶς.", "st": "62.4.1"}, {"sp": "SEC", "t": "Προοίμιον Εʹ", "st": "62.5"}, {"sp": "N", "t": "ὁρῶ μέν, ὦ ἄνδρες Ἀθηναῖοι, παντάπασι πρόδηλον ὂν οὕς τ’ ἂν ἀκούσαιτε λόγους ἡδέως καὶ πρὸς οὓς οὐκ οἰκείως ἔχετε· οὐ μὴν ἀλλὰ τὸ μὲν λέγειν ἅ τις οἴεται χαριεῖσθαι τῶν παρακρούσασθαί τι βουλομένων εἶναι νομίζω, τὸ δ’ ὑφίστασθαι, περὶ ὧν πέπεικεν ἑαυτὸν συμφέρειν τῇ πόλει, καὶ θορυβηθῆναι κἂν ἄλλο τι βούλησθ’ ὑμεῖς, εὔνου καὶ δικαίου τοῦτο πολίτου κρίνω.", "st": "62.5.1"}, {"sp": "N", "t": "βουλοίμην δ’ ἂν ὑμᾶς, εἰ καὶ μηδὲ δι’ ἓν τῶν ἄλλων, δι’ ἐκεῖν’ ὑπομεῖναι τοὺς λόγους ἀμφοτέρων, ἵν’ ἐὰν μὲν ὀρθότερον φανῇ τις λέγων ὧν ὑμεῖς ὡρμήκατε, χρήσησθε τούτῳ, ἂν δ’ ἀπολειφθῇ καὶ μὴ δύνηται διδάξαι, δι’ αὑτόν, ἀλλὰ μὴ δι’ ὑμᾶς οὐκ ἐθέλοντας ἀκούειν τοῦτο πεπονθέναι δοκῇ. ἔτι δ’ οὐδὲ πάθοιτ’ ἂν ἀηδὲς οὐδὲν τοσοῦτον, εἰ πολλά τινος ληροῦντος ἀκούσαιτε, ὅσον εἰ τῶν δεόντων τι λέγειν ἔχοντός τινος εἰπεῖν κωλύσαιτε.", "st": "62.5.2"}, {"sp": "N", "t": "ἡ μὲν οὖν ἀρχὴ τοῦ δοκιμάζειν ὀρθῶς ἅπαντ’ ἐστὶν μηδὲν οἴεσθαι πρότερον γιγνώσκειν πρὶν μαθεῖν, ἄλλως τε καὶ συνειδότας πολλάκις ἤδη πολλοὺς μετεγνωκότας. ἂν τοίνυν ὑμεῖς ταῦθ’ ὑπάρξητε νῦν πεπεισμένοι, οἴομαι μετὰ βραχέων λόγων καὶ αὐτὸς ἀντιλέγειν εἰκότως δόξειν καὶ ὑμῖν τὰ βέλτιστα φανεῖσθαι λέγων.", "st": "62.5.3"}, {"sp": "SEC", "t": "Προοίμιον Ϛʹ", "st": "62.6"}, {"sp": "N", "t": "πολλῶν, ὦ ἄνδρες Ἀθηναῖοι, λόγων εἰρημένων παρὰ πάντων τῶν συμβεβουλευκότων, οὐδὲν ὑμᾶς νῦν ὁρῶ ὄντας ἐγγυτέρω τοῦ τί πρακτέον ηὑρῆσθαι ἢ πρὶν εἰς τὴν ἐκκλησίαν ἀναβῆναι. αἴτιον δὲ τούτου ταὔθ’ ὅπερ οἶμαι τοῦ κακῶς ἔχειν τὰ ὅλα· οὐ γὰρ παραινοῦσιν ὑμῖν ὑπὲρ τῶν παρόντων οἱ λέγοντες, ἀλλ’ ἑαυτῶν κατηγοροῦσι καὶ λοιδοροῦνται, ὡς μὲν ἐγὼ κρίνω, συνεθίζοντες ὑμᾶς ἄνευ κρίσεως, ὅσων εἰσὶν αἴτιοι κακῶν, ἀκούειν, ἵν’ ἄν ποτ’ ἄρ’ εἰς ἀγῶνα καθιστῶνται, μηδὲν ἡγούμενοι καινὸν ἀκούειν, ἀλλ’ ὑπὲρ ὧν ὤργισθε πολλάκις, πραότεροι δικασταὶ καὶ κριταὶ γίγνησθε τῶν πεπραγμένων αὐτοῖς.", "st": "62.6.1"}, {"sp": "N", "t": "τὴν μὲν οὖν αἰτίαν δι’ ἣν ταῦτα ποιοῦσιν, ἴσως ἀνόητον ἀκριβῶς ζητεῖν [εἴη ἂν] ἐν τῷ παρόντι· ὅτι δ’ ὑμῖν οὐχὶ συμφέρει, διὰ τοῦτ’ ἐπιτιμῶ. ἐγὼ δ’ οὔτε κατηγορήσω τήμερον οὐδενός, οὔθ’ ὑποσχήσομαι τοιοῦτ’ οὐδὲν ὃ μὴ παραχρῆμ’ ἐπιδείξω, οὐδ’ ὅλως τῶν αὐτῶν τούτοις οὐδὲν ποιήσω· ἀλλ’ ἃ βέλτιστα μὲν τοῖς πράγμασιν, συμφέροντα δὲ τοῖς βουλευομένοις ὑμῖν ἡγοῦμαι, ταῦθ’ ὡς ἂν δύνωμαι διὰ βραχυτάτων εἰπὼν καταβήσομαι.", "st": "62.6.2"}, {"sp": "SEC", "t": "Προοίμιον Ζʹ", "st": "62.7"}, {"sp": "N", "t": "οἱ μὲν ἐπαινοῦντες, ὦ ἄνδρες Ἀθηναῖοι, τοὺς προγόνους ὑμῶν λόγον εἰπεῖν μοι δοκοῦσι προαιρεῖσθαι κεχαρισμένον, οὐ μὴν συμφέροντά γ’ ἐκείνοις οὓς ἐγκωμιάζουσιν ποιεῖν. περὶ γὰρ πραγμάτων ἐγχειροῦντες ⟨λέγειν⟩ ὧν οὐδ’ ἂν εἷς ἀξίως ἐφικέσθαι δύναιτο τῷ λόγῳ, αὐτοὶ μὲν τοῦ δύνασθαι λέγειν δόξαν ἐκφέρονται, τὴν δ’ ἐκείνων ἀρετὴν ἐλάττω τῆς ὑπειλημμένης παρὰ τοῖς ἀκούουσιν φαίνεσθαι ποιοῦσιν. ἐγὼ δὲ τῆς μὲν ἐκείνων ἀρετῆς μέγιστον ἔπαινον ἡγοῦμαι τὸν χρόνον, οὗ πολλοῦ γεγενημένου μείζω τῶν ὑπ’ ἐκείνων πραχθέντων οὐδένες ἄλλοι παραδείξασθαι δεδύνηνται·", "st": "62.7.1"}, {"sp": "N", "t": "αὐτὸς δὲ πειράσομαι τὸν τρόπον εἰπεῖν ὃν ἄν μοι δοκεῖτε μάλιστα δύνασθαι παρασκευάσασθαι. καὶ γὰρ οὕτως ἔχει· εἰ μὲν ἡμεῖς ἅπαντες οἱ λέγοντες δεινοὶ φανείημεν, οὐδὲν ἂν τὰ ὑμέτερ’ εὖ οἶδ’ ὅτι βέλτιον σχοίη· εἰ δὲ παρελθὼν ⟨εἷς⟩ ὁστισοῦν δύναιτο διδάξαι καὶ πεῖσαι, τίς παρασκευὴ καὶ πόση καὶ πόθεν πορισθεῖσα χρήσιμος ἔσται τῇ πόλει, πᾶς ὁ παρὼν λέλυται φόβος. ἐγὼ δὲ τοῦτο, ἂν ἄρ’ οἷός τ’ ὦ, πειράσομαι ποιῆσαι, μικρὰ προειπὼν ὑμῖν ὡς ἔχω γνώμης περὶ τῶν πρὸς τὸν βασιλέα.", "st": "62.7.2"}, {"sp": "SEC", "t": "Προοίμιον Ηʹ", "st": "62.8"}, {"sp": "N", "t": "ἀμφότεροί μοι δοκοῦσιν ἁμαρτάνειν, ὦ ἄνδρες Ἀθηναῖοι, καὶ οἱ τοῖς Ἀρκάσιν καὶ οἱ τοῖς Λακεδαιμονίοις συνειρηκότες· ὥσπερ γὰρ ἀφ’ ἑκατέρων ἥκοντες, οὐχ ὑμῶν ὄντες, πρὸς οὓς ἀμφότεροι πρεσβεύονται, κατηγοροῦσιν καὶ διαβάλλουσιν ἀλλήλους. ἦν δὲ τοῦτο μὲν τῶν ἀφιγμένων ἔργον, τὸ δὲ κοινῶς ὑπὲρ τῶν πραγμάτων λέγειν καὶ τὰ βέλτισθ’ ὑπὲρ ὑμῶν σκοπεῖν ἄνευ φιλονικίας τῶν ἐνθάδε συμβουλεύειν ἀξιούντων.", "st": "62.8.1"}, {"sp": "N", "t": "νῦν δ’ ἔγωγε, εἴ τις αὐτῶν ἀφέλοι τὸ γιγνώσκεσθαι καὶ τὸ τῇ φωνῇ λέγειν ἀττικιστί, πολλοὺς ἂν οἶμαι τοὺς μὲν Ἀρκάδας, τοὺς δὲ Λάκωνας αὐτῶν εἶναι νομίσαι. ἐγὼ δ’ οἶδα μὲν ὡς χαλεπὸν τὸ τὰ βέλτιστα λέγειν ἐστίν· συνεξηπατημένων γὰρ ὑμῶν, καὶ τῶν μὲν ταυτί, τῶν δὲ ταυτὶ βουλομένων, ἐὰν τὰ μεταξύ τις ἐγχειρῇ λέγειν κᾆθ’ ὑμεῖς μὴ περιμένητε μαθεῖν, χαριεῖται μὲν οὐδετέροις, διαβεβλήσεται δὲ πρὸς ἀμφοτέρους·", "st": "62.8.2"}, {"sp": "N", "t": "οὐ μὴν ἀλλ’ αἱρήσομαι μᾶλλον αὐτός, ἐὰν ἄρα τοῦτο πάθω, δοκεῖν φλυαρεῖν ἢ παρ’ ἃ βέλτιστα νομίζω τῇ πόλει, προέσθαι τισὶν ὑμᾶς ἐξαπατῆσαι. τὰ μὲν οὖν ἄλλ’ ὕστερον, ἐὰν ὑμῖν βουλομένοις ᾖ, λέξω· ἐκ δὲ τῶν ὁμολογουμένων ὑφ’ ἁπάντων ἄρξομαι ἃ κράτιστα νομίζω, διδάσκειν.", "st": "62.8.3"}, {"sp": "SEC", "t": "Προοίμιον Θʹ", "st": "62.9"}, {"sp": "N", "t": "οὐχὶ ταὐτὰ γιγνώσκων ἐνίοις τῶν εἰρηκότων ἀνέστηκ’, ὦ ἄνδρες Ἀθηναῖοι. οὐ μὴν οὐδὲ τούτους αἰτιάσομαι κακίᾳ τἀναντία τοῖς βελτίστοις εἰρηκέναι, ἀλλ’ ὅτι πολλοὶ τοῦ τὰ πράγματα κρίνειν ἀμελήσαντες τοὺς λόγους σκοπεῖν οὓς ἐροῦσιν εἰώθασιν, κἂν τούτοις ἀφθόνοις ἐντύχωσιν, ἑτοίμως δημηγορεῖν, οὐκ ὀρθῶς ἐγνωκότες, οὐδὲ λογιζόμενοι παρ’ ἑαυτοῖς ὅτι πολλῶν πράξεων ἐν πολλῷ χρόνῳ πᾶσι πεπραγμένων καὶ διὰ τοὺς καιροὺς ἐνίων ὑπεναντίων αὑταῖς, ἂν τὰς ἑτέρας τις ὑπερβαίνων τὰς ἑτέρας λέγῃ, λήσει τὸ ῥᾷστον τῶν ἔργων ποιῶν, αὑτὸν ἐξαπατῶν.", "st": "62.9.1"}, {"sp": "N", "t": "οἱ μὲν οὖν οὕτω χρώμενοι τῷ συμβουλεύειν δοκοῦσί μοι τὴν ἀπὸ τῶν ῥηθέντων τοῦ δύνασθαι λέγειν δόξαν γιγνομένην αὑτοῖς ἱκανὴν φιλοτιμίαν ἡγεῖσθαι· ἐγὼ δὲ νομίζω χρῆναι τὸν πόλει περὶ πραγμάτων ἐπιχειροῦντα συμβουλεύειν μᾶλλον ὅπως τὰ δόξαντα συνοίσει σκοπεῖν, ἢ πῶς οἱ παραχρῆμα λόγοι χάριν ἕξουσι. δεῖ γὰρ τοῖς ἐπὶ τῶν λόγων εὐδοκιμοῦσι συμφέροντός τινος ἔργου πρᾶξιν προσεῖναι, ἵνα μὴ νῦν μόνον, ἀλλ’ ἀεὶ τὰ ῥηθέντα καλῶς ἔχῃ.", "st": "62.9.2"}, {"sp": "SEC", "t": "Προοίμιον Ιʹ", "st": "62.10"}, {"sp": "N", "t": "εἰ μὲν ἐγνώκατ’, ὦ ἄνδρες Ἀθηναῖοι, τί βέλτιστον ὂν τυγχάνει πρᾶξαι περὶ τῶν παρόντων, ἁμάρτημα τὸ συμβουλεύειν προτιθέναι· ἃ γὰρ αὐτοὶ πρὶν ἀκοῦσαι δοκιμάζετε συμφέρειν, τί δεῖ ταῦτ’ ἀκούοντας μάτην ἐνοχλεῖσθαι; εἰ δὲ σκοπεῖτε καὶ βουλεύεσθ’ ὡς ἐκ τῶν ῥηθησομένων δοκιμάσαι δέον, οὐκ ὀρθῶς ἔχει τὸ κωλύειν τοὺς βουλομένους λέγειν. παρὰ μὲν γὰρ τῶν ὅλως ἀποστερεῖσθ’ ἐκ τοῦ τοῦτο ποιεῖν, εἴ τι χρήσιμον ἐντεθύμηνται· τοὺς δ’ ἀφέντας ἃ τυγχάνουσιν ἐγνωκότες, ὧν ὑμᾶς ἐπιθυμεῖν οἴονται, ταῦτα ποιεῖτε συμβουλεύειν.", "st": "62.10.1"}, {"sp": "N", "t": "ἔστιν δ’ ἁμαρτάνειν μὲν βουλομένων τὸ συναναγκάζειν τὸν παριόνθ’ ἃ βούλεσθε λέγειν, βουλευομένων δ’ ἀκούσαντας ἃ γιγνώσκει σκοπεῖν, κἄν τι καλῶς ἔχῃ, χρῆσθαι. λέγω δὲ ταῦτ’ οὐκ ἐναντία τοῖς ὑμῖν ἀρέσκουσιν μέλλων παραινεῖν, ἀλλ’ ἐκεῖν’ εἰδώς, ὅτι ἂν μὲν μὴ ’θελήσητε τῶν ἀντιλεγόντων ἀκοῦσαι, ἐξηπατῆσθαι φήσουσιν ὑμᾶς, ἂν δ’ ἀκούσαντες μὴ πεισθῆτε, ἐξεληλεγμένοι παραχρῆμ’ ἔσονται τὰ χείρω παραινοῦντες.", "st": "62.10.2"}, {"sp": "SEC", "t": "Προοίμιον ΙΑʹ", "st": "62.11"}, {"sp": "N", "t": "οἴομαι πάντας ὑμᾶς, ὦ ἄνδρες Ἀθηναῖοι, γιγνώσκειν ὅτι οὐ κρινοῦντες ἥκετε τήμερον οὐδένα τῶν ἀδικούντων, ἀλλὰ βουλευσόμενοι περὶ τῶν παρόντων. δεῖ τοίνυν τὰς μὲν κατηγορίας ὑπερθέσθαι πάσας, καὶ τότ’ ἐν ὑμῖν λέγειν καθ’ ὅτου πέπεικεν ἕκαστος ἑαυτόν, ὅταν τινὰ κρίνωμεν· εἰ δέ τίς τι χρήσιμον ἢ συμφέρον εἰπεῖν ἔχει, τοῦτο νῦν ἀποφαίνεσθαι. τὸ μὲν γὰρ κατηγορεῖν τοῖς πεπραγμένοις ἐγκαλούντων ἐστίν, τὸ δὲ συμβουλεύειν περὶ τῶν παρόντων καὶ γενησομένων προτίθεται. οὐκοῦν οὐ λοιδορίας οὐδὲ μέμψεως ὁ παρὼν καιρός, ἀλλὰ συμβουλῆς εἶναί μοι δοκεῖ. διὸ πειράσομαι μὲν φυλάξασθαι, ὃ τούτοις ἐπιτιμῶ, μὴ παθεῖν αὐτός, συμβουλεύσαι δ’ ἃ κράτιστα νομίζω περὶ τῶν παρόντων.", "st": "62.11.1"}, {"sp": "SEC", "t": "Προοίμιον ΙΒʹ", "st": "62.12"}, {"sp": "N", "t": "οὐδέν’ ⟨ἂν⟩ ἀντειπεῖν, ὦ ἄνδρες Ἀθηναῖοι, νομίζω, ὡς οὐ κακοῦ πολίτου καὶ φαύλου τὴν γνώμην ἀνδρός ἐστιν οὕτω τινὰ μισεῖν ἢ φιλεῖν τῶν ἐπὶ τὰ κοινὰ προσιόντων ὥστε τοῦ τῇ πόλει βελτίστου μηδὲν φροντίζειν, ἀλλὰ τὰ μὲν πρὸς ἐπήρειαν, τὰ δὲ πρὸς φιλίαν δημηγορεῖν· ἃ ποιοῦσιν ἔνιοι τῶν δευρὶ παριόντων. ἐγὼ δὲ τούτοις μὲν τοσοῦτον ἂν εἴποιμι, ὅτι μοι δοκοῦσιν οὐδ’ εἴ τι πεποιήκασιν τοιοῦτον μέγισθ’ ἡμαρτηκέναι, ἀλλ’ ὅτι δηλοῦσιν οὐδέποτ’ οὐδὲ παύσασθαι παρεσκευασμένοι.", "st": "62.12.1"}, {"sp": "N", "t": "ὑμῖν δὲ παραινῶ μὴ προϊεμένους ὑμᾶς αὐτοὺς ἱκανὸν τοῦτο νομίζειν, δίκην, ὅταν ὑμῖν δόξῃ, παρὰ τούτων λαβεῖν, ἀλλὰ καὶ τούτους, ὅσον ἐστὶν ἐν ὑμῖν, κωλύειν, καὶ αὐτούς, ὥσπερ ὑπὲρ πόλεως προσήκει βουλευομένους, τὰς ἰδίας ἀνελόντας φιλονικίας τὸ κοινῇ βέλτιστον σκοπεῖσθαι, ἐνθυμουμένους ὅτι οὐδείς, οὐδ’ ἅμα πάντες οἱ πολιτευόμενοι, τῶν νόμων, ἐφ’ οἷς ὑμεῖς ἐστε, ἀξιόχρεῴ εἰσι διαφθαρέντων δίκην δοῦναι.", "st": "62.12.2"}, {"sp": "SEC", "t": "Προοίμιον ΙΓʹ", "st": "62.13"}, {"sp": "N", "t": "ἴσως ἐπίφθονον ἄν τισιν, ὦ ἄνδρες Ἀθηναῖοι, δόξειεν εἶναι, εἴ τις ὢν ἰδιώτης καὶ τῶν πολλῶν ὑμῶν εἷς, ἑτέρων συμβεβουλευκότων, οἳ καὶ τῷ πάλαι πολιτεύεσθαι καὶ τῷ παρ’ ὑμῖν δόξαν ἔχειν προέχουσιν, παρελθὼν εἴποι, ὅτι οὐ μόνον αὑτῷ δοκοῦσιν οὐκ ὀρθῶς λέγειν, ἀλλ’ οὐδ’ ἐγγὺς εἶναι τοῦ τὰ δέοντα γιγνώσκειν. οὐ μὴν ἀλλ’ ἔγωγ’ οὕτω σφόδρ’ οἶμαι μᾶλλον ὑμῖν συμφέροντ’ ἐρεῖν τούτων, ὥστ’ οὐκ ὀκνήσω πάνθ’ ἃ τυγχάνουσιν εἰρηκότες, ἄξια μηδενὸς εἶναι φῆσαι. νομίζω δὲ καὶ ὑμᾶς ὀρθῶς ἂν ποιεῖν, εἰ μὴ τὸν λέγοντα, ἀλλὰ τὰ συμβουλευόμενα σκοποῖτε. δεῖ γάρ, ὦ ἄνδρες Ἀθηναῖοι, τὴν παρ’ ὑμῶν εὔνοιαν μή τισιν, ὥσπερ ἐκ γένους, ἀλλὰ τοῖς τὰ βέλτιστ’ ἀεὶ λέγουσιν ὑπάρχειν.", "st": "62.13.1"}, {"sp": "SEC", "t": "Προοίμιον ΙΔʹ", "st": "62.14"}, {"sp": "N", "t": "βουλοίμην ἂν ὑμᾶς, ὦ ἄνδρες Ἀθηναῖοι, προσέχοντας, ἃ μέλλω λέγειν, ἀκοῦσαι· καὶ γάρ ἐστιν οὐ μικρά. ἐγὼ θαυμάζω τί δή ποτε, πρὶν μὲν εἰς τὴν ἐκκλησίαν ἀναβῆναι, ὅτῳ τις ἂν ὑμῶν ἐντύχῃ, οὗτος εὐπόρως εἰπεῖν ἔχει δι’ ὧν ἂν τὰ παρόντα πράγματα βελτίω γένοιτο· καὶ πάλιν αὐτίκα δὴ μάλ’ ἐὰν ἀπέλθητε, ὁμοίως ἕκαστος ἐρεῖ τὰ δέοντα· ἐν δὲ τῷ περὶ τούτων σκοπεῖν ὄντες καὶ συνειλεγμένοι πάντα μᾶλλον ἢ ταῦτα λεγόντων τινῶν ἀκούετε.", "st": "62.14.1"}, {"sp": "N", "t": "ἆρά γ’, ὦ ἄνδρες Ἀθηναῖοι, γνῶναι μὲν ἔστιν ἑκάστῳ τὰ δέονθ’ ὑμῶν καὶ κατὰ τῶν ἄλλων εἰπεῖν ἐπίσταται, ποιῶν δ’ αὐτὸς ἕκαστος οὐ χαίρει, εἶτ’ ἰδίᾳ μέν, ὡς ἄρ’ αὐτὸς ἑτοίμως τὰ βέλτιστ’ ⟨ἂν⟩ πράττειν δόξων, τοῖς ἄλλοις ἐπιτιμᾷ, κοινῇ δ’ εὐλαβεῖσθε τὰ τοιαῦτα ψηφίζεσθαι δι’ ὧν ἐν τῷ λῃτουργεῖν τι τῶν καθηκόντων ἅπαντες ἔσεσθε;", "st": "62.14.2"}, {"sp": "N", "t": "εἰ μὲν τοίνυν μηδένα καιρὸν οἴεσθ’ ἥξειν ὃς εἴσω τῆς εἰρωνείας ἀφίξεται ταύτης, καλῶς ἂν ἔχοι τοῦτον τὸν τρόπον διάγειν· εἰ δὲ τὰ πράγμαθ’ ὁρᾶτ’ ἐγγυτέρω προσάγοντα, δεῖ σκοπεῖσθαι ὅπως μὴ πλησίον αὐτοῖς μαχεῖσθε, ἃ πόρρωθεν ἔξεστι φυλάξασθαι, καὶ τοὺς νῦν περιοφθέντας ἐφηδομένους ὕστερον ἕξεθ’ οἷς ἂν πάσχητε.", "st": "62.14.3"}, {"sp": "SEC", "t": "Προοίμιον ΙΕʹ", "st": "62.15"}, {"sp": "N", "t": "περὶ μὲν τῶν παρόντων, ὦ ἄνδρες Ἀθηναῖοι, πραγμάτων τῇ πόλει, καίπερ οὐκ ἐχόντων ὡς δεῖ, οὐ πάνυ μοὶ δοκεῖ τῶν χαλεπῶν εἶναι ζητῆσαι τί ἄν τις πράξας βελτίω ποιήσειεν. ὅντινα μέντοι χρὴ τρόπον πρὸς ὑμᾶς εἰπεῖν περὶ αὐτῶν, τοῦτο παμπόλλην δυσκολίαν ἔχειν νομίζω, οὐχ ὡς οὐ συνησόντων ὅ τι ἄν τις λέγῃ, ἀλλ’ οὕτω πολλὰ καὶ ψευδῆ καὶ πάντα μᾶλλον ἢ τὰ βέλτιστα τοῖς πράγμασιν συνειθίσθαι μοι δοκεῖτ’ ἀκούειν, ὥστε δέδοικα μὴ τῷ νῦν τὰ βέλτιστ’ εἰπόντι, ἣν τοῖς ἐξηπατηκόσιν προσῆκεν ἀπέχθειαν ὑπάρχειν παρ’ ὑμῶν, ταύτην ἀπενέγκασθαι συμβῇ.", "st": "62.15.1"}, {"sp": "N", "t": "ὁρῶ γὰρ ὑμᾶς πολλάκις οὐ τοὺς αἰτίους τῶν πραγμάτων μισοῦντας, ἀλλὰ τοὺς ὑστάτους περὶ αὐτῶν εἰπόντας τι πρὸς ὑμᾶς. οὐ μὴν ἀλλὰ καίπερ οὕτως ἀκριβῶς ταῦτα λογιζόμενος, ὅμως οἶμαι δεῖν πάντα παρεὶς τἄλλα περὶ αὐτῶν τῶν παρόντων ἃ κράτιστα νομίζω λέγειν.", "st": "62.15.2"}, {"sp": "SEC", "t": "Προοίμιον ΙϚʹ", "st": "62.16"}, {"sp": "N", "t": "ἐβουλόμην ἂν ὑμᾶς, ὦ ἄνδρες Ἀθηναῖοι, ᾗ πρὸς τοὺς ἄλλους ἅπαντας εἰώθατε προσφέρεσθαι φιλανθρωπίᾳ, ταύτῃ καὶ πρὸς ὑμᾶς αὐτοὺς χρῆσθαι· νυνὶ δ’ ἀμείνους ἐστὲ τὰ τῶν ἄλλων δείν’ ἐπανορθοῦν ἢ τῶν ὑμῖν αὐτοῖς συμβαινόντων φροντίζειν. ἴσως μὲν οὖν αὐτὸ τοῦτό τις ἂν φήσειε μέγιστον ἔπαινον φέρειν τῇ πόλει, τὸ μηδενὸς ἕνεκα κέρδους ἰδίου πολλοὺς κινδύνους ὑπὲρ αὐτοῦ τοῦ δικαίου προῃρῆσθαι. ἐγὼ δὲ ταύτην τ’ ἀληθῆ τὴν δόξαν εἶναι νομίζω κατὰ τῆς πόλεως καὶ βούλομαι, κἀκεῖνο δ’ ὑπολαμβάνω σωφρόνων ἀνθρώπων ἔργον εἶναι, ἴσην πρόνοιαν τῶν αὑτοῖς οἰκείων ὅσηνπερ τῶν ἀλλοτρίων ποιεῖσθαι, ἵνα μὴ φιλάνθρωποι μόνον, ἀλλὰ καὶ νοῦν ἔχοντες φαίνησθε.", "st": "62.16.1"}, {"sp": "SEC", "t": "Προοίμιον ΙΖʹ", "st": "62.17"}, {"sp": "N", "t": "ἴσως, ὦ ἄνδρες Ἀθηναῖοι, προσήκει τῷ βουλομένῳ τι παραινεῖν ὑμῖν οὕτω πειρᾶσθαι λέγειν ὡς καὶ δυνήσεσθ’ ὑπομεῖναι· εἰ δὲ μὴ τοῦτο, ἀφέντα τοὺς ἄλλους ἅπαντας λόγους, περὶ αὐτῶν ὧν σκοπεῖτε συμβουλεύειν, καὶ ταῦθ’ ὡς διὰ βραχυτάτων. οὐ γὰρ ἐνδείᾳ μοι δοκεῖτε λόγων οὐδὲ νῦν ὁρᾶν τὰ πράγματα πάντα λελυμασμένα, ἀλλὰ τῷ τοὺς μὲν ἑαυτῶν ἕνεκα δημηγορεῖν καὶ πολιτεύεσθαι, τοὺς δὲ μήπω τούτου δεδωκότας πεῖραν μᾶλλον ὅπως εὖ δόξουσι λέγειν σπουδάζειν, ἢ πῶς ἔργον ἐξ ὧν λέγουσί τι συμφέρον πραχθήσεται. ἐγὼ δ’ ἵνα μὴ λάθω τοὐναντίον οὗ φημὶ δεῖν αὐτὸς ποιῶν, καὶ πλείω περὶ τῶν ἄλλων ἢ περὶ ὧν ἀνέστην λέγων, ἀφεὶς τἄλλα πάντα, ἃ παραινῶ καὶ δὴ πειράσομαι πρὸς ὑμᾶς εἰπεῖν.", "st": "62.17.1"}, {"sp": "SEC", "t": "Προοίμιον ΙΗʹ", "st": "62.18"}, {"sp": "N", "t": "δοκεῖτέ μοι δικαίως ἄν, ὦ ἄνδρες Ἀθηναῖοι, προσέχειν τὸν νοῦν, εἴ τις ὑπόσχοιθ’ ὑμῖν ταὐτὰ δίκαια καὶ συμφέροντα δείξειν ὄνθ’ ὑπὲρ ὧν βουλευόμεθα. ἐγὼ τοίνυν οἴομαι τοῦτο ποιήσειν οὐ χαλεπῶς, ἂν ὑμεῖς βραχύ τί μοι πεισθῆτε πάνυ. μὴ πάντα, ὡς ἕκαστος ἔχει γνώμης ὑμῶν περὶ τῶν παρόντων, ὀρθῶς ἐγνωκέναι πεπείσθω, ἀλλ’ ἐὰν παρὰ ταῦτά τι συμβαίνῃ λέγεσθαι, σκοπείτω πάνθ’ ὑπομείνας ἀκοῦσαι, εἶτ’ ἂν ὀρθῶς εἰρῆσθαί τι δοκῇ, χρήσθω. οὐ γὰρ ἧττον ὑμέτερον ἔσται τῶν χρησαμένων τὸ κατορθωθὲν ⟨ἢ⟩ τοῦ πρὸς ὑμᾶς εἰπόντος. ἡ μὲν οὖν ἀρχὴ τοῦ σκοπεῖν ὀρθῶς ἐστιν μὴ βεβουλεῦσθαι πρὶν ἐξ ὧν δεῖ βουλεύσασθαι ἀκοῦσαι. οὐ γὰρ αὑτὸς οὔτε καιρὸς οὔτε τρόπος τοῦ τ’ ἐπικυρῶσαι τὰ δοκοῦντα καὶ τοῦ σκέψασθαι τί πρῶτον δοκεῖ συμφέρειν.", "st": "62.18.1"}, {"sp": "SEC", "t": "Προοίμιον ΙΘʹ", "st": "62.19"}, {"sp": "N", "t": "μεθ’ ὑμῶν, ὦ ἄνδρες Ἀθηναῖοι, παρελήλυθα βουλευσόμενος, πότερον χρή με λέγειν ἢ μή. διὸ δ’ αὐτὸς τοῦτ’ ἀπορῶ κρῖναι, φράσω πρὸς ὑμᾶς. ἀναγκαῖον εἶναί μοι δοκεῖ τῷ μήθ’ αὑτῷ μήτε τισὶν χαρίσασθαι βουλομένῳ, ἀλλ’ ὑπὲρ ὑμῶν εἰπεῖν ἃ πέπεικεν ἑαυτὸν μάλιστα συμφέρειν, καὶ συνειπεῖν ἃ καλῶς λέγουσιν ἀμφότεροι, καὶ τοὐναντίον ἀντειπεῖν ὅσα μὴ δίκαι’ ἀξιοῦσιν. εἰ μὲν οὖν ὑμεῖς ὑπομείναιτ’ ἀκοῦσαι ταῦτ’ ἀμφότερα διὰ βραχέων, πολλῷ βέλτιον ἂν περὶ τῶν λοιπῶν βουλεύσαισθε· εἰ δὲ πρὶν μαθεῖν ἀποσταίητε, γένοιτ’ ἂν ἐμοὶ μηδετέρους ἀδικοῦντι πρὸς ἀμφοτέρους διαβεβλῆσθαι. τοῦτο δ’ οὐχὶ δίκαιός εἰμι παθεῖν. ἐὰν μὲν οὖν κελεύητε, ἕτοιμός εἰμι λέγειν· εἰ δὲ μή, καὶ σιωπᾶν ἔχει μοι καλῶς.", "st": "62.19.1"}, {"sp": "SEC", "t": "Προοίμιον Κʹ", "st": "62.20"}, {"sp": "N", "t": "καὶ δίκαιον, ὦ ἄνδρες Ἀθηναῖοι, καὶ συμφέρον ὑμῖν ἡγοῦμαι τὰς μὲν αἰτίας καὶ τὰς κατηγορίας, ὅταν βουλεύεσθαι δέῃ, παραλείπειν, περὶ τῶν παρόντων δὲ λέγειν ὅ τι βέλτιστον ἕκαστος ἡγεῖται. ὅτι μὲν γάρ τινων αἰτίων ὄντων κακῶς τὰ πράγματ’ ἔχει, πάντες ἐπιστάμεθα· ἐξ ὅτου δὲ τρόπου βελτίω δύναιτ’ ἂν γενέσθαι, τοῦτο τοῦ συμβουλεύοντος ἔργον εἰπεῖν.", "st": "62.20.1"}, {"sp": "N", "t": "ἔπειτ’ ἔγωγε νομίζω καὶ κατηγόρους εἶναι τῶν ἀδικούντων χαλεποὺς οὐ τοὺς ἐν τοιούτοις καιροῖς ἐξετάζοντας τὰ πεπραγμένα, ὅτ’ οὐδεμίαν δώσουσι δίκην, ἀλλὰ τοὺς τοιοῦτό τι συμβουλεῦσαι δυνηθέντας ἀφ’ οὗ βελτίω τὰ παρόντα γένοιτ’ ἄν· διὰ γὰρ τούτους ἐφ’ ἡσυχίας καὶ παρ’ ἐκείνων ἐγγένοιτ’ ἂν ὑμῖν δίκην λαβεῖν.", "st": "62.20.2"}, {"sp": "N", "t": "τοὺς μὲν οὖν ἄλλους λόγους πάντας περιέργους ἡγοῦμαι, ἃ δ’ ἂν οἶμαι συνενεγκεῖν περὶ ὧν νυνὶ σκοπεῖτε, ταῦτ’ εἰπεῖν πειράσομαι, τοσοῦτον ἀξιώσας μόνον· ἂν ἄρα του μεμνῶμαι τῶν πεπραγμένων, μὴ κατηγορίας μ’ ἕνεχ’ ἡγεῖσθε λέγειν, ἀλλ’ ἵνα δείξας ἃ τόθ’ ἡμάρτετε, νῦν ἀποτρέψω ταὐτὰ παθεῖν.", "st": "62.20.3"}, {"sp": "SEC", "t": "Προοίμιον ΚΑʹ", "st": "62.21"}, {"sp": "N", "t": "εἰ καὶ τὸν ἄλλον χρόνον, ὦ ἄνδρες Ἀθηναῖοι, μηδενὶ συμπολιτευόμενοι τοσαύτην ἤγομεν ἡσυχίαν ὅσηνπερ ἐν τῷ παρόντι, οὔτε τὰ νῦν ἂν γεγενημένα συμβῆναι νομίζω, τῶν τ’ ἄλλων οἶμαι πολλὰ βέλτιον ἂν ἡμῖν ἔχειν. νῦν δ’ ὑπὸ τῆς ἐνίων ἀσελγείας οὔτε παρελθεῖν οὔτ’ εἰπεῖν οὔθ’ ὅλως λόγου τυχεῖν ἔστιν.", "st": "62.21.1"}, {"sp": "N", "t": "ὅθεν συμβαίνει πολλὰ καὶ οὐκ ἐπιτήδει’ ἴσως. εἰ μὲν οὖν ἀεὶ ταὐτά, πυνθάνεσθαι, καὶ σκοπεῖν ὅ τι χρὴ ποιῆσαι, καὶ πάσχειν οἷάπερ νυνὶ βούλεσθε, ψηφιεῖσθ’ ἅπερ ἐκ τῶν παρεληλυθότων χρόνων, καθέλκειν τριήρεις, ἐμβαίνειν, εἰσφέρειν, πάντα ταῦτ’ ἤδη· ἃ τριῶν ἡμερῶν ἢ πέντε, ἂν σιωπηθῇ τὰ παρὰ τῶν πολεμίων καὶ σχῶσιν ἡσυχίαν ἐκεῖνοι, πάλιν οὐκέτι καιρὸν εἶναι πράττειν ὑπολήψεσθε. ὅπερ, ἡνίκ’ ἐν Ἑλλησπόντῳ Φίλιππον ἠκούσαμεν, συνέβη, καὶ πάλιν ἡνίκ’ εἰς Μαραθῶνα τριήρεις αἱ λῃστρίδες προσέσχον.", "st": "62.21.2"}, {"sp": "N", "t": "ὡς γὰρ ἂν χρήσαιτό τις, ὦ ἄνδρες Ἀθηναῖοι, καλῶς δυνάμει παρεσκευασμένῃ, οὕτως ὑμεῖς εἰώθατε τῷ βουλεύεσθαι χρῆσθαι, ὀξέως. δεῖ δὲ βουλεύεσθαι μὲν ἐφ’ ἡσυχίας, ποιεῖν δὲ τὰ δόξαντα μετὰ σπουδῆς, καὶ λογίσασθαι τοῦθ’ ὅτι εἰ μὴ καὶ τροφὴν ἱκανὴν ποριεῖτε καὶ στρατηγόν τινα τοῦ πολέμου νοῦν ἔχοντα προστήσεσθε καὶ μένειν ἐπὶ τῶν οὕτω δοξάντων ἐθελήσετε, ψηφίσμαθ’ ὑμῖν περιέσται, καὶ παραναλώσετε μὲν πάνθ’ ὅσ’ ἂν δαπανήσητε, βελτίω δ’ οὐδ’ ὁτιοῦν τὰ πράγματ’ ἔσται, κρινεῖτε δ’ ὃν ἂν βούλησθ’ ὀργισθέντες. ἐγὼ δὲ βούλομαι τοὺς ἐχθροὺς ὑμᾶς ἀμυνομένους ὀφθῆναι πρότερον ἢ τοὺς πολίτας κρίνοντας· οὐ γὰρ ἡμῖν αὐτοῖς πολεμεῖν μᾶλλον ἢ ’κείνοις ἐσμὲν δίκαιοι.", "st": "62.21.3"}, {"sp": "N", "t": "ἵν’ οὖν μή, τὸ ῥᾷστον ἁπάντων, ἐπιτιμήσω μόνον, ὃν τρόπον ἄν μοι δοκεῖτε ταῦτα ποιῆσαι διδάξω, δεηθεὶς ὑμῶν μὴ θορυβῆσαι μηδ’ ἀναβάλλειν νομίσαι με καὶ χρόνον ἐμποιεῖν. οὐ γὰρ οἱ ταχὺ καὶ τήμερον εἰπόντες μάλιστ’ εἰς [τὸ] δέον λέγουσιν ʽοὐ γὰρ ἂν τά γ’ ἤδη γεγενημένα κωλῦσαι δυνηθείημεν τῇ νυνὶ βοηθείᾀ, ἀλλ’ ὃς ἂν δείξῃ τίς πορισθεῖσα παρασκευὴ διαμεῖναι δυνήσεται, τέως ἂν ἢ περιγενώμεθα τῶν ἐχθρῶν ἢ πεισθέντες διαλυσώμεθα τὸν πόλεμον· οὕτω γὰρ οὐκέτι τοῦ λοιποῦ πάσχοιμεν ἂν κακῶς.", "st": "62.21.4"}, {"sp": "SEC", "t": "Προοίμιον ΚΒʹ", "st": "62.22"}, {"sp": "N", "t": "οἶμαι πάντας ἂν ὑμᾶς, ὦ ἄνδρες Ἀθηναῖοι, ὁμολογῆσαι, ὅτι δεῖ τὴν πόλιν ἡμῶν, ὅταν μὲν περὶ τῶν ἰδίων τινὸς τῶν αὑτῆς βουλεύηται, ἴσην πρόνοιαν ἔχειν τοῦ συμφέροντος ὅσηνπερ τοῦ δικαίου, ὅταν δ’ ὑπὲρ τῶν συμμαχικῶν ἢ τῶν κοινῶν, οἷον καὶ τὸ νυνὶ παρόν, μηδενὸς οὕτως ὡς τοῦ δικαίου φροντίζειν. ἐν μὲν γὰρ ἐκείνοις τὸ λυσιτελὲς ἐξαρκεῖ, ἐν δὲ τοῖς τοιούτοις καὶ τὸ καλὸν προσεῖναι δεῖ.", "st": "62.22.1"}, {"sp": "N", "t": "τῶν μὲν γὰρ πράξεων, εἰς οὓς ἂν ἥκωσι, κύριοι καθίστανται· τῆς δ’ ὑπὲρ τούτων δόξης οὐδεὶς τηλικοῦτός ἐσθ’ ὅστις ἔσται κύριος, ἀλλ’ ὁποίαν τιν’ ἂν τὰ πραχθέντ’ ἔχῃ δόξαν, τοιαύτην οἱ πολλοὶ περὶ τῶν πραξάντων διήγγειλαν. διὸ δεῖ σκοπεῖν καὶ προσέχειν ὅπως δίκαια φανεῖται.", "st": "62.22.2"}, {"sp": "N", "t": "χρῆν μὲν οὖν οὕτως ἅπαντας ἔχειν τὴν διάνοιαν περὶ τῶν ἀδικουμένων ὥσπερ ἄν, εἴ τι γένοιτο, ὃ μὴ συμβαίη, τοὺς ἄλλους ἀξιώσειε πρὸς αὑτὸν ἕκαστος ἔχειν. ἐπειδὴ δὲ καὶ παρὰ τὴν αὑτῶν γνώμην ἐναντιοῦνταί τινες, μικρὰ πρὸς τούτους εἰπών, ἃ βέλτισθ’ ὑμῖν ὑπολαμβάνω, ταῦτ’ ἤδη συμβουλεύσω.", "st": "62.22.3"}, {"sp": "SEC", "t": "Προοίμιον ΚΓʹ", "st": "62.23"}, {"sp": "N", "t": "οὐ μικρὰν ἄν μοι δοκεῖτ’, ὦ ἄνδρες Ἀθηναῖοι, ζημίαν νομίσαι, εἴ τις ἀηδὴς δόξα καὶ μὴ προσήκουσα τῇ πόλει παρὰ τοῖς πολλοῖς περιγίγνοιτο. τοῦτο τοίνυν οὕτω καλῶς ἐγνωκότες οὐκ ἀκόλουθα ποιεῖτε τὰ λοιπά, ἀλλ’ ὑπάγεσθ’ ἑκάστοτε πράττειν ἔνια, ἃ οὐδ’ ἂν αὐτοὶ φήσαιτε καλῶς ἔχειν. ἐγὼ δ’ οἶδα μὲν τοῦθ’ ὅτι τοὺς ἐπαινοῦντας ἥδιον προσδέχονται πάντες τῶν ἐπιτιμώντων· οὐ μὴν οἴομαι δεῖν, ταύτην τὴν φιλανθρωπίαν διώκων, λέγειν παρ’ ἃ συμφέρειν ὑμῖν ἡγοῦμαι.", "st": "62.23.1"}, {"sp": "N", "t": "κγ", "st": "62.23.2"}, {"sp": "N", "t": "τὴν μὲν [οὖν] ἀρχὴν εἰ καλῶς ἐγιγνώσκετε, οὐδὲν δεῖν κοινῇ ποιεῖν ὑποληπτέον ἦν ὧν ἰδίᾳ μέμφεσθε, ἵνα μὴ συνέβαινεν ὅπερ νυνὶ γίγνεται· περιιὼν μὲν ἕκαστος “ὡς αἰσχρὰ καὶ δεινά” λέγει καὶ “μέχρι τοῦ προβήσεται τὰ πράγματα;” συγκαθεζόμενος δ’ αὐτὸς ἕκαστός ἐστι τῶν τὰ τοιαῦτα ποιούντων. ἐγὼ μὲν οὖν ἐβουλόμην ἄν, ὥσπερ ὅτι ὑμῖν συμφέρει τοῦ τὰ βέλτιστα λέγοντος ἀκούειν οἶδα, οὕτως εἰδέναι συνοῖσον καὶ τῷ τὰ βέλτιστ’ εἰπόντι· πολλῷ γὰρ ἂν ἥδιον εἶχον. νῦν δὲ φοβοῦμαι μέν, ὅμως δ’ ἅ γε πιστεύω χρηστὰ φανεῖσθαι, κἂν ὑμεῖς μὴ πεισθῆτε, οὐκ ἀποτρέψομαι λέγειν.", "st": "62.23.2"}, {"sp": "SEC", "t": "Προοίμιον ΚΔʹ", "st": "62.24"}, {"sp": "N", "t": "εἰ καὶ μηδὲν ἄλλο τις, ὦ ἄνδρες Ἀθηναῖοι, πρότερον παρ’ ὑμῖν εἰρηκὼς εἴη, νῦν γε λέγων περὶ ὧν οὐκ ὀρθῶς ἐγκαλοῦσιν οἱ πρέσβεις τῇ πόλει, παρὰ πάντων ἄν μοι δοκεῖ δικαίως συγγνώμης τυχεῖν. καὶ γὰρ ἐν ἄλλοις μέν τισιν ἡττᾶσθαι τῶν ἐναντίων οὐχ οὕτως ὄνειδος ὡς ἀτύχημ’ ἂν φανείη· καὶ γὰρ τῇ τύχῃ καὶ τοῖς ἐφεστηκόσι καὶ πολλοῖς μέτεστι τοῦ καλῶς ἢ μὴ ἀγωνίσασθαι· ἐν δὲ τῷ τὰ δίκαι’ ὑπὲρ αὑτῶν μὴ ἔχειν ἀξίως τῶν ὑπαρχόντων εἰπεῖν αὐτῆς τῆς γνώμης τῆς τῶν τοῦτο παθόντων τὸ ὄνειδος εὑρήσομεν.", "st": "62.24.1"}, {"sp": "N", "t": "εἰ μὲν οὖν ἕτεροί τινες ἦσαν ἐν οἷς ἐγίγνονθ’ οἱ λόγοι περὶ ὑμῶν, οὔτε τούτους ἂν οἶμαι ῥᾳδίως οὕτω ψεύδεσθαι, οὔτε τοὺς ἀκούοντας πολλὰ τῶν εἰρημένων ἀνασχέσθαι. νῦν δὲ τἄλλα τ’ οἶμαι τῆς ὑμετέρας πλεονεκτοῦσιν εὐηθείας ἅπαντες, καὶ δὴ καὶ τοῦτο νῦν οὗτοι· ἀκροαταῖς γὰρ ἐχρήσαντο καθ’ ὑμῶν ὑμῖν οἵοις οὐδέσιν ἂν τῶν ἄλλων, ἀκριβῶς οἶδα τοῦτ’ ἐγώ.", "st": "62.24.2"}, {"sp": "N", "t": "ἄξιον δ’ εἶναί μοι δοκεῖ διὰ ταῦτα τοῖς θεοῖς χάριν ὑμᾶς ἔχειν, ὦ ἄνδρες Ἀθηναῖοι, καὶ τούτους μισεῖν. τὸ μὲν γὰρ ὁρᾶν τούτους τὸν Ῥοδίων δῆμον, τὸν πολὺ τούτων ποτ’ ἀσελγεστέρους λόγους λέγοντα πρὸς ὑμᾶς, ἱκέτην ὑμέτερον γεγενημένον εὐτύχημ’ εἶναι νομίζω τῆς πόλεως· τὸ δὲ τοὺς ἀνοήτους τούτους μήτε τοῦτο λογίζεσθαι, παρὸν οὕτως ἐναργὲς ἰδεῖν, μήθ’ ὅτι πολλάκις καθ’ ἕν’ αὐτῶν ἕκαστον ὑμεῖς σεσῴκατε, καὶ πλείω πράγματ’ ἐσχήκατε τὴν τούτων θρασύτητα καὶ κακοδαιμονίαν ἐπανορθοῦντες, ἐπειδὰν δι’ ἑαυτοὺς ἀνέλωνται πόλεμον, ἢ τὰ ὑμέτερ’ αὐτῶν πράττοντες, τοῦτο παμπόλλην ὑμῖν ὀργὴν εἰκότως ἂν παραστῆσαί μοι δοκεῖ.", "st": "62.24.3"}, {"sp": "N", "t": "οὐ μὴν ἀλλ’ ἴσως τούτοις μὲν εἵμαρται μηδέποτ’ εὖ πράττουσιν εὖ φρονῆσαι· ἡμῖν δὲ προσήκει καὶ δι’ ἡμᾶς αὐτοὺς καὶ διὰ τἄλλ’ ἃ πέπρακται τῇ πόλει, σπουδάσαι δεῖξαι πᾶσιν ἀνθρώποις ὅτι καὶ πρότερον καὶ νῦν καὶ ἀεὶ ἡμεῖς μὲν τὰ δίκαια προαιρούμεθα πράττειν, ἕτεροι δέ τινες καταδουλοῦσθαι βουλόμενοι τοὺς αὑτῶν πολίτας διαβάλλουσιν πρὸς ἡμᾶς.", "st": "62.24.4"}, {"sp": "SEC", "t": "Προοίμιον ΚΕʹ", "st": "62.25"}, {"sp": "N", "t": "εἰ μετὰ τῆς αὐτῆς γνώμης, ὦ ἄνδρες Ἀθηναῖοι, τούς τε λόγους ἠκούετε τῶν συμβουλευόντων καὶ τὰ πράγματ’ ἐκρίνετε, πάντων ἀσφαλέστατον ἦν ἂν τὸ συμβουλεύειν. καὶ γὰρ εὐτυχῶς καὶ ἄλλως πράξασι ʽλέγειν γὰρ εὐφήμως πάντα δεἶ κοίν’ ἂν ἦν τὰ τῆς αἰτίας ὑμῖν καὶ τῷ πείσαντι. νῦν δ’ ἀκούετε μὲν τῶν ἃ βούλεσθε λεγόντων ἥδιστα, αἰτιᾶσθε δὲ πολλάκις ἐξαπατᾶν ὑμᾶς αὐτούς, ἐὰν μὴ πάνθ’ ὃν ἂν ὑμεῖς τρόπον βούλησθε γένηται,", "st": "62.25.1"}, {"sp": "N", "t": "οὐ λογιζόμενοι τοῦθ’ ὅτι τοῦ μὲν ζητῆσαι καὶ λογίσασθαι τὰ βέλτιστα, ὡς ἄνθρωπος, καὶ πρὸς ὑμᾶς εἰπεῖν αὐτὸς ἕκαστός ἐστιν κύριος, τοῦ δὲ πραχθῆναι ταῦτα καὶ συνενεγκεῖν ἐν τῇ τύχῃ τὸ πλεῖστον μέρος γίγνεται. ἔστιν δ’ ἄνθρωπον ὄντ’ ἀγαπητὸν τῆς αὑτοῦ διανοίας λόγον ὑπέχειν· τῆς δὲ τύχης πρὸς ὑποσχεῖν ἕν τι τῶν ἀδυνάτων.", "st": "62.25.2"}, {"sp": "N", "t": "εἰ μὲν οὖν ηὑρημένον ἦν πῶς ἄν τις ἀσφαλῶς ἄνευ κινδύνου δημηγοροίη, μανία παραλείπειν τοῦτον ⟨ἂν⟩ ἦν τὸν τρόπον· ἐπεὶ δ’ ἀνάγκη τὸν περὶ τῶν μελλόντων πραγμάτων γνώμην ἀποφαινόμενον [κοινωνεῖν τοῖς ἀπ’ αὐτῶν γενομένοις] καὶ μετέχειν τῆς ἀπὸ τούτων αἰτίας, αἰσχρὸν ἡγοῦμαι λέγειν μὲν ὡς εὔνους, μὴ ὑπομένειν δέ, εἴ τις ἐκ τούτου κίνδυνος ἔσται. εὔχομαι δὲ τοῖς θεοῖς, ἃ καὶ τῇ πόλει κἀμοὶ συμφέρειν μέλλει, ταῦτ’ ἐμοί τ’ εἰπεῖν ἐλθεῖν ἐπὶ νοῦν καὶ ὑμῖν ἑλέσθαι. τὸ γὰρ πάντα τρόπον ζητεῖν νικῆσαι, δυοῖν θάτερον, ἢ μανίας ἢ κέρδους ἕνεκ’ ἐσπουδακότος φήσαιμ’ ἂν εἶναι.", "st": "62.25.3"}, {"sp": "SEC", "t": "Προοίμιον ΚϚʹ", "st": "62.26"}, {"sp": "N", "t": "εἴη μέν, ὦ ἄνδρες Ἀθηναῖοι, καὶ περὶ ὧν νυνὶ τυγχάνετ’ ἐκκλησιάζοντες καὶ περὶ τῶν ἄλλων ἁπάντων ταὐτὰ καὶ δοκοῦντα βέλτισθ’ ὑμῖν εἶναι καὶ ὄνθ’ ὡς ἀληθῶς. δεῖ μέντοι περὶ πραγμάτων μεγάλων βουλευομένους καὶ κοινῶν, ἁπάντων ἐθέλειν ἀκούειν τῶν συμβουλευόντων, ὡς ἐμοὶ δοκεῖ, ἐνθυμουμένους ὅτι αἰσχρόν ἐστιν, ὦ ἄνδρες Ἀθηναῖοι, νῦν μὲν βουλομένων τι παραινεῖν ἐνίων θορυβεῖν, ὕστερον δὲ κατηγορούντων τῶν αὐτῶν τούτων τῶν πεπραγμένων ἡδέως ἀκούειν.", "st": "62.26.1"}, {"sp": "N", "t": "ἐγὼ γὰρ οἶδα, νομίζω δὲ καὶ ὑμᾶς, ὅτι νῦν μὲν ἀρέσκουσι μάλισθ’ ὑμῖν οἱ ταὔθ’ οἷς ὑμεῖς βούλεσθε λέγοντες· ἂν δέ τι συμβῇ παρ’ ἃ νῦν οἴεσθε, ὃ μὴ συμβαίη, τούτους μὲν ἐξηπατηκέναι νομιεῖθ’ ὑμᾶς, ὧν δὲ νῦν οὐκ ἀνέχεσθε, τότ’ ὀρθῶς δόξουσι λέγειν. ἔστι δὲ τοῖς μάλιστα πεπεικόσιν ὑμᾶς ταῦτ’ ἐφ’ ὧν νῦν ἐστε, τούτοις καὶ μάλιστα συμφέρον τὸ λόγου τυχεῖν τοὺς ἀντιλέγοντας.", "st": "62.26.2"}, {"sp": "N", "t": "ἂν μὲν γὰρ διδάξαι δυνηθῶσιν ὡς οὐκ ἔστιν ἄρισθ’ ἃ τούτοις δοκεῖ, ὅτ’ οὐδὲν ἡμάρτηταί πω, τοῦτο πράξαντες ἀθῴους τοῦ κινδύνου ποιήσουσιν αὐτούς. ἐὰν δὲ μὴ δυνηθῶσιν, οὔκουν ὕστερόν γ’ ἐπιτιμᾶν ἕξουσιν, ἀλλ’ ὅσ’ ἀνθρώπων ἦν ἔργον, ἀκοῦσαι, τούτων τετυχηκότες, ἂν ἡττῶνται δικαίως στέρξουσιν, καὶ μεθ’ ἁπάντων τῶν ἀποβαινόντων, ὁποῖ’ ἄττ’ ἂν ᾖ, κοινωνήσουσιν.", "st": "62.26.3"}, {"sp": "SEC", "t": "Προοίμιον ΚΖʹ", "st": "62.27"}, {"sp": "N", "t": "οἶμαι δεῖν ὑμᾶς, ὦ ἄνδρες Ἀθηναῖοι, περὶ τηλικούτων βουλευομένους διδόναι παρρησίαν ἑκάστῳ τῶν συμβουλευόντων. ἐγὼ δ’ οὐδεπώποθ’ ἡγησάμην χαλεπὸν τὸ διδάξαι τὰ βέλτισθ’ ὑμᾶς ʽὡς γὰρ ἁπλῶς εἰπεῖν, πάντες ὑπάρχειν ἐγνωκότες ἔμοιγε δοκεῖτἐ, ἀλλὰ τὸ πεῖσαι πράττειν ταῦτα· ἐπειδὰν γάρ τι δόξῃ καὶ ψηφισθῇ, τότ’ ἴσον τοῦ πραχθῆναι ἀπέχει ὅσονπερ πρὶν δόξαι.", "st": "62.27.1"}, {"sp": "N", "t": "ἔστιν μὲν οὖν ὧν ἐγὼ νομίζω χάριν ὑμᾶς τοῖς θεοῖς ὀφείλειν, τὸ τοὺς διὰ τὴν αὑτῶν ὕβριν ὑμῖν πολεμήσαντας ⟨οὐ⟩ πάλαι, νῦν ἐν ὑμῖν μόνοις τῆς αὑτῶν σωτηρίας ἔχειν τὰς ἐλπίδας. ἄξιον δ’ ἡσθῆναι τῷ παρόντι καιρῷ· συμβήσεται γὰρ ὑμῖν, ἂν ἃ χρὴ βουλεύσησθ’ ὑπὲρ αὐτοῦ, τὰς παρὰ τῶν διαβαλλόντων τὴν πόλιν ἡμῶν βλασφημίας ἔργῳ μετὰ δόξης καλῆς ἀπολύσασθαι.", "st": "62.27.2"}, {"sp": "SEC", "t": "Προοίμιον ΚΗʹ", "st": "62.28"}, {"sp": "N", "t": "αἱ μὲν ἐλπίδες, ὦ ἄνδρες Ἀθηναῖοι, μεγάλαι καὶ καλαὶ τῶν προειρημένων, πρὸς ἃς οἴομαι τοὺς πολλοὺς ἄνευ λογισμοῦ τι πεπονθέναι. ἐγὼ δ’ οὐδεπώποτ’ ἔγνων ἕνεκα τοῦ παραχρῆμ’ ἀρέσαι λέγειν τι πρὸς ὑμᾶς, ὅ τι ἂν μὴ καὶ μετὰ ταῦτα συνοίσειν ἡγῶμαι. ἔστι μὲν οὖν τὸ κοινὸν ἔθος τῶν πλείστων τοὺς μὲν συνεπαινοῦντας ἑαυτοῖς ὅ τι ἂν πράττωσι φιλεῖν, πρὸς δὲ τοὺς ἐπιτιμῶντας ἀηδῶς ἔχειν. οὐ μὴν ἀλλὰ δεῖ τὸν εὖ φρονοῦντα τὸν λογισμὸν ἀεὶ τῶν ἐπιθυμιῶν κρείττω πειρᾶσθαι ποιεῖν.", "st": "62.28.1"}, {"sp": "N", "t": "ἐγὼ δ’ ἡδέως μὲν ἂν ἑώρων, ἃ καὶ συνοίσειν ἔμελλε, ταῦτ’ ἐν ἡδονῇ πράττειν ὄνθ’ ὑμῖν, ἵνα καὶ χαριζόμενος καὶ χρηστὰ λέγων ἐφαινόμην. ἐπειδὴ δὲ τἀναντί’ ὁρῶ τούτων ἐπιχειροῦντας ὑμᾶς, οἴομαι δεῖν ἀντειπεῖν, εἰ καί τισιν μέλλω ἀπεχθήσεσθαι. ἂν μὲν οὖν μηδ’ ὑπομείνητ’ ἀκοῦσαι μηδὲ ἕν, οὐ τῷ δοκιμάζοντες διαμαρτεῖν, ἀλλὰ τῷ φύσει πονήρ’ ἐπιθυμεῖν πράττειν τοιαῦτα προαιρεῖσθαι δόξετε. ἐὰν δ’ ἀκούσητε, τυχὸν μὲν ἴσως κἂν μεταπεισθείητε, ὃ μάλιστ’ ἐγὼ νομίζω συνενεγκεῖν ἂν ὑμῖν· εἰ δὲ μή, οἱ μὲν ἀγνοεῖν τὸ συμφέρον, οἱ δὲ—ὅ τι ἄν τις βούληται, τοῦτ’ ἐρεῖ.", "st": "62.28.2"}, {"sp": "SEC", "t": "Προοίμιον ΚΘʹ", "st": "62.29"}, {"sp": "N", "t": "πρῶτον μὲν οὐδέν ἐστιν καινόν, ὦ ἄνδρες Ἀθηναῖοι, τοῖς δόξασιν παρ’ ὑμῖν εἶναί τινας οἵτινες ἀντεροῦσιν, ἐπειδὰν πράττειν τι δέῃ. εἰ μὲν οὖν ἀποδόντων ὑμῶν λόγον αὐτοῖς, ὅτ’ ἐβουλεύεσθε, τοῦτ’ ἐποίουν, τούτων ἂν ἦν ἄξιον κατηγορεῖν, εἰ περὶ ὧν ἥττηντ’ ἐβιάζοντο πάλιν λέγειν· νῦν δὲ τούτους μὲν οὐδέν ἐστ’ ἄτοπον εἰπεῖν βουληθῆναι ταῦθ’ ἃ τότ’ οὐχ ὑπεμείνατ’ ἀκοῦσαι,", "st": "62.29.1"}, {"sp": "N", "t": "ὑμῖν δ’ ἄν τις εἰκότως ἐπιτιμήσειεν, ἄνδρες Ἀθηναῖοι, ὅτι ὁπόταν περί του βουλεύησθε, οὐκ ἐᾶτε λέγειν ἕκαστον ἃ γιγνώσκει, ἀλλ’ ἂν ἕτεροι τῷ λόγῳ προλάβωσιν ὑμᾶς, οὐδὲν ἂν τῶν ἑτέρων ἀκούσαιτε. ἐκ δὲ τούτου συμβαίνει πρᾶγμ’ ἀηδὲς ὑμῖν. οἷς γὰρ πρὶν ἁμαρτεῖν ὑμῖν ἐξῆν συμβουλεύουσιν πείθεσθαι, τούτους ὕστερον κατηγοροῦντας ἐπαινεῖτε.", "st": "62.29.2"}, {"sp": "N", "t": "ταὐτὸ δὴ τοῦτό μοι πάλιν δοκεῖτε πείσεσθαι, εἰ μὴ παρασχόντες ἴσους ἀκροατὰς πάντων ὑμᾶς αὐτοὺς ἐν τῷ παρόντι, καὶ τοῦτον τὸν πόνον ὑπομείναντες, ἑλόμενοι τὰ κράτιστα τοὺς ὁτιοῦν τούτοις ἐπιτιμῶντας φαύλους νομιεῖτε. ἐγὼ μὲν δὴ δίκαιον ὑπείληφα πρῶτον ἁπάντων αὐτὸς εἰπεῖν, τί μοι δοκεῖ περὶ ὧν σκοπεῖσθε, ἵνα, ἂν μὲν ὑμῖν ἀρέσκῃ, καὶ τὰ λοιπὰ διδάσκω, εἰ δὲ μή, μήθ’ ὑμῖν ἐνοχλῶ μήτ’ ἐμαυτὸν κόπτω.", "st": "62.29.3"}, {"sp": "SEC", "t": "Προοίμιον Λʹ", "st": "62.30"}, {"sp": "N", "t": "ἔδει μέν, ὦ ἄνδρες Ἀθηναῖοι, πρὸ τοῦ πολεμεῖν ἐσκέφθαι τίς ὑπάρξει παρασκευὴ τῷ γενησομένῳ πολέμῳ· εἰ δ’ ἄρα μὴ πρόδηλος ἦν, ὅτε πρῶτον ἐβουλεύεσθ’ ὑπὲρ αὐτοῦ φανεροῦ γενομένου, τότε καὶ περὶ τῆς παρασκευῆς ἐσκέφθαι. εἰ δὲ φήσετε πολλὰς ἐγκεχειρικέναι δυνάμεις, ἃς λελυμάνθαι τοὺς ἐπιστάντας, οὐκ ἀποδέξεται τοῦθ’ ὑμῶν οὐδείς· οὐ γάρ ἐστι τῶν αὐτῶν τούς ⟨τ’⟩ ἐπὶ τῶν πραγμάτων ἀπολύειν, καὶ λέγειν ὡς διὰ τούτους κακῶς ταῦτ’ ἔχει.", "st": "62.30.1"}, {"sp": "N", "t": "ἐπειδὴ δὲ τὰ μὲν παρεληλυθότ’ οὐκ ἂν ἄλλως ἔχοι, δεῖ δ’ ἐκ τῶν παρόντων ἐπαμῦναι τοῖς πράγμασιν, τοῦ μὲν κατηγορεῖν οὐδένα καιρὸν ὁρῶ, πειράσομαι δ’ ἃ κράτιστα νομίζω, συμβουλεῦσαι. πρῶτον μὲν οὖν ὑμᾶς ἐκεῖν’ ἐγνωκέναι δεῖ, ὅτι τὴν ἴσην ὑπερβολὴν τῆς σπουδῆς καὶ φιλονικίας ἐπὶ τοῖς πράγμασι πάντ’ ἄνδρα παρασχέσθαι δεῖ, ὅσηνπερ ἐκ τῶν ἄνωθεν χρόνων ἀμελείας· μόλις γὰρ οὕτως ἐλπὶς ἐκ πολλοῦ διώκοντας τὰ προειμέν’ ἑλεῖν δυνηθῆναι.", "st": "62.30.2"}, {"sp": "N", "t": "ἔπειτ’ οὐκ ἀθυμητέον τοῖς γεγενημένοις· ὃ γάρ ἐστιν τῶν παρεληλυθότων χείριστον, τοῦτο πρὸς τὰ μέλλοντα βέλτιστον ὑπάρχει. τί οὖν τοῦτ’ ἔστιν [ὦ ἄνδρες Ἀθηναῖοι]; ὅτι οὐδὲν ὑμῶν τῶν δεόντων ποιούντων κακῶς ἔχει τὰ πράγματα· ἐπεὶ εἴ γε πάνθ’ ἃ προσῆκε πραττόντων οὕτως εἶχεν, οὐδ’ ἂν ἐλπὶς ἦν αὐτὰ γενέσθαι βελτίω.", "st": "62.30.3"}, {"sp": "SEC", "t": "Προοίμιον ΛΑʹ", "st": "62.31"}, {"sp": "N", "t": "οὐδέν ἐστιν, ὦ ἄνδρες Ἀθηναῖοι, χαλεπώτερον ἢ τοῖς αὐτοῖς ἔθεσιν ἐπιτιμᾶν τε καὶ χρῆσθαι τοὺς δημηγοροῦντας. τὸ γὰρ στασιάζειν πρὸς αὑτοὺς καὶ κατηγορεῖν ἀλλήλων ἄνευ κρίσεως, οὐδείς ἐστιν οὕτως ἀγνώμων ὅστις οὐ φήσειεν ἂν βλάβην εἶναι τοῖς πράγμασιν. ἐγὼ δ’ οἴομαι τούτους μὲν ἂν εἶναι βελτίους, εἰ τὴν πρὸς αὑτοὺς φιλονικίαν ἐπὶ τοὺς τῆς πόλεως ἐχθροὺς τρέψαντες ἐδημηγόρουν· ὑμῖν δὲ παραινῶ μὴ συστασιάζειν μηδετέροις τούτων, μηδ’ ὅπως ἅτεροι κρατήσουσι σκοπεῖν, ἀλλ’ ὅπως ὑμεῖς ἅπαντες τῶν ἐχθρῶν περιέσεσθε.", "st": "62.31.1"}, {"sp": "N", "t": "εὔχομαι δὲ τοῖς θεοῖς τοὺς ἢ φιλονικίας ἢ ἐπηρείας ἤ τινος ἄλλης ἕνεκ’ αἰτίας ἄλλο τι, πλὴν ἅ ποθ’ ἡγοῦνται συμφέρειν, λέγοντας παύσασθαι· τὸ γὰρ καταρᾶσθαι συμβουλεύοντ’ ἴσως ἔστ’ ἄτοπον. αἰτιασαίμην μὲν οὖν ἔγωγ’ ἂν οὐδέν’, ὦ ἄνδρες Ἀθηναῖοι, τοῦ κακῶς τὰ πράγματ’ ἔχειν ἀλλ’ ἢ πάντας τούτους· οἴομαι δὲ δεῖν παρὰ μὲν τούτων ἐφ’ ἡσυχίας λόγον ὑμᾶς λαβεῖν, νῦν δ’ ὑπὲρ τῶν παρόντων, ὅπως ἔσται βελτίω, σκοπεῖν.", "st": "62.31.2"}, {"sp": "SEC", "t": "Προοίμιον ΛΒʹ", "st": "62.32"}, {"sp": "N", "t": "ἐβουλόμην ἄν, ὦ ἄνδρες Ἀθηναῖοι, τὴν ἴσην σπουδὴν ἐνίους τῶν λεγόντων ποιεῖσθαι ὅπως τὰ βέλτιστ’ ἐροῦσιν, ὅσηνπερ ὅπως εὖ δόξουσι λέγειν, ἵν’ οὗτοι μὲν ἀντὶ τοῦ δεινοὶ λέγειν ἐπιεικεῖς ἐνομίζοντ’ εἶναι, τὰ δ’ ὑμέτερα, ὥσπερ ἐστὶν προσῆκον, βέλτιον εἶχεν. νῦν δ’ ἔνιοί μοι δοκοῦσι παντάπασι τὴν ἀπὸ τοῦ λόγου δόξαν ἠγαπηκότες τῶν μετὰ ταῦτα συμβησομένων ὑμῖν μηδὲν φροντίζειν.", "st": "62.32.1"}, {"sp": "N", "t": "καὶ δῆτα θαυμάζω, πότερά ποθ’ οἱ τοιοῦτοι λόγοι τὸν λέγονθ’ ὁμοίως πεφύκασιν ἐξαπατᾶν ὥσπερ πρὸς οὓς ἂν λέγωνται, ἢ συνιέντες οὗτοι τἀναντία τοῖς δοκοῦσιν ἑαυτοῖς εἶναι βελτίστοις δημηγοροῦσιν. εἰ μὲν γὰρ ἀγνοοῦσιν ὅτι τὸν μέλλοντα πράξειν τὰ δέοντα οὐκ ἐπὶ τῶν λόγων θρασύν, ἀλλ’ ἐπὶ τῆς παρασκευῆς ἰσχυρὸν εἶναι δεῖ, οὐδ’ ἐπὶ τῷ τοὺς ἐχθροὺς μὴ δυνήσεσθαι θαρρεῖν, ἀλλ’ ἐπὶ τῷ κἂν δύνωνται κρατήσειν, τὰ τῶν λόγων ἀστεῖ’ ὡς ἔοικεν τοῦ τὰ μέγιστ’ αἰσθάνεσθαι κεκώλυκεν αὐτούς. εἰ δὲ ταῦτα μὲν μηδ’ ἂν φήσαιεν ἀγνοεῖν, πρόφασις δ’ ἄλλη τις ὕπεστι δι’ ἣν ταῦτα προαιροῦνται, πῶς οὐ χρὴ φαύλην ταύτην ὑπολαμβάνειν, ἥτις ποτ’ ἐστίν;", "st": "62.32.2"}, {"sp": "N", "t": "ἐγὼ δ’ οὐκ ἀποτρέψομαι λέγειν ἃ δοκεῖ μοι, καίπερ ⟨οὕτως⟩ ὁρῶν ἠγμένους ὑμᾶς· καὶ γὰρ εὔηθες, λόγῳ ψυχαγωγηθέντων ὑμῶν οὐκ ὀρθῶς, λόγον αὖ τὸν μέλλοντα βελτίω λέγειν καὶ μᾶλλον συμφέρονθ’ ὑμῖν καταδεῖσαι. ἀξιῶ δὲ καὶ ὑμᾶς ὑπομεῖναι, ἐνθυμηθέντας ὅτι οὐδὲ τὰ νῦν δοκοῦντ’ ἔδοξεν ἂν ὑμῖν, εἰ μὴ τοὺς λόγους ἠκούσατ’ ἐξ ὧν ἐπείσθητε.", "st": "62.32.3"}, {"sp": "N", "t": "ὥσπερ ἂν τοίνυν, εἰ νόμισμ’ ἐκρίνεθ’ ὁποῖόν τί ποτ’ ἐστίν, δοκιμάσαι δεῖν ἂν ᾠήθητε, οὕτω καὶ τὸν λόγον ἀξιῶ τὸν εἰρημένον ἐξ ὧν ἀντειπεῖν ἡμεῖς ἔχομεν σκεψαμένους, ἐὰν μὲν συμφέρονθ’ εὕρητε, ἀγαθῇ τύχῃ πείθεσθαι, ἂν δ’ ἄρ’ ἕκαστα λογιζομένοις ἀλλοιότερος φανῇ, πρὶν ἁμαρτεῖν μεταβουλευσαμένους, τοῖς ὀρθῶς ἔχουσιν χρήσασθαι.", "st": "62.32.4"}, {"sp": "SEC", "t": "Προοίμιον ΛΓʹ", "st": "62.33"}, {"sp": "N", "t": "μάλιστα μέν, ὦ ἄνδρες Ἀθηναῖοι, βουλοίμην ἂν ὑμᾶς ἃ μέλλω λέγειν πεισθῆναι· εἰ δ’ ἄρα τοῦτ’ ἄλλῃ πῃ συμβαίνοι, ἐμαυτῷ γ’ ἂν εἰρῆσθαι πρὸ παντὸς αὐτὰ δεξαίμην. ἔστι δ’ οὐ μόνον, ὡς δοκεῖ, τὸ πρὸς ὑμᾶς εἰπεῖν χαλεπὸν τὰ δέοντα, ἀλλὰ καὶ καθ’ αὑτὸν σκοπούμενον εὑρεῖν. γνοίη δ’ ἄν τις, εἰ μὴ τὸν λόγον ὑμᾶς, ἀλλὰ τὰ πράγματ’ ἐφ’ ὧν ἐστε σκέψεσθαι νομίσαι, καὶ πλείω σπουδὴν τοῦ δοκεῖν ἐπιεικὴς εἶναι ἢ τοῦ δεινὸς εἰπεῖν φανῆναι ποιοῖτο.", "st": "62.33.1"}, {"sp": "N", "t": "ἐγὼ γοῦν ʽοὕτω τί μοι ἀγαθὸν γένοιτὀ ἐπειδὴ περὶ τῶν παρόντων ἐπῄει μοι σκοπεῖν, λόγοις μὲν καὶ μάλ’ ἀφθόνοις, οὓς οὐκ ἂν ἀηδῶς ἠκούεθ’ ὑμεῖς, ἐνετύγχανον. καὶ γὰρ ὡς δικαιότατοι τῶν Ἑλλήνων ἐστέ, πόλλ’ ⟨ὄντ’⟩ εἰπεῖν καὶ ἑώρων καὶ ὁρῶ, καὶ ὡς ἀρίστων προγόνων, καὶ πολλὰ τοιαῦτα. ἀλλὰ ταῦτα μὲν τὸν χρόνον ἡσθῆναι ποιήσανθ’ ὅσον ἂν ῥηθῇ, μετὰ ταῦτ’ οἴχεται·", "st": "62.33.2"}, {"sp": "N", "t": "δεῖ δὲ πράξεώς τινος τὸν λέγοντα φανῆναι σύμβουλον, δι’ ἣν καὶ μετὰ ταῦτ’ ἀγαθοῦ τινος ὑμῖν ἔσται παρουσία. τοῦτο δ’ ἤδη καὶ σπάνιον καὶ χαλεπὸν πεπειραμένος οἶδ’ ὂν εὑρεῖν. οὐδὲ γὰρ αὔταρκες τὸ ἰδεῖν ἐστι τὰ τοιαῦτα, ἂν μὴ καὶ πεῖσαί τις τοὺς συναρουμένους ὑμᾶς δυνηθῇ. οὐ μὴν ἀλλ’ ἐμὸν μὲν ἔργον εἰπεῖν ἴσως ἃ πέπεικ’ ἐμαυτὸν συμφέρειν, ὑμέτερον δ’ ἀκούσαντας κρῖναι, κἂν ἀρέσκῃ, χρῆσθαι.", "st": "62.33.3"}, {"sp": "SEC", "t": "Προοίμιον ΛΔʹ", "st": "62.34"}, {"sp": "N", "t": "οὐκ ἄδηλον ἦν, ὦ ἄνδρες Ἀθηναῖοι, πρῴην, ὅτε τῶν ἀντιλέγειν βουλομένων οἷς ὁ δεῖν’ ἔλεγεν οὐκ ᾤεσθ’ ἀκούειν χρῆναι, ὅτι συμβήσεται τοῦθ’ ὃ νυνὶ γίγνεται, ὅτι οἱ τότε κωλυθέντες ἐροῖεν εἰς ἑτέραν ἐκκλησίαν. ἂν τοίνυν ταὔθ’ ἅπερ πρότερον ποιήσητε, καὶ τῶν τοῖς τότε δόξασι συνειπεῖν βουλομένων μὴ ’θελήσητ’ ἀκοῦσαι, πάλιν ταῦτ’ εἰς τὴν ἑτέραν ἐκκλησίαν οὗτοι λαβόντες τούτων κατηγορήσουσιν.", "st": "62.34.1"}, {"sp": "N", "t": "οὐδαμῶς, ὦ ἄνδρες Ἀθηναῖοι, οὔτε τὰ πράγματα χείρω γένοιτ’ ἄν, οὔθ’ ὑμεῖς ἀτοπώτεροι φανείητε, ἢ εἰ μήτε τῶν δοξάντων ὑμῖν πέρας μηδὲν ἔχειν δοκοίη, μήτ’ ἀφέντες ἃ μὴ συμφέρει, τῶν πρὸ ὁδοῦ τι περαίνοιτε, εἴητε δ’ ὥσπερ τὰ θέατρα τῶν προκαταλαμβανόντων. μηδαμῶς, ὦ ἄνδρες Ἀθηναῖοι, ἀλλὰ πονήσαντες τὸν πόνον τοῦτον καὶ παρασχόντες ἴσους ἀκροατὰς ἀμφοτέροις ὑμᾶς αὐτοὺς πρῶτον μὲν ἕλεσθ’ ὅ τι καὶ ποιήσετε, ἔπειθ’ ὑπολαμβάνετε, ἐάν τις ἐναντιῶται τοῖς ἅπαξ οὕτω δοκιμασθεῖσι, πονηρὸν καὶ κακόνουν ὑμῖν.", "st": "62.34.2"}, {"sp": "N", "t": "τὸ μὲν γὰρ λόγου μὴ τυχόντα πεπεῖσθαι βέλτιον τῶν ὑμῖν δοκούντων αὐτὸν ἐντεθυμῆσθαι συγγνώμη· τὸ δ’ ἀκουσάντων ὑμῶν καὶ διακρινάντων ἔτ’ ἀναισχυντεῖν, καὶ μὴ συγχωρεῖν ἐνδόντα τῇ τῶν πλειόνων γνώμῃ, ἄλλην τιν’ ⟨ἂν⟩ ὑποψίαν οὐχὶ δικαίαν ἔχειν φανείη. ἐγὼ μὲν δὴ σιωπᾶν ⟨ἂν⟩ ᾤμην δεῖν ἐν τῷ παρόντι, εἰ μένοντας ὑμᾶς ἑώρων ἐφ’ ὧν ἔδοξεν· εἰμὶ γὰρ τῶν ἐκεῖνα πεπεισμένων συμφέρειν ὑμῖν· ἐπειδὴ δ’ ὑπὸ τῶν παρὰ τούτων λόγων μεταβεβλῆσθαί μοί τινες δοκοῦσιν, ὡς οὔτ’ ἀληθῆ λέγουσιν οὔθ’ ὑμῖν συμφέροντα, ἴσως μὲν εἰδότας, οὐ μὴν ἀλλ’ εἰ καὶ τυγχάνετ’ ἀγνοοῦντες, διδάξω.", "st": "62.34.3"}, {"sp": "SEC", "t": "Προοίμιον ΛΕʹ", "st": "62.35"}, {"sp": "N", "t": "ἔδει μέν, ὦ ἄνδρες Ἀθηναῖοι, καὶ δίκαιον ἦν τότε πείθειν ὑμᾶς ὅ τι ἄριστον ἕκαστος ἡγεῖτο, ὅτ’ ἐβουλεύεσθε τὸ πρῶτον περὶ τούτων, ἵνα μὴ συνέβαινεν ἃ δὴ δύο πάντων ἐστὶν ἀλυσιτελέστατα τῇ πόλει, μήτε πέρας μηδὲν εἶχεν τῶν ὑμῖν δοξάντων, παρανοίας θ’ ὑμεῖς κατεγιγνώσκεθ’ ὑμῶν αὐτῶν μεταβουλευόμενοι. ἐπειδὴ δὲ σιωπήσαντες τότε νῦν ἐπιτιμῶσί τινες, βούλομαι μικρὰ πρὸς αὐτοὺς εἰπεῖν.", "st": "62.35.1"}, {"sp": "N", "t": "ἐγὼ γὰρ θαυμάζω τὸν τρόπον τῆς πολιτείας τῆς τούτων, μᾶλλον δ’ ἡγοῦμαι φαῦλον. εἰ γὰρ ἐξὸν παραινεῖν ὅταν σκοπῆτε, βεβουλευμένων κατηγορεῖν αἱροῦνται, συκοφαντῶν ἔργον, οὐχ, ὡς φασίν, εὔνων ποιοῦσιν ἀνθρώπων. ἡδέως δ’ ἂν ἐροίμην αὐτούς ʽκαὶ μηδεμιᾶς λοιδορίας ὃ μέλλω λέγειν ἀρχὴ γενέσθὠ τί δὴ τἄλλ’ ἐπαινοῦντες Λακεδαιμονίους, ὃ μάλιστ’ ἄξιόν ἐστιν τῶν παρ’ ἐκείνοις ἄγασθαι, τοῦτ’ οὐ μιμοῦνται, μᾶλλον δ’ αὐτὸ τοὐναντίον ποιοῦσιν;", "st": "62.35.2"}, {"sp": "N", "t": "φασὶ γάρ, ὦ ἄνδρες Ἀθηναῖοι, παρ’ ἐκείνοις μέχρι μὲν τοῦ δόξαι γνώμην, ἣν ἂν ἕκαστος ἔχῃ, λέγειν, ἐπειδὰν δ’ ἐπικυρωθῇ, ταῦθ’ ἅπαντας ἐπαινεῖν καὶ συμπράττειν, καὶ τοὺς ἀντειπόντας. τοιγάρτοι πολλῶν μὲν ὄντες οὐ πολλοὶ περιγίγνονται, λαμβάνουσι δέ, ὅσ’ ἂν μὴ τῷ πολέμῳ δύνωνται, τοῖς καιροῖς, οὐδεὶς δ’ αὐτοὺς ἐκφεύγει χρόνος οὐδὲ τρόπος τοῦ τὰ συμφέρονθ’ ἑαυτοῖς περαίνειν, οὐ μὰ Δί’ οὐχ ὥσπερ ἡμεῖς καὶ διὰ τούτους καὶ τοὺς ὁμοίους τούτοις, ἀλλήλων περιγιγνόμενοι καὶ οὐχὶ τῶν ἐχθρῶν, πάντ’ ἀνηλώκαμεν τὸν χρόνον,", "st": "62.35.3"}, {"sp": "N", "t": "κἂν μὲν εἰρήνην τις ἐκ πολέμου ποιήσῃ, τοῦτον μισοῦντες, ἂν δ’ ἐξ εἰρήνης πόλεμόν τις λέγῃ, τούτῳ μαχόμενοι, ἂν δ’ ἔχειν ἡσυχίαν τις παραινῇ καὶ τὰ ἡμέτερ’ αὐτῶν πράττειν, οὐδὲ τοῦτον ὀρθῶς λέγειν φάσκοντες, ὅλως δ’ αἰτιῶν καὶ κενῶν ἐλπίδων ὄντες πλήρεις. “τί οὖν”, ἄν τις εἴποι, “σὺ παραινεῖς, ἐπειδὴ ταῦτ’ ἐπιτιμᾷς”; ἐγὼ νὴ Δί’ ἐρῶ.", "st": "62.35.4"}, {"sp": "SEC", "t": "Προοίμιον ΛϚʹ", "st": "62.36"}, {"sp": "N", "t": "πρῶτον μέν, ὦ ἄνδρες Ἀθηναῖοι, οὐ πάνυ μοι δοκεῖ τις ἂν εἰκότως περὶ ὑμῶν δεῖσαι, μὴ παρὰ τὸ τῶν συμβουλευόντων οὐκ ἐθέλειν ἀκούειν χεῖρον βουλεύσησθε. πρῶτον μὲν γὰρ ἡ τύχη, καλῶς ποιοῦσα, πολλὰ τῶν πραγμάτων ὑμῖν αὐτόματα, ὡς ἂν εὔξαισθε, παρίστησιν, ἐπεὶ τῇ γε τῶν προεστηκότων προνοίᾳ βραχέ’ αὐτῶν εἶχεν ἂν καλῶς. ἔπειθ’ ὑμεῖς οὐ μόνον τοὺς λόγους οὓς ἂν ἕκαστος εἴποι πρόϊστε, ἀλλὰ καὶ ὧν ἕνεκ’ αὐτῶν ἕκαστος δημηγορεῖ, εἰ δὲ μὴ φιλαπέχθημον ἦν, εἶπον ἂν καὶ πόσου.", "st": "62.36.1"}, {"sp": "N", "t": "τὸν δὴ τοῦ φενακίζεσθαι χρόνον ὡς εἰς μικρότατον συνάγοντες σωφρονεῖν ἔμοιγε δοκεῖτε. εἰ μὲν δή τι τῶν αὐτῶν ἔμελλον τοῖς ἄλλοις ἐρεῖν, οὐκ ἂν ᾤμην δεῖν λέγων ἐνοχλεῖν. νῦν δὲ συμφέροντα μὲν ὑμῖν ἀκοῦσαι, παντάπασι δ’ ἀφεστηκότα τῶν ὑπὸ τῶν πολλῶν προσδοκωμένων οἴομαι λόγον ἐρεῖν. βραχὺς δ’ ἔσται. σκέψασθε δ’ ἀκούσαντες, κἂν ὑμῖν ἀρέσκῃ, χρήσασθε.", "st": "62.36.2"}, {"sp": "SEC", "t": "Προοίμιον ΛΖʹ", "st": "62.37"}, {"sp": "N", "t": "καὶ βραχεῖαν, ὦ ἄνδρες Ἀθηναῖοι, καὶ δικαίαν ποιήσομαι τὴν ἀρχὴν τοῦ λόγου· καὶ οὕτω δὲ τὰ πάντ’ ἐρῶ. ἡγοῦμαι γὰρ ἐξαπατᾶν μὲν εἶναι βουλομένου σκοπεῖν ὅντιν’ ὑμᾶς τρόπον τοὺς ἀκούοντας τὰ τοῦ πράγματος δυσχερῆ τῷ λόγῳ συγκρύψεται, ἁπλῶς δὲ πεπεικότος αὑτὸν ὑμῖν προσφέρεσθαι τοῦτο πρῶτον εἶναι, εἰπεῖν πότερ’ ἐγνωκὼς παρελήλυθεν,", "st": "62.37.1"}, {"sp": "N", "t": "ἵν’ ἐὰν μὲν ἀκούσαντες τοῦτο τοὺς μετὰ ταῦτα λόγους βούλησθ’ ἀκούειν, καὶ διδάσκῃ καὶ φράζῃ τὰ βέλτισθ’ αὑτῷ δοκοῦντα, ἂν δ’ ἀποδοκιμάσητε, ἀπηλλαγμένος ᾖ καὶ μήθ’ ὑμῖν ἐνοχλῇ μήθ’ αὑτὸν κόπτῃ. ἐγὼ δὴ τοῦτο πρῶτον ἐρῶ. ἐμοὶ δοκεῖ Μυτιληναίων ὁ δῆμος ἠδικῆσθαι, καὶ δίκην ὑμῖν ὑπὲρ αὐτοῦ προσήκειν λαβεῖν. καὶ ὅπως λήψεσθ’ ἔχω λέγειν, ἐπειδὰν ὡς ἠδίκηνται καὶ ὑμῖν προσήκει βοηθεῖν ἐπιδείξω.", "st": "62.37.2"}, {"sp": "SEC", "t": "Προοίμιον ΛΗʹ", "st": "62.38"}, {"sp": "N", "t": "πρῶτον μὲν οὐ πάνυ θαυμαστόν ἐστιν, ὦ ἄνδρες Ἀθηναῖοι, τὸ μὴ ῥᾳδίους τοῖς συμβουλεύειν βουλομένοις εἶναι τοὺς λόγους· ὅταν γὰρ τὰ πράγματ’ ἔχῃ φαύλως περὶ ὧν δεῖ σκοπεῖν, δυσχερεῖς ἀνάγκη περὶ αὐτῶν εἶναι καὶ τὰς συμβουλίας. εἰ μὲν οὖν ἐκ τοῦ μὴ ’θέλειν ἀκούειν ἐλπὶς ταῦτα γενέσθαι βελτίω, τοῦτο χρὴ πράττειν· εἰ δὲ χείρω μὲν ἅπαντα, βέλτιον δ’ οὐδὲν ἐκ τούτου γενήσεται, τί δεῖ, πρὸς τὸ φαυλότατον ἐλθεῖν ἐάσαντας, ἐκ πλείονος ἢ νῦν καὶ χαλεπωτέρως σῴζειν πειρᾶσθαι, ἐξὸν ἐκ τῶν παρόντων ἔτι καὶ νῦν ἐπανορθώσασθαι καὶ προαγαγεῖν ἐπὶ τὸ βέλτιον;", "st": "62.38.1"}, {"sp": "N", "t": "τὸ μὲν οὖν ὀργίλως ὑμᾶς ἔχειν εἰκός ἐστιν ταῦτα πάσχοντας· τὸ δὲ μὴ τοῖς αἰτίοις, ἀλλὰ πᾶσιν ἐφεξῆς ὀργίζεσθαι, τοῦτ’ οὐκέτ’ εἰκὸς οὐδ’ ὀρθῶς ἔχον ἐστίν. οἱ γὰρ μηδενὸς μὲν αἴτιοι τῶν παρεληλυθότων, τὰ δὲ λοιπὰ πῶς ἔσται βελτίω λέγειν ἔχοντες, χάριν, οὐκ ἀπέχθειαν κομίσαιντ’ ἂν δικαίως παρ’ ὑμῶς· οὕς, ἐὰν ἀκαίρως δυσκολαίνητε, ὀκνεῖν ἀνίστασθαι ποιήσετε.", "st": "62.38.2"}, {"sp": "N", "t": "καίτοι ἔγωγ’ οὐκ ἀγνοῶ, ὅτι πολλάκις οὐ τοῖς αἰτίοις, ἀλλὰ τοῖς ἐμποδὼν οὖσι τοῖς ὀργιζομένοις ἀηδές τι παθεῖν συνέβη· ὅμως δ’ ἀνέστην συμβουλεύσων· πιστεύω γὰρ ἔγωγ’, ὦ ἄνδρες Ἀθηναῖοι, φλαύρου μὲν μηδενὸς αἴτιος ὢν εὑρεθήσεσθαι, βελτίω δ’ ἑτέρων ὑμῖν ἔχειν συμβουλεῦσαι.", "st": "62.38.3"}, {"sp": "SEC", "t": "Προοίμιον ΛΘʹ", "st": "62.39"}, {"sp": "N", "t": "τὰ μὲν γεγενημέν’, ὦ ἄνδρες Ἀθηναῖοι, τοιαῦθ’ οἷα πάντες ἀκηκόατε· δεῖ δ’ ὑμᾶς μηδὲν ἐκπεπληγμένως διακεῖσθαι, λογιζομένους ὅτι πρὸς μὲν τὰ παρόντ’ ἀθύμως ἔχειν οὔτε τοῖς πράγμασι συμφέρον οὔθ’ ὑμῶν ἄξιόν ἐστιν, τὸ δὲ ταῦτ’ ἐπανορθοῦν αὑτοῖς ἡγεῖσθαι προσῆκον [καὶ] τῆς ὑμετέρας δόξης ἄξιον ἂν φανείη. χρὴ δὲ τοὺς ὄντας οἷοι φήσαιτ’ ἂν ὑμεῖς εἶναι, ἐν τοῖς δεινοῖς ἑτέρων διαφέροντας φαίνεσθαι.", "st": "62.39.1"}, {"sp": "N", "t": "ἐγὼ δ’ οὐδαμῶς μὲν ἂν ἐβουλόμην ταῦτα συμβῆναι τῇ πόλει, οὐδ’ ἀτυχεῖν ὑμᾶς οὐδέν· εἰ δ’ ἄρ’ ἔδει γενέσθαι καί τι δαιμόνιον τοῦτ’ ἀπέκειτο, ὥσπερ πέπρακται τὰ γεγενημένα, λυσιτελεῖν οἴομαι. τὰ μὲν γὰρ τῆς τύχης ὀξείας ἔχει τὰς μεταβολὰς καὶ κοινὰς ἀμφοτέροις τὰς παρουσίας· ἃ δ’ ἂν δι’ ἀνδρῶν κακίαν πραχθῇ, βεβαίους ποιεῖ τὰς ἥττας.", "st": "62.39.2"}, {"sp": "N", "t": "οἴομαι μὲν οὖν οὐδὲ τοὺς κεκρατηκότας ἀγνοεῖν ὅτι βουληθέντων ὑμῶν καὶ παροξυνθέντων τῷ γεγενημένῳ, οὐ πάνυ πω δῆλον πότερον εὐτύχημ’ ἢ καὶ τοὐναντίον αὐτοῖς ἐστιν τὸ πεπραγμένον· εἰ δ’ ἄρ’ ἐπῆρκε τὸ πρᾶγμ’ αὐτοὺς θρασύνεσθαι, κἂν τοῦτο πρὸς ὑμῶν ἤδη γίγνοιτο. ὅσῳ γὰρ ἂν μᾶλλον καταφρονήσωσι, τοσούτῳ θᾶττον ἁμαρτήσονται.", "st": "62.39.3"}, {"sp": "SEC", "t": "Προοίμιον Μʹ", "st": "62.40"}, {"sp": "N", "t": "οὔ μοι δοκεῖτ’, ὦ ἄνδρες Ἀθηναῖοι, περὶ ἧς οἴεσθε πόλεως νυνὶ μόνον βουλεύεσθαι, ἀλλ’ ὑπὲρ πασῶν τῶν συμμαχίδων. ὅπως γὰρ ἂν περὶ ταύτης γνῶτε, πρὸς ταῦτ’ εἰκὸς ἀποβλέποντας τοὺς ἄλλους καὶ αὑτοὺς τῶν αὐτῶν τεύξεσθαι νομίζειν. ὥστε δεῖ καὶ τοῦ βελτίστου καὶ τῆς ὑμετέρας αὐτῶν ἕνεκα δόξης σπουδάσαι, ὅπως ἅμα καὶ συμφέροντα καὶ δίκαια φανήσεσθε βουλευόμενοι.", "st": "62.40.1"}, {"sp": "N", "t": "ἡ μὲν οὖν ἀρχὴ τῶν τοιούτων πραγμάτων ἁπάντων ἐστὶν τῶν στρατηγῶν· ὧν οἱ πλεῖστοι τῶν παρ’ ὑμῶν ἐκπλεόντων οὐ τοὺς ὑμετέρους φίλους, οὓς διὰ παντὸς τοῦ χρόνου τῶν αὐτῶν κινδύνων μετεσχηκότας παρειλήφασιν, τούτους θεραπεύειν οἴονται δεῖν, ἀλλ’ ἰδίους φίλους ἕκαστος ἑαυτῷ κατασκευάσας ὑμᾶς ἀξιοῖ τοὺς αὑτῶν κόλακας καὶ ὑμετέρους ἡγεῖσθαι φίλους· οὗ πᾶν ἐστι τοὐναντίον.", "st": "62.40.2"}, {"sp": "N", "t": "οὔτε γὰρ ἐχθροτέρους οὔτ’ ἀναγκαίους μᾶλλον ἐχθροὺς ἂν τούτων εὕροιτε. ὅσῳ γὰρ πλείω παρακρουόμενοι πλεονεκτοῦσιν, τοσούτῳ πλειόνων ὀφείλειν ἡγοῦνται δίκην δοῦναι· οὐδεὶς δ’ ἂν γένοιτ’ εὔνους τούτοις ὑφ’ ὧν ἄν τι κακὸν πείσεσθαι προσδοκᾷ. τοῦ μὲν οὖν κατηγορεῖν ἴσως οὐχ ὁ παρὼν καιρός· ἃ δ’ ἡγοῦμαι συμφέρειν ὑμῖν, ταῦτα συμβουλεύσω.", "st": "62.40.3"}, {"sp": "SEC", "t": "Προοίμιον ΜΑʹ", "st": "62.41"}, {"sp": "N", "t": "οὐδέν’, ὦ ἄνδρες Ἀθηναῖοι, τῶν πάντων ὑμῶν οὕτως οἴομαι κακόνουν εἶναι τῇ πόλει ὥστε μὴ χαλεπῶς φέρειν μηδὲ λυπεῖσθαι τοῖς γεγενημένοις. εἰ μὲν τοίνυν ἀγανακτοῦντας ἦν ἄπρακτόν τι ποιῆσαι τούτων, τοῦτ’ ἂν ἔγωγε παρῄνουν ὑμῖν ἅπασιν· ἐπειδὴ δὲ ταῦτα μὲν οὐκ ἂν ἄλλως ἔχοι, δεῖ δ’ ὑπὲρ τῶν λοιπῶν προνοηθῆναι ὅπως μὴ ταὐτὰ πείσεσθε, ὥσπερ, ὦ ἄνδρες Ἀθηναῖοι, νῦν γεγενημένων ἀγανακτεῖτε, οὕτω χρὴ σπουδάσαι ὑπὲρ τοῦ μὴ πάλιν ταὐτὰ συμβῆναι, καὶ νομίζειν μηδέν’ ἔχειν λόγον εἰπεῖν τῶν συμβουλευόντων τοιοῦτον, ὃς δυνήσεται σῷσαι τὰ παρόντα μηδενὸς ὑμῶν μηδὲν συναραμένου· οὐ γὰρ ἂν λόγος, ἀλλὰ θεός τις ὁ τοιοῦτος εἴη.", "st": "62.41.1"}, {"sp": "N", "t": "ἡ μὲν οὖν ἀρχὴ τοῦ ταῦθ’ οὕτως ἔχειν ἐκεῖθεν ἤρτηται, ἐκ τοῦ τῆς παραχρῆμα πρὸς ὑμᾶς ἕνεκα χάριτος ἐνίους τῶν λεγόντων ἐνταυθοῖ δημηγορεῖν, ὡς οὔτ’ εἰσφέρειν οὔτε στρατεύεσθαι δεῖ, πάντα δ’ αὐτόματ’ ἔσται. ἔδει μὲν οὖν ταῦθ’ ὑπ’ ἄλλου τινὸς ἐξελέγχεσθαι μετὰ τοῦ λυσιτελοῦντος [ἐλέγχου] τῇ πόλει· δοκεῖ δέ μοι τρόπον τινὰ καὶ νῦν ἀμείνων ἡ τύχη περὶ ὑμᾶς τῶν ἐφεστηκότων εἶναι.", "st": "62.41.2"}, {"sp": "N", "t": "τὸ μὲν γὰρ ἕκαστ’ ἀπόλλυσθαι τῆς τῶν ἐπιμελουμένων κακίας σημεῖον προσήκει ποιεῖσθαι· τὸ δὲ μὴ πάλαι πάντ’ ἀπολωλέναι τῆς ὑμετέρας τύχης εὐεργέτημ’ ἔγωγε κρίνω. ἐν ᾧ τοίνυν ἡ τύχη διαλείπει καὶ τοὺς ἐχθροὺς ἀνέχει, τῶν λοιπῶν ἐπιμελήθητε. εἰ δὲ μή, σκοπεῖθ’ ὅπως μὴ ἅμα τούς τ’ ἐφεστῶτας ἑκάστοις ὑμεῖς κρινεῖτε, καὶ τὰ πράγμαθ’ ὑμῶν, ὦ ἄνδρες Ἀθηναῖοι, κλινεῖ. οὐ γὰρ ἔσθ’ ὅπως ταῦτ’ ἄνευ μεγάλου τινὸς ⟨κακοῦ⟩ στήσεται, μηδενὸς ἀντιλαμβανομένου.", "st": "62.41.3"}, {"sp": "SEC", "t": "Προοίμιον ΜΒʹ", "st": "62.42"}, {"sp": "N", "t": "οὐδέν ἐστιν, ὦ ἄνδρες Ἀθηναῖοι, τοῦτ’ ἄλογον, τοὺς ἀεὶ καὶ συνεχῶς ὑπὲρ τῶν ὀλιγαρχιῶν πολιτευομένους καὶ νῦν ταῦτα ποιοῦντας ἐξελέγχεσθαι. ἀλλ’ ἐκεῖνο μᾶλλον ἄν τις εἰκότως θαυμάσαι, τὸ τοὺς εἰδότας ὑμᾶς ταῦτα πολλάκις ἥδιον τούτων ἀκούειν ἢ τῶν ὑπὲρ ὑμῶν λεγόντων. ἴσως μὲν οὖν ὥσπερ οὐδ’ ἰδίᾳ ῥᾴδιόν ἐστιν ἅπαντ’ ὀρθῶς πράττειν, οὕτως οὐδὲ κοινῇ·", "st": "62.42.1"}, {"sp": "N", "t": "ἀλλ’ οὐ δὴ τὰ μέγιστά γε χρὴ παρορᾶν. τὰ μὲν οὖν ἄλλα πάντ’ ἐστὶν ἐλάττω· ὅταν δ’ ὑπὲρ πολιτείας καὶ σφαγῶν καὶ δήμου καταλύσεως εὐχερῶς ἀκούητε, πῶς οὐκ ἔξω χρὴ τοῦ φρονεῖν ὑμᾶς [αὐτοὺς] ἡγεῖσθαι; οἱ μὲν γὰρ ἄλλοι πάντες ἄνθρωποι τοῖς ἑτέρων παραδείγμασι χρώμενοι μᾶλλον εὐλαβεῖς αὐτοὶ γίγνονται· ὑμεῖς δ’ οὐδὲ τὰ τοῖς ἄλλοις συμβαίνοντ’ ἀκούοντες φοβηθῆναι δύνασθε, ἀλλ’ ἃ τοὺς ἰδίᾳ περιμένοντας ἀβελτέρους νομίζετε, ταῦτ’ αὐτοὶ δημοσίᾳ μοι δοκεῖτ’ ἀναμένειν παθόντες αἰσθέσθαι.", "st": "62.42.2"}, {"sp": "SEC", "t": "Προοίμιον ΜΓʹ", "st": "62.43"}, {"sp": "N", "t": "οὐδεὶς πώποτ’ ἴσως ὑμῶν ἐζήτησεν, ὦ ἄνδρες Ἀθηναῖοι, τί δήποθ’ οἱ κακῶς πράττοντες ἄμεινον περὶ τῶν πραγμάτων τῶν εὖ πραττόντων βουλεύονται. ἔστι δ’ οὐχ ἑτέρωθέν ποθεν τοῦτο γιγνόμενον, ἀλλ’ ὅτι συμβαίνει τοῖς μὲν μήτε φοβεῖσθαι μηδὲν μήθ’ ἅν τις λέγοι δεινὰ προσήκονθ’ αὑτοῖς ἡγεῖσθαι, τοὺς δὲ πλησίον ὄντας τῶν ἁμαρτημάτων, ὅταν εἰς τὸ κακῶς πράττειν ἀφίκωνται, σώφρονας πρὸς τὰ λοιπὰ καὶ μετρίους ὑπάρχειν.", "st": "62.43.1"}, {"sp": "N", "t": "σπουδαίων τοίνυν ἐστὶν ἀνθρώπων, ὅταν βελτίστῃ τῇ παρούσῃ τύχῃ χρῶνται, τότε πλείω τὴν σπουδὴν πρὸς τὸ σωφρονεῖν ἔχειν· οὐδὲν γὰρ οὔτε φυλαττομένοις οὕτω δεινὸν ὥστ’ ἀφύλακτον εἶναι, οὔτ’ ὀλιγωροῦσιν ἀπροσδόκητον παθεῖν. λέγω δὲ ταῦτ’ οὐχ ἵνα τὴν ἄλλως ὑμᾶς δεδίττωμαι, ἀλλ’ ἵνα μὴ διὰ τὴν παροῦσαν εὐπραξίαν, ἃ γένοιτ’ ἄν, εἰ μὴ προνοήσεσθε τῶν πραγμάτων, δείν’ ἀκούοντες καταφρονῆτε, ἀλλ’ ἄνευ τοῦ παθεῖν, ὥσπερ ἐστὶν προσῆκον φάσκοντάς γε μηδένων ἀπολείπεσθαι τῷ σωφρονεῖν, φυλάξησθε.", "st": "62.43.2"}, {"sp": "SEC", "t": "Προοίμιον ΜΔʹ", "st": "62.44"}, {"sp": "N", "t": "οὐχὶ τὸν αὐτὸν εἶναι καιρὸν ὑπείληφ’, ὦ ἄνδρες Ἀθηναῖοι, τοῦ τε χαρίζεσθαι καὶ τοῦ τὰ δοκοῦντά μοι βέλτιστα παραινεῖν. πολλάκις γὰρ ὁρῶ τὸ χαρίζεσθαί τι παρὰ γνώμην πλείον’ ἀπέχθειαν ἐνεγκὸν τοῦ τὸ πρῶτον ἐναντιωθῆναι. εἰ μὲν οὖν ἅπαντες ἐγιγνώσκετε ταὐτά, οὔτ’ ἄν, εἴ μοι τὰ δέοντ’ ἐδοκεῖτε προαιρεῖσθαι, παρῆλθον, περίεργον ἡγούμενος τοῖς ἀφ’ αὑτῶν ἃ χρὴ ποιοῦσι λέγειν, οὔτ’ ἂν εἰ τοὐναντίον· μᾶλλον γὰρ ἂν ἡγησάμην ἕν’ ὄντ’ ἐμαυτὸν ἀγνοεῖν τὰ κράτιστ’ ἢ πάντας ὑμᾶς.", "st": "62.44.1"}, {"sp": "N", "t": "ἐπειδὴ δ’ ὁρῶ τινὰς ὑμῶν ταὐτὰ μὲν γιγνώσκοντας ἐμοί, τἀναντία δ’ ἄλλοις, πειράσομαι μετὰ τούτων τοὺς ἑτέρους πεῖσαι. εἰ μὲν οὖν οἰήσεσθε δεῖν μὴ ’θέλειν ἀκούειν, οὐκ ὀρθῶς ποιήσετε· ἂν δ’ ἀκούσητε σιωπῇ καὶ τοῦθ’ ὑπομείνητε, δυοῖν ἀγαθοῖν θάτερον ὑμῖν ὑπάρξει· ἢ γὰρ πεισθήσεσθε, ἄν τι δοκῶμεν λέγειν συμφέρον, ἢ βεβαιότερον περὶ ὧν ἐγνώκατ’ ἔσεσθε πεπεισμένοι. ἂν γάρ, οἷς τι διαμαρτάνειν οἰόμεθ’ ἡμεῖς ὑμᾶς, ταῦτα μηδενὸς ἄξια φανῇ, μετ’ ἐλέγχου τὰ δεδογμένα νῦν ὑμεῖς ἔσεσθ’ ᾑρημένοι.", "st": "62.44.2"}, {"sp": "SEC", "t": "Προοίμιον ΜΕʹ", "st": "62.45"}, {"sp": "N", "t": "βουλοίμην ἄν, ὦ ἄνδρες Ἀθηναῖοι, περὶ ὧν ηὐδοκίμηκε λέγων παρ’ ὑμῖν ὁ δεῖνα, ἐπὶ τῶν ἔργων πραττομένων ἴσον αὐτῷ τὸν ἔπαινον γενέσθαι· οὔτε γὰρ τούτῳ κακόνους εἰμὶ μὰ τοὺς θεοὺς ὑμῖν τ’ ἀγαθὸν ἄν τι γίγνεσθαι βουλοίμην. ἀλλ’ ὁρᾶτ’, ὦ ἄνδρες Ἀθηναῖοι, μὴ κεχωρισμένον ᾖ λόγον εἰπεῖν εὖ καὶ προελέσθαι πράγματα συμφέροντα, καὶ τὸ μὲν ῥήτορος ἔργον ᾖ, τὸ δὲ νοῦν ἔχοντος ἀνθρώπου.", "st": "62.45.1"}, {"sp": "N", "t": "ὑμεῖς τοίνυν οἱ πολλοί, καὶ μάλισθ’ οἱ πρεσβύτατοι, λέγειν μὲν οὐκ ὀφείλεθ’ ὁμοίως δύνασθαι τοῖς δεινοτάτοις· τῶν γὰρ εἰθισμένων τοῦτο τὸ πρᾶγμα· νοῦν δ’ ἔχειν ὀφείλεθ’ ὁμοίως καὶ μᾶλλον τούτων· αἱ γὰρ ἐμπειρίαι καὶ τὸ πόλλ’ ἑορακέναι τοῦτ’ ἐμποιοῦσι. μὴ τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, φανῆτ’ ἀγνοοῦντες ἐν τῷ παρόντι νῦν ὅτι αἱ διὰ τῶν λόγων ἀνδρεῖαι καὶ θρασύτητες, ἐὰν μὴ μεθ’ ὑπαρχούσης ὦσι παρασκευῆς καὶ ῥώμης, ἀκοῦσαι μέν εἰσιν ἡδεῖαι, πράττειν δ’ ἐπικίνδυνοι.", "st": "62.45.2"}, {"sp": "N", "t": "αὐτίκα γὰρ τὸ μὴ ’πιτρέπειν τοῖς ἀδικοῦσιν, ὁρᾶθ’ ὡς καλὸν τὸ ῥῆμα. ἀποβλέψατε δὴ πρῶτον πρὸς τὸ ἔργον αὐτό. δεῖ κρατῆσαι μαχομένους τῶν ἐχθρῶν τοὺς τὴν τοῦ ῥήματος τούτου σεμνότητ’ ἔργῳ ληψομένους. εἰπεῖν μὲν γάρ, ὦ ἄνδρες Ἀθηναῖοι, πάντα πέφυκε ῥᾴδιον, πρᾶξαι δ’ οὐχ ἅπαντα. οὐ γὰρ ἴσος πόνος καὶ ἱδρὼς πρό τε τοῦ λέγειν καὶ πρὸ τοῦ πράττειν ἐστίν.", "st": "62.45.3"}, {"sp": "N", "t": "ἐγὼ δ’ οὐ χείρους ὑμᾶς ἡγοῦμαι φύσει Θηβαίων ʽκαὶ γὰρ ἂν μαινοίμην̓, ἀλλ’ ἀπαρασκευοτέρους. φημὶ δὴ δεῖν τοῦ παρασκευάζεσθαι νῦν ποιεῖσθαι τὴν ἀρχήν, ἐπειδὴ τέως ἠμελεῖτε, οὐ τοῦ διαγωνίζεσθαι. οὐ γὰρ ἀντιλέγω τὸ ὅλον, ἀλλ’ ὑπὲρ τοῦ τρόπου τῆς ἐγχειρήσεως ἐναντιοῦμαι.", "st": "62.45.4"}, {"sp": "SEC", "t": "Προοίμιον ΜϚʹ", "st": "62.46"}, {"sp": "N", "t": "ὅσην μέν, ὦ ἄνδρες Ἀθηναῖοι, πεποίηνται σπουδὴν οἱ πρέσβεις κατηγορῆσαι τῆς πόλεως ἡμῶν, ἅπαντες ἑοράκατε· πλὴν γὰρ οὐκ ἔχω τίνος εἴπω, τἄλλα πάνθ’ ὑμῖν ἀναθεῖναι πεπείρανται. εἰ μὲν οὖν ἦσαν αὐτῶν ἀληθεῖς αἱ κατηγορίαι, χάριν γ’ εἴχετ’ εἰκότως ἄν, εἰ πρὸς ὑμᾶς οὕτως ὑμῶν κατηγόρουν καὶ μὴ πρὸς ἄλλους.", "st": "62.46.1"}, {"sp": "N", "t": "ἐπειδὴ δὲ διαστρέψαντες τἀληθῆ, καὶ τὰ μὲν παραβαίνοντες, ἀφ’ ὧν ἂν μεγάλους ἐπαίνους κομίσαισθε δικαίως, τὰ δ’ αἰτιασάμενοι ψευδῆ καὶ οὐ προσήκονθ’ ὑμῖν, κέχρηνται τῷ λόγῳ, πονηροὺς δίκαιον αὐτούς, ἐπειδὰν ἐξελεγχθῶσι ταῦτα πεποιηκότες, νομίζειν. εἰ γὰρ ῥήτορες δεινοὶ μᾶλλον εἶναι δοκεῖν ἢ μετ’ ἀληθείας ἐπιεικεῖς ἄνθρωποι νομίζεσθαι προείλοντο, οὐδ’ αὐτοὶ καλοκἀγαθίας ἂν ὡς ἔοικεν ἀμφισβητοῖεν.", "st": "62.46.2"}, {"sp": "N", "t": "ἔστι μὲν οὖν χαλεπὸν τὸ παρ’ ὑμῖν ὑπὲρ ὑμῶν ἐροῦντ’ ἀνεστηκέναι, ὥσπερ ῥᾴδιον τὸ καθ’ ὑμῶν. ἐγὼ γὰρ μὰ τὴν Ἀθηνᾶν οὐδένας ἂν τῶν ἄλλων ἀνθρώπων οὕτως οἶμαι τὰ προσόνθ’ αὑτοῖς ἀκοῦσαι νουθετουμένους, ὡς ὑμεῖς τὰ μὴ προσήκοντα κακῶς ἀκούοντες. οὐ μὴν οὐδὲ τούτους θρασέως ἂν οὕτως ἡγοῦμαι ψεύδεσθαι, εἰ μὴ συνῄδεσαν ταῦτα, καὶ πρόδηλον ἦν ὅτι", "st": "62.46.3"}, {"sp": "N", "t": "δεινότατοι πάντων ὑμεῖς ἐστ’ ἀκούειν ὅ τι ἄν τις καθ’ ὑμῶν λέγῃ. εἰ μὲν οὖν ταύτης τῆς εὐηθείας δίκην ὑμᾶς δεῖ διδόναι, λόγους οὐ προσήκοντας κατὰ τῆς πόλεως ἀκούειν τοῦτ’ ἂν εἴη. εἰ δ’ ὑπὲρ τῶν ἀληθῶν εἴ τι δίκαιον ῥητέον, ἐπὶ τοῦτ’ ἐγὼ παρελήλυθα, πιστεύων οὐκ αὐτὸς ἀξίως τῶν ὑμῖν πεπραγμένων εἰπεῖν δυνήσεσθαι, ἀλλὰ τὰ πράγματα, ὅπως ἄν τις εἴπῃ, δίκαια φανεῖσθαι.", "st": "62.46.4"}, {"sp": "N", "t": "βουλοίμην δ’ ἂν ὑμᾶς, ὦ ἄνδρες Ἀθηναῖοι, ἴσους ἀκροατὰς ὑπὲρ ὑμῶν αὐτῶν γενέσθαι, καὶ μὴ τῷ προῆχθαι τοὺς λόγους ἐπαινέσαι τοὺς τούτων φιλονικεῖν. οὐ γὰρ ἂν ὑμετέραν κακίαν οὐδεὶς ἔτι κρίναι, εἰ λέγοντός τινος εὖ παρεκρούσθητε, ἀλλὰ τῶν ἐπὶ τούτῳ σπουδὴν ποιησαμένων, ὅπως ὑμᾶς ἐξαπατήσουσιν.", "st": "62.46.5"}, {"sp": "SEC", "t": "Προοίμιον ΜΖʹ", "st": "62.47"}, {"sp": "N", "t": "οἶμαι πάντας ἂν ὑμᾶς, ὦ ἄνδρες Ἀθηναῖοι, φῆσαι, ἃ βέλτισθ’ ἕκαστος ἡγεῖται τῇ πόλει, βούλεσθαι ταῦτα πραχθῆναι. συμβαίνει δέ γε μὴ κατὰ ταὐτὸ κεκρίσθαι παρὰ πᾶσι τὸ βέλτιστον· οὐ γὰρ ἂν ὑμῶν οἱ μὲν λέγειν, οἱ δὲ μὴ λέγειν ἐκέλευον. πρὸς μὲν τοίνυν τοὺς ὑπειληφότας ταῦτα συμφέρειν οὐδενὸς δεῖ λόγου τῷ μέλλοντι λέγειν· πεπεισμένοι γὰρ ὑπάρχουσι· πρὸς δὲ τοὺς τἀναντία συμφέρειν ἡγουμένους βραχέ’ εἰπεῖν βούλομαι.", "st": "62.47.1"}, {"sp": "N", "t": "μὴ ’θέλουσι μὲν οὖν ἀκούειν οὐκ ἔνι δήπου μαθεῖν, οὐδὲν μᾶλλον ἢ σιωπῶσιν μηδενὸς λέγοντος· ἀκούσασιν δὲ δυοῖν ἀγαθοῖν οὐκ ἔνι θατέρου διαμαρτεῖν. ἢ γὰρ πεισθέντες πάντες καὶ ταὔτ’ ἐγνωκότες κοινότερον βουλεύσεσθε, οὗ μεῖζον εἰς τὰ παρόντ’ οὐδὲν ἂν γένοιτ’ ἀγαθόν, ἢ μὴ δυνηθέντος τοῦ λέγοντος διδάξαι βεβαιότερον τοῖς ἐγνωσμένοις πιστεύσετε.", "st": "62.47.2"}, {"sp": "N", "t": "χωρὶς δὲ τούτων οὐδὲ καλὴν ὑποψίαν ἔχει ἥκειν μὲν εἰς τὴν ἐκκλησίαν ὡς ἐκ τῶν ῥηθησομένων τὸ κράτιστον ἑλέσθαι δέον, φανῆναι δέ, πρὶν ἐκ τῶν λόγων δοκιμάσαι, παρ’ ὑμῖν αὐτοῖς τι πεπεισμένους, καὶ τοῦθ’ οὕτως ἰσχυρὸν ὥστε μηδ’ ἐθέλειν παρὰ ταῦτ’ ἀκούειν.", "st": "62.47.3"}, {"sp": "SEC", "t": "Προοίμιον ΜΗʹ", "st": "62.48"}, {"sp": "N", "t": "ἴσως ὀχληρός, ὦ ἄνδρες Ἀθηναῖοι, τισὶν ὑμῶν εἶναι δοκῶ, πολλάκις λέγων περὶ τῶν αὐτῶν ἀεί. ἀλλ’ ἐὰν ὀρθῶς σκοπῆτε, οὐκ ἐγὼ φανήσομαι τούτου δίκαιος ὢν ἔχειν τὴν αἰτίαν, ἀλλ’ οἱ μὴ πειθόμενοι τοῖς ὑμετέροις ψηφίσμασιν. εἰ γὰρ ἐκεῖνοι τὸ πρῶτον ἐποίησαν ἃ ὑμεῖς προσετάξατε, οὐδὲν ἂν τὸ δεύτερον ἡμᾶς ἔδει λέγειν, οὐδ’ εἰ τὸ δεύτερον, αὖθις. νῦν δ’ ὅσῳ πλεονάκις τὰ προσήκονθ’ [ὑμῖν] ὑμεῖς ἐψηφίσασθε, τοσούτῳ μοι δοκοῦσιν ἧττον ἐκεῖνοι παρεσκευάσθαι ποιεῖν.", "st": "62.48.1"}, {"sp": "N", "t": "πρότερον μὲν οὖν ἔγωγε μὰ τοὺς θεοὺς οὐκ ᾔδειν πρὸς τί ποτ’ εἴη τοῦτ’ εἰρημένον “ἀρχὴ ἄνδρα δείκνυσιν·” νῦν δὲ κἂν ἄλλον μοι δοκῶ διδάξαι. οἱ γὰρ ἄρχοντες ἢ τινὲς αὐτῶν, ἵνα μὴ πάντας λέγω, τῶν μὲν ὑμετέρων ψηφισμάτων ἀλλ’ οὐδὲ τὸ μικρότατον φροντίζουσιν, ὅπως δὲ λήψονται. εἰ μὲν οὖν ἐνῆν δοῦναι, δικαίως ἂν αὐτὸ τοῦτό μοί τις ἐπέπληξεν, εἰ διὰ μικρὸν ἀνάλωμ’ ἐνοχλεῖν ὑμῖν ᾑρούμην· νῦν δ’ οὐκ ἔνι, καθάπερ οὐδὲ τούτους λέληθεν.", "st": "62.48.2"}, {"sp": "N", "t": "εἰ δ’ ὑπὲρ ὧν ὑμῖν λῃτουργεῖν δεῖ, προσθήσειν αὑτοῖς οἴονταί με, ληροῦσιν. καὶ ταῦτ’ ἴσως βούλονται καὶ προσδοκῶσιν· ἐγὼ δ’ οὐ ποιήσω ταῦτα, ἀλλ’ ἐὰν μὲν δῶσι, καθέλξω τὴν ναῦν καὶ τὰ προσήκοντα ποιήσω, εἰ δὲ μή, τοὺς αἰτίους ὑμῖν ἀποφανῶ.", "st": "62.48.3"}, {"sp": "SEC", "t": "Προοίμιον ΜΘʹ", "st": "62.49"}, {"sp": "N", "t": "οὐδέν’ ἂν εὖ φρονοῦντ’ ἀντειπεῖν, ὦ ἄνδρες Ἀθηναῖοι, νομίζω, ὡς οὐχ ἁπάντων ἄριστόν ἐστιν τῇ πόλει μάλιστα μὲν ἐξ ἀρχῆς μηδὲν ἀσύμφορον πράττειν, εἰ δὲ μή, παρεῖναι εὐθὺς τοὺς ἐναντιωσομένους. δεῖ μέντοι τούτῳ προσεῖναι ἐθέλοντας ἀκούειν ὑμᾶς καὶ διδάσκεσθαι· οὐδὲν γὰρ πλέον εἶναι τὸν ἐροῦντα τὰ βέλτιστα, ἂν μὴ τοὺς ἀκουσομένους ἔχῃ.", "st": "62.49.1"}, {"sp": "N", "t": "οὐ μὴν οὐδ’ ἐκεῖν’ ἀλυσιτελὲς μετὰ ταῦτ’ ἂν φανείη, ὅσ’ ἄν τις ὑμᾶς ἢ διὰ καιρὸν ἢ δι’ ὥραν ἡμέρας ἢ δι’ ἄλλην τιν’ αἰτίαν παρακρούσηται, ταῦθ’ ὅταν ποτὲ βούλησθ’ ὑμῶν αὐτῶν ὄντες ἀκούειν, εἶναι τὸν ἐξετάσοντα πάλιν, ἵν’ ἐὰν μὲν οἷά φασιν οἱ τότε πείσαντες φανῇ, προθυμότερον πράττηθ’ ὡς ἔλεγχον δεδωκότα, ἐὰν δ’ ἄρα μὴ τοιαῦθ’ εὑρεθῇ, πρὶν πορρωτέρω προελθεῖν ἐπίσχητε. καὶ γὰρ ἂν δεινὸν εἴη, εἰ τοῖς τοῦ κρατίστου διαμαρτοῦσι τὸ χείριστον ἀνάγκη πράττειν εἴη, καὶ μή, τὸ δεύτερον ἐκ τῶν λόγων, ἐξείη μεταβουλεύσασθαι.", "st": "62.49.2"}, {"sp": "N", "t": "τοὺς μὲν οὖν ἄλλους ἅπαντας ἔγωγ’ ὁρῶ τὴν ἀειλογίαν προτεινομένους, ὅταν τι πιστεύωσι δικαίως αὑτοῖς πεπρᾶχθαι· οὗτοι δ’ αὖ τοὐναντίον ἐγκαλοῦσιν, εἰ περὶ ὧν ἡμάρτετε νῦν ἀναθέσθαι βούλεσθε, τὴν ἀπάτην κυριωτέραν οἰόμενοι δεῖν εἶναι τῆς μετὰ τοῦ χρόνου βασάνου. τὴν μὲν οὖν τούτων σπουδὴν οὐδ’ ὑμῶν ἴσως ἀγνοοῦσιν οἱ πολλοί· δεῖ δ’ ὑπὲρ τῶν πραγμάτων, ἐπειδήπερ γέγονε λόγου τυχεῖν, ἅ τις ἡγεῖται κράτιστα, λέγειν.", "st": "62.49.3"}, {"sp": "SEC", "t": "Προοίμιον Νʹ", "st": "62.50"}, {"sp": "N", "t": "ὅ τι μὲν μέλλει συνοίσειν πάσῃ τῇ πόλει, τοῦτο καὶ λέγειν εὔχομαι πάντας, ὦ ἄνδρες Ἀθηναῖοι, καὶ ὑμᾶς ἑλέσθαι. ἐγὼ δ’ οὖν, ἃ πεπεικὼς ἐμαυτὸν τυγχάνω μάλιστα συμφέρειν ὑμῖν, ταῦτ’ ἐρῶ, δεηθεὶς ὑμῶν τοσοῦτον, μήτε τοὺς ἐξιέναι κελεύοντας ὑμᾶς διὰ τοῦτο νομίζειν ἀνδρείους, μήτε τοὺς ἀντιλέγειν ἐπιχειροῦντας διὰ τοῦτο κακούς. οὐ γὰρ ὁ αὐτὸς ἔλεγχος, ὦ ἄνδρες Ἀθηναῖοι, τῶν τε λόγων καὶ τῶν πραγμάτων ἐστίν, ἀλλὰ δεῖ νῦν εὖ βεβουλευμένους ἡμᾶς φανῆναι, τότε δέ, ἂν ἄρα ταῦτα δοκῇ, τὰ τῆς ἀνδρείας ἀποδείξασθαι.", "st": "62.50.1"}, {"sp": "N", "t": "ἡ μὲν οὖν ὑμετέρα προθυμία παντὸς ἀξία καὶ τοιαύτη πάρεστιν οἵαν ἄν τις εὔξαιτ’ εὔνους ὢν τῇ πόλει· νῦν δ’ ὅσῳ τυγχάνει σπουδαιοτέρα, τοσούτῳ δεῖ μᾶλλον προϊδεῖν ὅπως εἰς δέον καταχρήσεσθ’ αὐτῇ. οὐδενὸς γὰρ εὐδοκιμεῖ πράγματος ἡ προαίρεσις, ἂν μὴ καὶ τὸ τέλος συμφέρον καὶ καλὸν λάβῃ. ἐγὼ δ’ οἶδά ποτ’, ὦ ἄνδρες Ἀθηναῖοι, παρ’ ὑμῖν ἀκούσας ἀνδρὸς οὔτ’ ἀνοήτου δοκοῦντος εἶναι οὔτ’ ἀπείρου πολέμου,", "st": "62.50.2"}, {"sp": "N", "t": "Ἰφικράτους λέγω, ὃς ἔφη δεῖν οὕτω προαιρεῖσθαι κινδυνεύειν τὸν στρατηγὸν ὅπως μὴ τὰ ἢ τὰ γενήσεται, ἀλλ’ ὅπως τά· οὕτως γὰρ εἶπε τῷ ῥήματι. ἦν δὴ τοῦτο γνώριμον, ὅτι ὅπως καλῶς ἀγωνιεῖται ἔλεγεν. ἐπειδὰν μὲν τοίνυν ἐξέλθητε, ὃς ἂν ἡγῆται, κύριος ὑμῶν ἐστι· νῦν δ’ ἕκαστος ὑμῶν αὐτῶν στρατηγεῖ. δεῖ δὴ τοιαῦτα φανῆναι βεβουλευμένους δι’ ὧν πανταχῶς συνοίσει τῇ πόλει καὶ μὴ μελλουσῶν ἕνεκ’ ἐλπίδων τῆς παρούσης εὐδαιμονίας χεῖρόν τι ποιήσετε.", "st": "62.50.3"}, {"sp": "SEC", "t": "Προοίμιον ΝΑʹ", "st": "62.51"}, {"sp": "N", "t": "οὐδέν’ ἂν ᾠόμην, ὦ ἄνδρες Ἀθηναῖοι, πιστεύοντα τοῖς πεπραγμένοις ἐγκαλέσαι τοῖς καθιστᾶσιν εἰς λόγον ταῦτα· ὅσῳ γὰρ ἂν πλεονάκις ἐξετάζῃ τις αὐτά, ἀνάγκη τοὺς τούτων αἰτίους εὐδοκιμεῖν. οὐ μὴν ἀλλά μοι δοκοῦσιν αὐτοὶ φανερὸν καθιστάναι οὐκ ἐπί ⟨τῳ⟩ τῶν τῇ πόλει συμφερόντων πράξαντες. ὡς γοῦν ἐξελέγχεσθαι μέλλοντες, ἂν πάλιν εἰς λόγον ἔλθωσιν, φεύγουσι καὶ δεινὰ ποιεῖν ἡμᾶς φασιν. καίτοι ὅταν τοὺς ἐξελέγχειν βουλομένους δεινὰ ποιεῖν αἰτιᾶσθε, τί ἡμεῖς τοὺς ἡμᾶς αὐτοὺς ἐξηπατηκότας τηνικαῦτα λέγωμεν;", "st": "62.51.1"}, {"sp": "SEC", "t": "Προοίμιον ΝΒʹ", "st": "62.52"}, {"sp": "N", "t": "ἦν μὲν δίκαιον, ὦ ἄνδρες Ἀθηναῖοι, τὴν ἴσην ὑπάρχειν παρ’ ὑμῶν ὀργὴν τοῖς ἐπιχειροῦσιν ὅσηνπερ τοῖς δυνηθεῖσιν ἐξαπατῆσαι. ὃ μὲν γὰρ ἦν ἐπὶ τούτοις, πεποίηται καὶ προήγαγον ὑμᾶς· τοῦ δὲ μὴ τέλος ταῦτ’ ἔχειν ἡ τύχη καὶ τὸ βέλτιον νῦν ὑμᾶς φρονεῖν ἢ ὅτ’ ἐξήχθηθ’ ὑπὸ τούτων, γέγονεν αἴτια. οὐ μὴν ἀλλ’ ἔγωγ’ οὕτω πόρρω νομίζω τὴν πόλιν εἶναι τοῦ δίκην παρὰ τῶν ἀδικούντων λαμβάνειν ὥστ’ ἀγαπητὸν εἶναί μοι δοκεῖ, ἂν ὅπως μὴ πείσεσθε κακῶς δύνησθε φυλάττεσθαι· τοσαῦται τέχναι καὶ γοητεῖαι καὶ ὅλως ὑπηρεσίαι τινές εἰσιν ἐφ’ ὑμᾶς κατεσκευασμέναι. τῆς μὲν οὖν τούτων κακίας οὐκ ἂν ἐν τῷ παρόντι τις ἐν δέοντι μάλιστα κατηγορήσειεν· βούλομαι δ’ ὑπὲρ ὧν ἀνέστην, ἃ νομίζω συμφέροντ’ εἰπεῖν.", "st": "62.52.1"}, {"sp": "SEC", "t": "Προοίμιον ΝΓʹ", "st": "62.53"}, {"sp": "N", "t": "ἡ μὲν εἰωθυῖα πάντα τὸν χρόνον βλάπτειν, ὦ ἄνδρες Ἀθηναῖοι, τὴν πόλιν λοιδορία καὶ ταραχὴ καὶ νυνὶ γέγονε παρὰ τῶν αὐτῶν ὧνπερ ἀεί. ἄξιον δ’ οὐχ οὕτω τούτοις ἐπιτιμῆσαι (ἴσως γὰρ ὀργῇ καὶ φιλονικίᾳ ταῦτα πράττουσι, καὶ τὸ μέγιστον ἁπάντων, ὅτι συμφέρει ταῦτα ποιεῖν αὐτοῖς) ἀλλ’ ὑμῖν, εἰ περὶ κοινῶν, ὦ ἄνδρες Ἀθηναῖοι, πραγμάτων καὶ μεγάλων συνειλεγμένοι τὰς ἰδίας λοιδορίας ἀκροώμενοι κάθησθε, καὶ οὐ δύνασθε πρὸς ὑμᾶς αὐτοὺς λογίσασθαι τοῦθ’, ὅτι αἱ τῶν ῥητόρων ἁπάντων ἄνευ κρίσεως πρὸς ἀλλήλους λοιδορίαι, ὧν ἂν ἀλλήλους ἐξελέγξωσιν, ὑμᾶς τὰς εὐθύνας διδόναι ποιοῦσιν.", "st": "62.53.1"}, {"sp": "N", "t": "πλὴν γὰρ ὀλίγων ἴσως, ἵνα μὴ πάντας εἴπω, οὐδεὶς αὐτῶν ἅτερος θατέρῳ λοιδορεῖται, ἵνα βέλτιόν τι τῶν ὑμετέρων γίγνηται ʽπολλοῦ γε καὶ δεἶ, ἀλλ’ ἵνα, ἃ τὸν δεῖνά φησι ποιοῦντα [ἂν δέῃ] δεινότατ’ ἀνθρώπων ποιεῖν, ταῦτ’ αὐτὸς μετὰ πλείονος ἡσυχίας διαπράττηται.", "st": "62.53.2"}, {"sp": "N", "t": "ὅτι δ’ οὕτω ταῦτ’ ἔχει, μὴ ἐμοὶ πιστεύσητε, ἀλλ’ ἐν βραχεῖ λογίσασθε. ἔστιν ὅπου τις ἀναστὰς εἶπεν παρ’ ὑμῖν πώποτε “βουλόμενός τι λαβεῖν τῶν ὑμετέρων παρελήλυθ’, ὦ ἄνδρες Ἀθηναῖοι, οὐχ ὑπὲρ ὑμῶν;” οὐδεὶς δήπου, ἀλλ’ ὑπὲρ ὑμῶν καὶ δι’ ὑμᾶς, καὶ τοιαύτας προφάσεις λέγουσιν. φέρε δὴ σκέψασθε, τί δή ποτ’, ὦ ἄνδρες Ἀθηναῖοι, ὑπὲρ ὧν ἅπαντες λέγουσιν, οὐδὲν βέλτιον τοῖς ὅλοις νῦν ἢ πρότερον πράττετε, οὗτοι δ’ οἱ πάνθ’ ὑπὲρ ὑμῶν, ὑπὲρ αὑτῶν δ’ οὐδεὶς οὐδὲν πώποτ’ εἰρηκώς, ἐκ πτωχῶν πλούσιοι γεγόνασιν; ὅτι φασὶν μέν, ὦ ἄνδρες Ἀθηναῖοι, φιλεῖν ὑμᾶς, φιλοῦσι δ’ οὐχ ὑμᾶς ἀλλ’ αὑτούς.", "st": "62.53.3"}, {"sp": "N", "t": "καὶ γελάσαι καὶ θορυβῆσαι καί ποτ’ ἐλπίσαι μετέδωκαν ὑμῖν, λαβεῖν δ’ ἢ κτήσασθαι τῇ πόλει κυρίως ἀγαθὸν οὐδὲν ἂν βούλοιντο. ᾗ γὰρ ἂν ἡμέρᾳ τῆς λίαν ἀρρωστίας ἀπαλλαγῆτε, ταύτῃ τούτους οὐδ’ ὁρῶντες ἀνέξεσθε. νῦν δὲ δραχμῇ καὶ χοῒ καὶ τέτταρσιν ὀβολοῖς ὥσπερ ἀσθενοῦντα τὸν δῆμον διάγουσιν, ὁμοιότατ’, ὦ ἄνδρες Ἀθηναῖοι, τοῖς παρὰ τῶν ἰατρῶν σιτίοις διδόντες ὑμῖν. καὶ γὰρ ἐκεῖν’ οὔτ’ ἰσχὺν ἐντίθησιν οὔτ’ ἀποθνῄσκειν ἐᾷ, καὶ ταῦτ’ οὔτ’ ἀπογνόντας ἄλλο τι μεῖζον πράττειν ἐᾷ, οὔτ’ αὔτ’ ἐξαρκεῖν δύναται.", "st": "62.53.4"}, {"sp": "SEC", "t": "Προοίμιον ΝΔʹ", "st": "62.54"}, {"sp": "N", "t": "καὶ δίκαιον, ὦ ἄνδρες Ἀθηναῖοι, καὶ καλὸν καὶ σπουδαῖον, ὅπερ ὑμεῖς εἰώθατε, καὶ ἡμᾶς προνοεῖν, ὅπως τὰ πρὸς τοὺς θεοὺς εὐσεβῶς ἕξει. ἡ μὲν οὖν ἡμετέρα γέγονεν ἐπιμέλει’ ὑμῖν εἰς δέον· καὶ γὰρ ἐθύσαμεν τῷ Διὶ τῷ σωτῆρι καὶ τῇ Ἀθηνᾷ καὶ τῇ Νίκῃ, καὶ γέγονεν καλὰ καὶ σωτήρια ταῦθ’ ὑμῖν τὰ ἱερά. ἐθύσαμεν δὲ καὶ τῇ Πειθοῖ καὶ τῇ Μητρὶ τῶν θεῶν καὶ τῷ Ἀπόλλωνι, καὶ ἐκαλλιεροῦμεν καὶ ταῦτα. ἦν δ’ ὑμῖν καὶ τὰ τοῖς ἄλλοις θεοῖς τυθένθ’ ἱέρ’ ἀσφαλῆ καὶ βέβαια καὶ καλὰ καὶ σωτήρια. δέχεσθ’ οὖν παρὰ τῶν θεῶν διδόντων τἀγαθά.", "st": "62.54.1"}, {"sp": "SEC", "t": "Προοίμιον ΝΕʹ", "st": "62.55"}, {"sp": "N", "t": "ἦν τις, ὡς ἔοικεν, χρόνος παρ’ ὑμῖν, ὦ ἄνδρες Ἀθηναῖοι, ὅτ’ ἐπηνάγκαζεν ὁ δῆμος, ὃν ἄνθρωπον ἴδοι σώφρονα καὶ χρηστόν, πράττειν τὰ κοινὰ καὶ ἄρχειν, οὐ σπάνει τῶν τοῦτο βουλομένων ποιεῖν (πάντα γὰρ τἄλλ’ εὐτυχῆ τὴν πόλιν κρίνων, ἓν οὐδέποτ’ εὐτυχῆσαι τοῦτο νομίζω, ἐπιλείπειν αὐτὴν τοὺς τὰ κοινὰ καρποῦσθαι βουλομένους), ἀλλ’ ὅραμα τοῦτ’ ἐποιεῖθ’ ὁ δῆμος αὑτοῦ καλόν, ὦ ἄνδρες Ἀθηναῖοι, καὶ λυσιτελὲς τῇ πόλει.", "st": "62.55.1"}, {"sp": "N", "t": "οἵ τε γὰρ συνεχεῖς οἵδε παραζευγνυμένων σφίσιν ἐξ ἰδιωτῶν σπουδαίων καὶ δικαίων ἀνδρῶν, εὐλαβεστέρους αὑτοὺς παρεῖχον, οἵ τε χρηστοὶ μὲν ὑμῶν καὶ δικαίως ⟨ἂν⟩ ἄρχοντες, μὴ πάνυ δ’ οἷοί τ’ ἐνοχλεῖν καὶ παραγγέλλειν, οὐκ ἀπηλαύνοντο τῶν τιμῶν. νῦν δὲ παντάπασι τὸν αὐτὸν τρόπον, ὦ ἄνδρες Ἀθηναῖοι, ὅνπερ τοὺς ἱερεῖς, οὕτως καθίστατε καὶ τοὺς ἄρχοντας. εἶτα θαυμάζετε, ἐπειδὰν ὁ δεῖν’ εὐδαίμων καὶ ὁ δεῖν’ ὑμῖν ᾖ συνεχῶς πολλὰ λαμβάνων, οἱ δ’ ἄλλοι περιίητε τὰ τούτων ἀγαθὰ ζηλοῦντες.", "st": "62.55.2"}, {"sp": "N", "t": "δεινότατοι γάρ ἐστ’ ἀφελέσθαι μὲν ὅσ’ ὑμῖν ὑπάρχει, καὶ νόμους περὶ τούτων θεῖναι, ἄν τις ἀστυνομήσῃ δὶς ἢ τὰ τοιαῦτα, στρατηγεῖν δ’ ἀεὶ τοὺς αὐτοὺς ἐᾶν. καὶ τὸ μὲν τοὺς ἐπὶ τῶν πράξεων ὄντας ἴσως ἔχει πρόφασιν· τὸ δὲ τοὺς ἄλλους, οἳ ποιοῦσι μὲν οὐδέν, χώραν δ’ ἀτέλεστον ἔχουσιν αὐτοὶ τετελεσμένοι, μωρία. ἀλλὰ καὶ ὑμῶν αὐτῶν ʽεἰσὶ δ’ οὐκ ὀλίγοἰ προσάγειν χρή. ἂν γὰρ ὡσπερεὶ ζυγῷ ἱστῆτε, πρόεισιν ὃς ἂν ἄξιος ᾖ του μετὰ ταῦτ’ αὐτός.", "st": "62.55.3"}, {"sp": "SEC", "t": "Προοίμιον ΝϚʹ", "st": "62.56"}, {"sp": "N", "t": "τὸ μέν, ὦ ἄνδρες Ἀθηναῖοι, πεπεικόθ’ ἑαυτὸν ἔχειν τι συμφέρον εἰπεῖν ἀνίστασθαι καὶ καλὸν καὶ προσῆκον εἶναί μοι δοκεῖ, τὸ δὲ μὴ βουλομένους ἀκούειν βιάζεσθαι παντελῶς ἔγωγ’ αἰσχρὸν ἡγοῦμαι [εἶναι]. οἴομαι δέ, ἐὰν ἐθελήσητέ μοι πείθεσθαι τήμερον, καὶ τὰ βέλτιστα μᾶλλον ὑμᾶς ἑλέσθαι δυνήσεσθαι καὶ τοὺς τῶν ἀναβαινόντων λόγους βραχεῖς ποιήσειν.", "st": "62.56.1"}, {"sp": "N", "t": "τί οὖν συμβουλεύω; πρῶτον μέν, ὦ ἄνδρες Ἀθηναῖοι, περὶ αὐτῶν ὧν σκοπεῖτε τὸν παριόντα λέγειν ἀξιοῦν. πολλὰ γὰρ ἄλλα τις ἂν περιέλθοι τῷ λόγῳ καὶ πόλλ’ ἂν ἀστεῖ’ εἴποι, ἄλλως τε καὶ ὥσπερ τούτων ἔνιοι δεινῶν ὄντων. ἀλλ’ εἰ μὲν ῥημάτων ἥκετ’ ἀκουσόμενοι, ταῦτα λέγειν καὶ ἀκούειν χρή· εἰ δ’ ὑπὲρ πραγμάτων αἱρέσεως βουλευσόμενοι, αὐτὰ καθ’ ἑαυτὰ παραινῶ τὰ πράγμαθ’ ὡς μάλιστα κρίνειν, ἀφελόντας ὅσοι λόγοι πεφύκασιν ἐξαπατᾶν.", "st": "62.56.2"}, {"sp": "N", "t": "ἓν μὲν οὖν τοῦτο λέγω, δεύτερον δέ, ὅ τισιν ἴσως παράδοξον ἔσται πρὸς τὸ τοὺς λόγους ἐλάττους εἶναι, σιωπῶντας ἀκούειν. περὶ μὲν γὰρ τοῦ ταῦτ’ ἢ ’κεῖνα συμφέρειν, καὶ πότερ’ ἂν δικαιότερον προέλοιθ’ ἡ πόλις, οὔτ’ εἰσὶ λόγοι πολλοὶ μὴ βουλομένοις μάτην ἀδολεσχεῖν, οὔτε πᾶς τις ἂν αὐτοὺς εἰπεῖν ἔχοι· ὡς δὲ καὶ δίκαιον ἀκούειν καὶ πρὸς τὸν θόρυβον ἀποκρίνασθαι καὶ λόγον ἐκ λόγου λέγειν, οὐδεὶς ὅστις οὐχὶ δύναιτ’ ἄν. ἐκ δὴ τοῦ θορυβεῖν οὐκ ἀπαλλάττεσθε λόγων, ἀλλὰ καὶ περὶ τῶν οὐδὲν εἰς χρείαν ἐπαναγκάζεσθ’ ἀκούειν. ἡ μὲν οὖν ἐμὴ γνώμη περὶ ὧν βουλεύεσθε, ἥδ’ ἐστίν.", "st": "62.56.3"}, {"sp": "HDR", "t": "Δημοσθένους ἐπιστολαὶ", "st": "63"}, {"sp": "SEC", "t": "1. Περὶ τῆς ὁμονοίας", "st": "63.1"}, {"sp": "N", "t": "παντὸς ἀρχομένῳ σπουδαίου καὶ λόγου καὶ ἔργου ἀπὸ τῶν θεῶν ὑπολαμβάνω προσήκειν πρῶτον ἄρχεσθαι. εὔχομαι δὴ τοῖς θεοῖς πᾶσι καὶ πάσαις, ὅ τι τῷ δήμῳ τῷ Ἀθηναίων ἄριστόν ἐστι καὶ τοῖς εὐνοοῦσι τῷ δήμῳ καὶ νῦν καὶ εἰς τὸν ἔπειτα χρόνον, τοῦτ’ ἐμοὶ μὲν ἐπὶ νοῦν ἐλθεῖν γράψαι, τοῖς δ’ ἐκκλησιάσασιν Ἀθηναίων ἑλέσθαι. εὐξάμενος δὲ ταῦτα, τῆς ἀγαθῆς ἐπινοίας ἐλπίδ’ ἔχων παρὰ τῶν θεῶν, τάδ’ ἐπιστέλλω.", "st": "63.1.1"}, {"sp": "N", "t": "Δημοσθένης τῇ βουλῇ καὶ τῷ δήμῳ χαίρειν.", "st": "63.1.2"}, {"sp": "N", "t": "περὶ μὲν τῆς ἐμῆς οἴκαδ’ ἀφίξεως ἀεὶ νομίζω πᾶσιν ὑμῖν ἔσεσθαι βουλεύσασθαι, διόπερ νῦν οὐδὲν περὶ αὐτῆς γέγραφα· τὸν δὲ παρόντα καιρὸν ὁρῶν ἑλομένων μὲν ὑμῶν τὰ δέοντα ἅμα δόξαν καὶ σωτηρίαν καὶ ἐλευθερίαν δυνάμενον κτήσασθαι οὐ μόνον ὑμῖν ἀλλὰ καὶ τοῖς ἄλλοις ἅπασιν Ἕλλησιν, ἀγνοησάντων δ’ ἢ παρακρουσθέντων οὐ ῥᾴδιον αὖθις τὸν αὐτὸν ἀναλαβεῖν, ᾠήθην χρῆναι τὴν ἐμαυτοῦ γνώμην ὡς ἔχω περὶ τούτων εἰς μέσον θεῖναι.", "st": "63.1.2"}, {"sp": "N", "t": "ἔστι μὲν οὖν ἔργον ἐξ ἐπιστολῆς ἐμμεῖναι συμβουλῇ· πολλοῖς γὰρ εἰώθατ’ ἀπαντᾶν ὑμεῖς πρὸ τοῦ περιμεῖναι μαθεῖν. λέγοντι μὲν οὖν ἔστιν αἰσθέσθαι τί βούλεσθε καὶ διορθώσασθαι τἀγνοούμενα ῥᾴδιον· τὸ δὲ βιβλίον οὐδεμίαν ἔχει βοήθειαν τοιαύτην πρὸς τοὺς θορυβοῦντας. οὐ μὴν ἀλλ’ ἐὰν ἐθελήσητ’ ἀκοῦσαι σιγῇ καὶ περιμείνητε πάντα μαθεῖν, οἴομαι, ὡς σὺν θεοῖς εἰρῆσθαι, καίπερ βραχέων τῶν γεγραμμένων ὄντων, αὐτός τε φανήσεσθαι μετὰ πάσης εὐνοίας τὰ δέονθ’ ὑπὲρ ὑμῶν πράττων καὶ τὰ συμφέρονθ’ ὑμῖν ἐμφανῆ δείξειν.", "st": "63.1.3"}, {"sp": "N", "t": "οὐχ ὡς ἀπορούντων δ’ ὑμῶν ῥητόρων, οὐδὲ τῶν ἄνευ λογισμοῦ ῥᾳδίως ὅ τι ἂν τύχωσιν ἐρούντων, ἔδοξέ μοι τὴν ἐπιστολὴν πέμπειν· ἀλλ’ ὅσα τυγχάνω δι’ ἐμπειρίαν καὶ τὸ παρηκολουθηκέναι τοῖς πράγμασιν εἰδώς, ταῦτ’ ἐβουλήθην τοῖς μὲν προαιρουμένοις λέγειν ἐμφανῆ ποιήσας ἀφθόνους ἀφορμὰς ὧν ὑπολαμβάνω συμφέρειν ὑμῖν δοῦναι, τοῖς δὲ πολλοῖς ῥᾳδίαν τὴν τῶν βελτίστων αἵρεσιν καταστῆσαι. ὧν μὲν οὖν ἕνεκ’ ἐπῆλθέ μοι τὴν ἐπιστολὴν γράφειν, ταῦτ’ ἐστίν.", "st": "63.1.4"}, {"sp": "N", "t": "δεῖ δ’ ὑμᾶς, ὦ ἄνδρες Ἀθηναῖοι, πρῶτον μὲν ἁπάντων πρὸς ὑμᾶς αὐτοὺς ὁμόνοιαν εἰς τὸ κοινῇ συμφέρον τῇ πόλει παρασχέσθαι καὶ τὰς ἐκ τῶν προτέρων ἐκκλησιῶν ἀμφισβητήσεις ἐᾶσαι, δεύτερον δὲ πάντας ἐκ μιᾶς γνώμης τοῖς δόξασι προθύμως συναγωνίζεσθαι· ὡς τὸ μήθ’ ἓν μήθ’ ἁπλῶς πράττειν οὐ μόνον ἐστὶν ἀνάξιον ὑμῶν καὶ ἀγεννές, ἀλλὰ καὶ τοὺς μεγίστους κινδύνους ἔχει.", "st": "63.1.5"}, {"sp": "N", "t": "δεῖ δὲ μηδὲ ταῦτα λαθεῖν ὑμᾶς, ἃ καθ’ αὑτὰ μὲν οὐκ ἔστιν αὐτάρκη κατασχεῖν πράγματα, προστεθέντα δὲ ταῖς δυνάμεσι πολλῷ πάντ’ εὐκατεργαστότερ’ ὑμῖν ποιήσει. τίν’ οὖν ἐστιν ταῦτα; μήτε πόλει μηδεμιᾷ μήτε τῶν ⟨ἐν⟩ ἑκάστῃ τῶν πόλεων συνηγωνισμένων τοῖς καθεστηκόσι ⟨μηδενὶ⟩ μήτε πικραίνεσθαι μήτε μνησικακεῖν.", "st": "63.1.6"}, {"sp": "N", "t": "ὁ γὰρ τοιοῦτος φόβος τοὺς συνειδότας αὑτοῖς, ὡς ἀναγκαίοις τοῖς καθεστηκόσι καὶ κίνδυνον ἔχουσι πρόδηλον προθύμους συναγωνιστὰς ποιεῖ· ἀφεθέντες δὲ τοῦ δέους τούτου πάντες ἠπιώτεροι γενήσονται. τοῦτο δ’ οὐ μικρὰν ὠφέλειαν ἔχει. κατὰ μὲν δὴ πόλεις τὰ τοιαῦτ’ εὔηθες προλέγειν, μᾶλλον δ’ οὐδ’ ἐν δυνατῷ· ὡς δ’ ἂν ὑμῖν αὐτοῖς ὀφθῆτε χρώμενοι, τοιαύτην καὶ κατὰ τῶν ἄλλων προσδοκίαν παραστήσεθ’ ἑκάστοις.", "st": "63.1.7"}, {"sp": "N", "t": "φημὶ δὴ χρῆναι μήτε στρατηγῷ μήτε ῥήτορι μήτ’ ἰδιώτῃ μηδενὶ τῶν τὰ πρὸ τοῦ γε δοκούντων συνηγωνίσθαι τοῖς καθεστηκόσι μήτε μέμφεσθαι μήτ’ ἐπιτιμᾶν μηδένα μηδὲν ὅλως, ἀλλὰ συγχωρῆσαι πᾶσιν τοῖς ἐν τῇ πόλει πεπολιτεῦσθαι τὰ δέοντα, ἐπειδήπερ οἱ θεοί, καλῶς ποιοῦντες, σῴσαντες τὴν πόλιν ἀποδεδώκασιν ὑμῖν ὅ τι ἂν βούλησθ’ ἐξ ἀρχῆς βουλεύσασθαι, καὶ νομίζειν, ὥσπερ ἂν ἐν πλοίῳ τῶν μὲν ἱστίῳ, τῶν δὲ κώπαις ἀποφαινομένων κομίζεσθαι, λέγεσθαι μὲν ὑπ’ ἀμφοτέρων ἅπαντ’ ἐπὶ σωτηρίᾳ, γεγενῆσθαι δὲ τὴν χρείαν πρὸς τὰ συμβάντ’ ἀπὸ τῶν θεῶν.", "st": "63.1.8"}, {"sp": "N", "t": "ἐὰν τοῦτον τὸν τρόπον περὶ τῶν παρεληλυθότων ἐγνωκότες ἦτε, καὶ πιστοὶ πᾶσι γενήσεσθε, καὶ καλῶν κἀγαθῶν ἀνδρῶν ἔργα πράξετε, καὶ τὰ πράγματ’ ὠφελήσετ’ οὐ μικρά, καὶ τοὺς ἐναντιωθέντας ἐν ταῖς πόλεσιν ἢ μεταγνῶναι ποιήσετε πάντας ἢ κομιδῇ ὀλίγους τινὰς αὐτοὺς τοὺς αἰτίους καταλειφθῆναι. μεγαλοψύχως τοίνυν καὶ πολιτικῶς τὰ κοινῇ συμφέροντα πράττετε, καὶ τῶν ἰδίων ⟨μὴ⟩ μέμνησθε.", "st": "63.1.9"}, {"sp": "N", "t": "παρακαλῶ δ’ εἰς ταῦτ’ οὐ τυχὼν αὐτὸς τῆς τοιαύτης φιλανθρωπίας παρ’ ἐνίων, ἀλλ’ ἀδίκως καὶ στασιαστικῶς εἰς τὴν ἑτέρων χάριν προποθείς. ἀλλ’ οὔτε τὴν ἰδίαν ὀργὴν ἀποπληρῶν τὸ κοινῇ συμφέρον οἶμαι δεῖν βλάπτειν, οὔτε μείγνυμι τῆς ἰδίας ἔχθρας εἰς τὰ κοινῇ συμφέροντ’ οὐδέν, ἀλλ’ ἐφ’ ἃ τοὺς ἄλλους παρακαλῶ, ταῦτ’ αὐτὸς οἴομαι δεῖν πρῶτος ποιεῖν.", "st": "63.1.10"}, {"sp": "N", "t": "αἱ μὲν οὖν παρασκευαὶ καὶ ἃ δεῖ φυλάξασθαι, καὶ ἃ πράττων τις ἂν κατ’ ἀνθρώπινον λογισμὸν μάλιστα κατορθοίη, σχεδὸν εἴρηταί μοι· τοῖς δὲ καθ’ ἡμέραν ἐπιστατῆσαι, καὶ τοῖς ἐκ τοῦ παραχρῆμα συμβαίνουσιν ὀρθῶς χρῆσθαι,", "st": "63.1.11"}, {"sp": "N", "t": "καὶ γνῶναι τὸν ἑκάστου καιρόν, καὶ κρῖναι τί τῶν πραγμάτων ἐξ ὁμιλίας δυνατὸν προσαγαγέσθαι καὶ τί βίας προσδεῖται, τῶν ἐφεστηκότων [στρατηγῶν] ἔργον ἐστίν. διὸ καὶ χαλεπωτάτην τάξιν ἔχει τὸ συμβουλεύειν· τὰ γὰρ ὀρθῶς βουλευθέντα καὶ δοκιμασθέντα σὺν πολλῇ σπουδῇ καὶ πόνῳ πολλάκις τῷ τοὺς ἐπιστάντας ἄλλως χρήσασθαι διελυμάνθη.", "st": "63.1.12"}, {"sp": "N", "t": "νῦν μέντοι πάνθ’ ἕξειν καλῶς ἐλπίζω. καὶ γὰρ εἴ τις ὑπείληφεν εὐτυχῆ τὸν Ἀλέξανδρον τῷ πάντα κατορθοῦν, ἐκεῖνο λογισάσθω, ὅτι πράττων καὶ πονῶν καὶ τολμῶν, οὐχὶ καθήμενος ηὐτύχει. νῦν τοίνυν τεθνεῶτος ἐκείνου ζητεῖ τινας ἡ τύχη μεθ’ ὧν ἔσται.", "st": "63.1.13"}, {"sp": "N", "t": "τούτους δ’ ὑμᾶς δεῖ γενέσθαι. τούς θ’ ἡγεμόνας, δι’ ὧν ἀνάγκη τὰ πράγματα πράττεσθαι, ὡς εὐνουστάτους ἐπὶ τὰς δυνάμεις ἐφίστατε· καὶ ὅ τι ποιεῖν αὐτὸς ἕκαστος ὑμῶν δυνήσεται καὶ βουλήσεται, τοῦτο πρὸς αὑτὸν εἰπάτω καὶ ὑποσχέσθω. καὶ τοῦθ’ ὅπως μὴ ψεύσεται, μηδ’ ἐξηπατῆσθαι μηδὲ πεισθῆναι παρακρουσθεὶς φήσας ἀναδύσεται.", "st": "63.1.14"}, {"sp": "N", "t": "ὡς τὴν ἔκδειαν ὧν ἂν ἐλλίπηθ’ ὑμεῖς, οὐχ εὑρήσετε τοὺς ἀναπληρώσοντας· οὐδὲ τὸν αὐτὸν ἔχει κίνδυνον, περὶ ὧν ἐφ’ ὑμῖν ἐστιν ὅπως ἂν βούλησθε πρᾶξαι μεταβουλεύεσθαι πολλάκις, καὶ περὶ ὧν ἂν ἐνστῇ πόλεμος· ἀλλ’ ἡ περὶ τούτων μετάγνωσις ἧττα τῆς προαιρέσεως γίγνεται. μὴ δὴ ποιήσητε τοιοῦτο μηδέν, ἀλλ’ ὅ τι πράξετε γενναίως καὶ ἑτοίμως ταῖς ψυχαῖς, τοῦτο χειροτονεῖτε,", "st": "63.1.15"}, {"sp": "N", "t": "κἂν ἅπαξ ψηφίσησθε, τὸν Δία τὸν Δωδωναῖον καὶ τοὺς ἄλλους θεούς, οἳ πολλὰς καὶ καλὰς κἀγαθὰς καὶ ἀληθεῖς ὑμῖν μαντείας ἀνῃρήκασιν, ἡγεμόνας ποιησάμενοι καὶ παρακαλέσαντες, καὶ κατὰ τῶν νικητηρίων ἅπασιν αὐτοῖς εὐξάμενοι, μετὰ τῆς ἀγαθῆς τύχης ἐλευθεροῦτε τοὺς Ἕλληνας. εὐτυχεῖτε.", "st": "63.1.16"}, {"sp": "SEC", "t": "2. Περὶ τῆς ἰδίας καθόδου", "st": "63.2"}, {"sp": "N", "t": "Δημοσθένης τῇ βουλῇ καὶ τῷ δημῷ χαίρειν. ἐνόμιζον μὲν ἀφ’ ὧν ἐπολιτευόμην, οὐχ ὅπως μηδὲν ὑμᾶς ἀδικῶν τοιαῦτα πείσεσθαι, ἀλλὰ καὶ μέτρι’ ἐξαμαρτὼν συγγνώμης τεύξεσθαι. ἐπειδὴ δ’ οὕτως γέγονεν, ἕως μὲν ἑώρων ὑμᾶς, οὐδεμιᾶς ἀποδείξεως φανερᾶς οὐδ’ ἐλέγχου γιγνομένου παρὰ τῆς βουλῆς, πρὸς τὰ ταύτης ἀπόρρητα καταψηφιζομένους ἁπάντων, οὐδὲν ἐλαττόνων παραχωρεῖν ὑμᾶς ἡγούμενος ἢ ἐμαυτὸν ἀποστερεῖσθαι, στέργειν ᾑρούμην· τὸ γὰρ οἷς ἂν ἡ βουλὴ φήσῃ τοὺς ὀμωμοκότας δικαστὰς προστίθεσθαι μηδεμιᾶς ἀποδείξεως ῥηθείσης, τῆς πολιτείας παραχωρεῖν ἦν.", "st": "63.2.1"}, {"sp": "N", "t": "ἐπειδὴ δὲ καλῶς ποιοῦντες ᾔσθησθε τὴν δυναστείαν ἥν τινες τῶν ἐν τῇ βουλῇ κατεσκευάζονθ’ ἑαυτοῖς, καὶ πρὸς τὰς ἀποδείξεις τοὺς ἀγῶνας κρίνετε, τὰ δ’ ἀπόρρητα ⟨τὰ⟩ τούτων ἐπιτιμήσεως ἄξι’ ηὑρήκατε, οἶμαι δεῖν, ἐὰν καὶ ὑμῖν βουλομένοις ᾖ, τῆς ὁμοίας τυχεῖν σωτηρίας τοῖς τῶν ὁμοίων αἰτιῶν τετυχηκόσιν, καὶ μὴ μόνος δι’ αἰτίαν ψευδῆ τῆς πατρίδος καὶ τῶν ὄντων καὶ τῆς τῶν οἰκειοτάτων συνηθείας ἀποστερηθῆναι.", "st": "63.2.2"}, {"sp": "N", "t": "εἰκότως δ’ ἂν ὑμῖν, ὦ ἄνδρες Ἀθηναῖοι, μέλοι τῆς ἐμῆς σωτηρίας οὐ μόνον κατὰ τοῦθ’ ὅτι οὐδὲν ὑμᾶς ἀδικῶν δεινὰ πέπονθα, ἀλλὰ καὶ τῆς παρὰ τοῖς ἄλλοις ἀνθρώποις ἕνεκ’ εὐδοξίας. μὴ γάρ, εἰ μηδεὶς ὑμᾶς ἀναμιμνῄσκει τοὺς χρόνους μηδὲ τοὺς καιροὺς ἐν οἷς τὰ μέγιστ’ ἐγὼ χρήσιμος ἦν τῇ πόλει,", "st": "63.2.3"}, {"sp": "N", "t": "τοὺς ἄλλους Ἕλληνας ἀγνοεῖν νομίζετε, μηδ’ ἐπιλελῆσθαι τῶν ἐμοὶ πεπραγμένων ὑπὲρ ὑμῶν, ἃ ἐγὼ δυοῖν ἕνεκα νῦν ὀκνῶ γράφειν καθ’ ἕκαστον, ἑνὸς μέν, τὸν φθόνον δεδιώς, πρὸς ὃν οὐδέν ἐστιν προὔργου τἀληθῆ λέγειν, ἑτέρου δέ, ὅτι πολλὰ καὶ ἀνάξι’ ἐκείνων διὰ τὴν τῶν ἄλλων Ἑλλήνων κακίαν νῦν πράττειν ἀναγκαζόμεθα.", "st": "63.2.4"}, {"sp": "N", "t": "ἐν κεφαλαίῳ δὲ τοιαῦτ’ ἐστὶν ἐφ’ οἷς ἐξηταζόμην ὑπὲρ ὑμῶν ἐγώ, ὥσθ’ ὑμᾶς μὲν ἐπ’ αὐτοῖς ὑπὸ πάντων ζηλοῦσθαι, ἐμοὶ δ’ ἐλπίδα τῶν μεγίστων δωρεῶν προσδοκᾶσθαι παρ’ ὑμῶν. τῆς δ’ ἀναγκαίας μέν, ἀγνώμονος δὲ τύχης οὐχ ὡς δίκαιον ἦν, ἀλλ’ ὡς ἐβούλετο, κρινάσης τὸν ὑπὲρ τῆς τῶν Ἑλλήνων ἐλευθερίας ἀγῶνα,", "st": "63.2.5"}, {"sp": "N", "t": "ὃν ὑμεῖς ἠγωνίσασθε, οὐδ’ ἐν τοῖς μετὰ ταῦτα χρόνοις ἀπέστην τῆς εἰς ὑμᾶς εὐνοίας, οὐδ’ ἀντηλλαξάμην ἀντὶ ταύτης οὐδέν, οὐ χάριν, οὐκ ἐλπίδας, οὐ πλοῦτον, οὐ δυναστείαν, οὐκ ἀσφάλειαν. καίτοι πάντα ταῦθ’ ἑώρων ὑπάρχοντα τοῖς καθ’ ὑμῶν βουλομένοις πολιτεύεσθαι.", "st": "63.2.6"}, {"sp": "N", "t": "ὃ δέ, πολλῶν ὄντων καὶ μεγάλων ἐφ’ οἷς εἰκότως ἐπέρχεταί μοι παρρησιάζεσθαι, μέγιστον ἡγοῦμαι, οὐκ ὀκνήσω γράψαι πρὸς ὑμᾶς, ὅτι ἐν ἅπαντι τῷ αἰῶνι τῶν μνημονευομένων ἀνθρώπων δεινοτάτου γεγενημένου Φιλίππου καὶ δι’ ὁμιλίας πεῖσαι προσέχειν αὑτῷ τὸν νοῦν ὡς βούλοιτο, καὶ διαφθεῖραι χρήμασι τοὺς ἐν ἑκάστῃ τῶν Ἑλληνίδων πόλεων γνωρίμους, ἐγὼ μόνος οὐδετέρου τούτων ἡττήθην,", "st": "63.2.7"}, {"sp": "N", "t": "ὃ κοινὴν ὑμῖν φιλοτιμίαν φέρει, πολλὰ μὲν ἐντυχὼν Φιλίππῳ καὶ διαλεχθεὶς ἐφ’ οἷς ὑμεῖς ἐπέμπετε πρεσβεύοντά με, πολλῶν δ’ ἀποσχόμενος χρημάτων διδόντος ἐκείνου, ἃ τῶν συνειδότων ἔτι πολλοὶ ζῶσιν. οὓς τίνα γνώμην ἔχειν περὶ ὑμῶν εἰκός, λογίσασθε· τὸ γὰρ τῷ τοιούτῳ τοῦτον κεχρῆσθαι τὸν τρόπον ἐμοὶ μὲν ἂν εὖ οἶδ’ ὅτι συμφορὰ φανείη, κακία δ’ οὐδεμία, ὑμετέρα δ’ ἀγνωμοσύνη· ἣν τῷ μεταγνῶναι λύσαιτε.", "st": "63.2.8"}, {"sp": "N", "t": "πάντα τοίνυν τὰ προειρημέν’ ἐλάττω νομίζω τῆς συνεχοῦς καὶ καθ’ ἡμέραν πολιτείας, ἐν ᾗ παρεῖχον ἐμαυτὸν ἐγὼ πολιτευόμενον, οὐδεμιᾶς ὀργῆς οὐδὲ δυσμενείας οὐδ’ ἀδίκου πλεονεξίας οὔτε κοινῆς οὔτ’ ἰδίας προϊστάμενος, οὐδὲ συκοφαντήσας οὐδένα πώποτ’ οὔτε πολίτην οὔτε ξένον, οὐδὲ καθ’ ὑμῶν ἰδίᾳ δεινὸς ὤν, ἀλλ’ ὑπὲρ ὑμῶν, εἴ τι δεήσειεν, ἐξεταζόμενος δημοσίᾳ.", "st": "63.2.9"}, {"sp": "N", "t": "εἰδεῖεν δ’ ἂν οἱ πρεσβύτεροι, καὶ λέγειν τοῖς νεωτέροις ἐστὲ δίκαιοι τὴν πρὸς Πύθωνα τὸν Βυζάντιον ἐκκλησίαν, ὅτε τοὺς ἀπὸ τῶν Ἑλλήνων ἦλθε πρέσβεις ἔχων ὡς ἀδικοῦσαν δείξων τὴν πόλιν, ἀπῆλθε δὲ τἀναντία τούτων παθών, μόνου τῶν τότε ῥητόρων ἐξετάσαντος ἐμοῦ τὰ ὑπὲρ ὑμῶν δίκαια. καὶ ἐῶ πρεσβείας ὅσας ὑπὲρ ὑμῶν ἐπρέσβευσα, ἐν αἷς οὐδὲν ἠλαττώθητε πώποτ’ οὐδὲ καθ’ ἕν.", "st": "63.2.10"}, {"sp": "N", "t": "ἐπολιτευόμην γάρ, ὦ ἄνδρες Ἀθηναῖοι, οὐχ ὅπως ἀλλήλων ὑμεῖς περιγενήσεσθε σκοπῶν, οὐδ’ ἐφ’ ἑαυτὴν ἀκονῶν τὴν πόλιν, ἀλλ’ ἀφ’ ὧν δόξαν καὶ μεγαλοψυχίαν ὑμῖν ὑπάρξειν ἐνόμιζον. ἐφ’ οἷς ἅπασι μέν, μάλιστα δὲ τοῖς νέοις, ἄγασθαι προσήκει, καὶ σκοπεῖν μὴ μόνον τὸν διακονήσοντα πρὸς χάριν πάντ’ ἐν τῇ πολιτείᾳ ʽτούτου μὲν γὰρ οὐδέποτ’ ἔστ’ ἀπορῆσαἰ, ἀλλὰ καὶ τὸν ἐπ’ εὐνοίᾳ περὶ ὧν ἂν ἀγνοῆτ’ ἐπιτιμήσοντα.", "st": "63.2.11"}, {"sp": "N", "t": "ἔτι τοίνυν παραλείπω πολλά, ἐφ’ οἷς ἕτερος καὶ μηδὲν ἄλλο χρήσιμος γεγονὼς δικαίως ἂν ἠξίου τυγχάνειν σωτηρίας, χορηγίας καὶ τριηραρχίας καὶ χρημάτων ἐπιδόσεις ἐν πᾶσι τοῖς καιροῖς· ἐν οἷς ἐγὼ φανήσομαι οὐ μόνον αὐτὸς ἐξητασμένος πρῶτος, ἀλλὰ καὶ τοὺς ἄλλους παρακεκληκώς. ὧν ἕκαστον, ὦ ἄνδρες Ἀθηναῖοι, λογίσασθε, ὡς ἀνάξιόν ἐστι τῆς περιεστηκυίας νῦν ἐμοὶ συμφορᾶς.", "st": "63.2.12"}, {"sp": "N", "t": "ἀφθόνων δ’ ὄντων, ἀπορῶ τί πρῶτον ὀδύρωμαι τῶν παρόντων κακῶν. πότερον τὴν ἡλικίαν ἐν ᾗ φυγῆς ἐπικινδύνου πειρᾶσθαι παρ’ ἔθος καὶ παρὰ τὴν ἀξίαν ἀναγκάζομαι; ἢ τὴν αἰσχύνην ἐφ’ ᾗ κατ’ οὐδέν’ ἔλεγχον οὐδ’ ἀπόδειξιν ἁλοὺς ἀπόλωλα; ἢ τὰς ἐλπίδας ὧν διαμαρτών, ὧν ἑτέροις προσῆκε κεκληρονόμηκα κακῶν;", "st": "63.2.13"}, {"sp": "N", "t": "οὔτ’ ἐφ’ οἷς ἐπολιτεύθην πρότερον δίκην ὀφείλων δοῦναι, οὔτε τῶν ἐφ’ οἷς ἐκρινόμην ἐξελεγχθέντων· οὔτε γὰρ ἔγωγε τῶν Ἁρπάλου φίλων φανήσομαι γεγονώς, τῶν τε γραφέντων περὶ Ἁρπάλου μόνα τὰ ἐμοὶ πεπραγμέν’ ἀνέγκλητον πεποίηκε τὴν πόλιν. ἐξ ὧν πάντων δῆλόν ἐστιν ὅτι καιρῷ τινὶ ληφθεὶς καὶ οὐκ ἀδικήματι, τῇ πρὸς ἅπαντας τοὺς ἐν ταῖς αἰτίαις ὀργῇ περιπέπτωκ’ ἀδίκως τῇ πρῶτος εἰσιέναι.", "st": "63.2.14"}, {"sp": "N", "t": "ἐπεὶ τί τῶν δικαίων οὐκ εἶπον ἐγὼ τῶν σεσῳκότων τοὺς ὕστερον κρινομένους; ἢ τίν’ ἔλεγχον εἶπεν ἡ βουλὴ κατ’ ἐμοῦ; ἢ τίνα νῦν ἂν εἰπεῖν ἔχοι; οὐ γὰρ ἔστιν οὐδείς· τὰ γὰρ μὴ γενόμεν’ οὐκ ἔστι ποιῆσαι γεγενῆσθαι. ἀλλὰ περὶ μὲν τούτων παύομαι, πόλλ’ ⟨ἂν⟩ γράφειν ἔχων· τὸ γὰρ μηδὲν ἐμαυτῷ συνειδέναι πεῖράν μοι δέδωκεν εἰς μὲν ὠφέλειαν ἀσθενὲς ὄν, εἰς δὲ τὸ μᾶλλον λυπεῖσθαι πάντων ὀδυνηρότατον.", "st": "63.2.15"}, {"sp": "N", "t": "ἐπειδὴ δὲ καλῶς ποιοῦντες πᾶσι τοῖς ἐν ταῖς αἰτίαις διήλλαχθε, κἀμοὶ διαλλάγητ’, ὦ ἄνδρες Ἀθηναῖοι· οὔτε γὰρ ἠδίκηχ’ ὑμᾶς οὐδέν, ὡς ἴστωσαν οἱ θεοὶ καὶ ἥρωες (μαρτυρεῖ δέ μοι πᾶς ὁ πρόσθεν παρεληλυθὼς χρόνος, ὃς δικαιότερον ἂν πιστεύοιθ’ ὑφ’ ὑμῶν τῆς ἀνελέγκτου νῦν ἐπενεχθείσης αἰτίας), οὔτ’ ἐγὼ χείριστος οὐδ’ ἀπιστότατος φανήσομαι τῶν διαβληθέντων.", "st": "63.2.16"}, {"sp": "N", "t": "καὶ μὴν τό γ’ ἀπελθεῖν οὐκ ἂν εἰκότως ὀργὴν πρός με ποιήσειεν· οὐ γὰρ ἀπεγνωκὼς ὑμᾶς οὐδ’ ἑτέρωσε βλέπων οὐδαμοῖ μετέστην, ἀλλὰ πρῶτον μὲν τοὔνειδος τῆς εἱρκτῆς χαλεπῶς τῷ λογισμῷ φέρων, εἶτα διὰ τὴν ἡλικίαν οὐκ ἂν οἷός τ’ ὢν τῷ σώματι τὴν κακοπαθίαν ὑπενεγκεῖν. ἔτι δ’ οὐδ’ ὑμᾶς ἐνόμιζον ἀβουλεῖν ἔξω με προπηλακισμοῦ γενέσθαι, ὃς οὐδὲν ὑμᾶς ὠφελῶν ἔμ’ ἀπώλλυεν.", "st": "63.2.17"}, {"sp": "N", "t": "ἐπεὶ ὅτι γ’ ὑμῖν προσεῖχον τὸν νοῦν καὶ οὐδέσιν ἄλλοις, πόλλ’ ἂν ἴδοιτε σημεῖα. εἴς τε γὰρ πόλιν ἦλθον, οὐκ ἐν ᾗ μέγιστα πράξειν αὐτὸς ἔμελλον, ἀλλ’ εἰς ἣν καὶ τοὺς προγόνους ἐλθόντας ᾔδειν, ὅθ’ ὁ πρὸς τὸν Πέρσην κατελάμβανεν αὐτοὺς κίνδυνος, καὶ παρ’ ᾗ πλείστην εὔνοιαν ὑπάρχουσαν ὑμῖν ἠπιστάμην (ἔστι δ’ ἡ Τροζηνίων αὕτη,", "st": "63.2.18"}, {"sp": "N", "t": "ᾗ μάλιστα μὲν οἱ θεοὶ καὶ τῆς πρὸς ὑμᾶς εὐνοίας ἕνεκα καὶ τῆς εἰς ἔμ’ εὐεργεσίας εὖνοι πάντες εἴησαν, εἶτα κἀγὼ σωθεὶς ὑφ’ ὑμῶν δυνηθείην ἀποδοῦναι χάριτας)· ἔν τε ταύτῃ τινῶν, ὡς ἐμοὶ χαριζομένων, ἐπιτιμᾶν ὑμῖν τι πειρωμένων τῇ κατ’ ἔμ’ ἀγνοίᾳ, ἐγὼ πᾶσαν εὐφημίαν, ὥσπερ ἐμοὶ προσῆκε, παρειχόμην· ἐξ ὧν καὶ μάλιστα νομίζω πάντας ἀγασθέντας μου δημοσίᾳ τιμῆσαι.", "st": "63.2.19"}, {"sp": "N", "t": "ὁρῶν δὲ τὴν μὲν εὔνοιαν τῶν ἀνδρῶν μεγάλην, τὴν δ’ εἰς τὸ παρὸν δύναμιν καταδεεστέραν, μετελθὼν εἰς τὸ τοῦ Ποσειδῶνος ἱερὸν ἐν Καλαυρείᾳ κάθημαι, οὐ μόνον τῆς ἀσφαλείας ἕνεκα, ἣν διὰ τὸν θεὸν ἐλπίζω μοι ὑπάρχειν ʽοὐ γὰρ εὖ οἶδά γε· ἃ γὰρ ἐφ’ ἑτέροις ἐστὶν ὡς ἂν βούλωνται πρᾶξαι, λεπτὴν καὶ ἄδηλον ἔχει τῷ κινδυνεύοντι τὴν ἀσφάλειαν̓, ἀλλ’ ὅτι καὶ τὴν πατρίδ’ ἐντεῦθεν ἑκάστης ἡμέρας ἀφορῶ, εἰς ἣν τοσαύτην εὔνοιαν ἐμαυτῷ σύνοιδα, ὅσης παρ’ ὑμῶν εὔχομαι τυχεῖν.", "st": "63.2.20"}, {"sp": "N", "t": "ὅπως οὖν, ὦ ἄνδρες Ἀθηναῖοι, μηκέτι πλείω χρόνον τοῖς παροῦσι κακοῖς συνέχωμαι, ψηφίσασθέ μοι ταῦθ’ ἃ καὶ ἄλλοις τισὶν ἤδη, ἵνα μήτ’ ἀνάξιον ὑμῶν μηδέν μοι συμβῇ, μήθ’ ἱκέτης ἑτέρων ἀναγκασθῶ γενέσθαι· οὐδὲ γὰρ ὑμῖν τοῦτο γένοιτ’ ἂν καλόν. ἐπεὶ εἴ γέ μοι τὰ πρὸς ὑμᾶς ἀδιάλλακτα ὑπάρχει, τεθνάναι μοι κρεῖττον ἦν.", "st": "63.2.21"}, {"sp": "N", "t": "εἰκότως δ’ ἄν μοι πιστεύοιτε ταύτην τὴν διάνοιαν ἔχειν καὶ μὴ νῦν μάτην θρασύνεσθαι· καὶ γὰρ ἐμαυτοῦ κυρίους ὑμᾶς ἐποίησα καὶ οὐκ ἔφυγον τὸν ἀγῶνα, ἵνα μήτε προδῶ τὴν ἀλήθειαν μήτ’ ἄκυρος ὑμῶν ἐμοῦ μηδεὶς γένηται, ἀλλ’ ὅ τι βούλοισθε, τοῦτο χρήσαισθε· παρ’ ὧν γὰρ ἁπάντων καλῶν κἀγαθῶν ἔτυχον, τούτους ᾠόμην δεῖν ἔχειν καὶ ἁμαρτεῖν, εἰ βούλοιντο, εἰς ἐμέ.", "st": "63.2.22"}, {"sp": "N", "t": "ἐπειδὴ δὲ καλῶς ποιοῦσ’ ἡ δικαία τύχη τῆς ἀδίκου κρατήσασα δὶς περὶ τῶν αὐτῶν ἀπέδωκεν ὑμῖν βουλεύσασθαι τῷ μηδὲν ἀνήκεστον ἐψηφίσθαι περὶ ἐμοῦ, σῴσατέ μ’, ὦ ἄνδρες Ἀθηναῖοι, καὶ ψηφίσασθε καὶ ὑμῶν αὐτῶν ἄξια καὶ ἐμοῦ.", "st": "63.2.23"}, {"sp": "N", "t": "ἐπ’ οὐδενὶ γὰρ τῶν πεπραγμένων ἠδικηκότα μ’ εὑρήσετε, οὐδ’ ἐπιτήδειον ἄτιμον εἶναι οὐδ’ ἀπολωλέναι, ἀλλὰ καὶ εὔνουν τῷ πλήθει τῷ ὑμετέρῳ τοῖς μάλισθ’ ὁμοίως, ἵνα μηδὲν ἐπίφθονον γράψω, καὶ πλεῖστα πεπραγματευμένον τῶν νυνὶ ζώντων ὑπὲρ ὑμῶν, καὶ μέγισθ’ ὑπάρχοντά μοι κατ’ ἐμαυτὸν σύμβολ’ εὐνοίας πρὸς ὑμᾶς.", "st": "63.2.24"}, {"sp": "N", "t": "μηδεὶς δ’ ὑμῶν ἡγείσθω μ’, ὦ ἄνδρες Ἀθηναῖοι, μήτ’ ἀνανδρίᾳ μήτ’ ἄλλῃ προφάσει φαύλῃ μηδεμιᾷ παρ’ ὅλην τὴν ἐπιστολὴν ὀδύρεσθαι. ἀλλὰ τοῖς παροῦσιν ἕκαστος ἀφθόνως χρῆται, ἐμοὶ δὲ ταῦτα νῦν πάρεστιν, ὡς μήποτ’ ὤφελεν, λῦπαι καὶ δάκρυα καὶ τῆς πατρίδος καὶ ὑμῶν πόθος καὶ ὧν πέπονθα λογισμός, ἃ πάντα ποιεῖ μ’ ὀδύρεσθαι· ἃ ἐπισκοποῦντες δικαίως, ⟨ὡς⟩ ἐν οὐδενὶ τῶν πεπολιτευμένων ὑπὲρ ὑμῶν, οὔτε μαλακίαν οὔτ’ ἀνανδρίαν προσοῦσαν εὑρήσετέ μοι.", "st": "63.2.25"}, {"sp": "N", "t": "πρὸς μὲν δὴ πάντας ὑμᾶς τοσαῦτα· ἰδίᾳ δὲ τοῖς ἐμοὶ προσκρούουσιν ἐναντίον ὑμῶν βούλομαι διαλεχθῆναι. ὅσα μὲν γὰρ τοῖς ὑφ’ ὑμῶν ἀγνοηθεῖσιν ὑπηρετοῦντες ἐποίουν, ἔστω δι’ ὑμᾶς αὐτοῖς πεπρᾶχθαι, καὶ οὐδὲν ἐγκαλῶ. ἐπειδὴ δ’ ἐγνώκαθ’ ὑμεῖς οἷα ταῦτ’ ἐστίν, ἐὰν μέν, ὥσπερ ὑπὲρ τῶν λοιπῶν ἐῶσι, καὶ ἐμοὶ συγχωρήσωσι, καλῶς ποιήσουσιν· ἐὰν δ’ ἐπηρεάζειν ἐγχειρῶσιν, ὑμᾶς ἀξιῶ μοι βοηθεῖν ἅπαντας, καὶ μὴ κυριωτέραν τὴν τούτων ἔχθραν τῆς παρ’ ὑμῶν χάριτός μοι γενέσθαι. εὐτυχεῖτε.", "st": "63.2.26"}, {"sp": "SEC", "t": "3. Περὶ τῶν Λυκούργου παιδῶν", "st": "63.3"}, {"sp": "N", "t": "Δημοσθένης τῇ βουλῇ καὶ τῷ δημῷ χαίρειν. περὶ μὲν τῶν κατ’ ἐμαυτόν, ἅ μοι παρ’ ὑμῶν ἐνόμιζον δίκαιον εἶναι γενέσθαι, τὴν προτέραν ἐπιστολὴν ἔπεμψα πρὸς ὑμᾶς· ὑπὲρ ὧν, ὅταν ὑμῖν δοκῇ, τότε συγχωρήσετε. περὶ δ’ ὧν νῦν ἐπέσταλκα, βουλοίμην ἂν ὑμᾶς μὴ παριδεῖν, μηδὲ πρὸς φιλονικίαν, ἀλλὰ πρὸς τὸ δίκαιον ἀκοῦσαι. συμβαίνει γάρ μοι, καίπερ ἐκποδὼν διατρίβοντι, πολλῶν ἀκούειν ἐπιτιμώντων ὑμῖν τοῖς περὶ τοὺς Λυκούργου παῖδας γιγνομένοις.", "st": "63.3.1"}, {"sp": "N", "t": "ἐπέστειλα μὲν οὖν ἂν τὴν ἐπιστολὴν καὶ τῶν ἐκείνῳ ζῶντι πεπραγμένων ἕνεκα, ὧν ὁμοίως ἐμοὶ πάντες ἂν αὐτῷ δικαίως ἔχοιτε χάριν, εἰ τὰ προσήκοντα βούλοισθε ποιεῖν. ἐκεῖνος γὰρ αὑτὸν ἐν τῷ περὶ τὴν διοίκησιν μέρει τάξας τῆς πολιτείας τὸ κατ’ ἀρχάς, καὶ περὶ τῶν Ἑλληνικῶν καὶ συμμαχικῶν οὐδὲν εἰωθὼς γράφειν, ὅτε καὶ τῶν δημοτικῶν εἶναι προσποιουμένων οἱ πολλοὶ κατέλειπον ὑμᾶς, τότε ταῖς τοῦ δήμου προαιρέσεσιν προσένειμεν ἑαυτόν,", "st": "63.3.2"}, {"sp": "N", "t": "οὐχ ὅτι δωρεὰς καὶ προσόδους ἐκ τούτων ὑπῆρχε λαμβάνειν ʽἀπὸ γὰρ τῶν ἐναντίων πάντα τὰ τοιαῦτ’ ἐγίγνετὀ, οὐδ’ ὅτι ταύτην ἀσφαλεστέραν τὴν προαίρεσιν οὖσαν ἑώρα ʽπολλοὺς γὰρ καὶ προδήλους εἶχε κινδύνους, οὓς ἀναγκαῖον ἦν ὑπομεῖναι τὸν ὑπὲρ τοῦ δήμου λέγειν προαιρούμενον̓, ἀλλ’ ὅτι δημοτικὸς καὶ φύσει χρηστὸς ἀνὴρ ἦν.", "st": "63.3.3"}, {"sp": "N", "t": "καίτοι παρὼν ἑώρα τοὺς μὲν βοηθήσαντας ἂν τῷ δήμῳ ἀσθενεῖς ἐπὶ τοῖς συμβεβηκόσιν ὄντας, τοὺς δὲ τἀναντία πράττοντας κατὰ πάντ’ ἐρρωμένους. ἀλλ’ ὅμως οὐδὲν ἧττον ἐκεῖνος εἵλεθ’ ἃ συμφέρειν ἡγεῖτο τῷ δήμῳ, καὶ μετὰ ταῦτ’ ἀόκνως καὶ λέγων καὶ πράττων ἃ προσῆκεν ἦν φανερός, ἐφ’ οἷς εὐθὺς ἐξῃτεῖτο, ὡς ἅπαντες ἴσασιν.", "st": "63.3.4"}, {"sp": "N", "t": "ἐπέστειλα μὲν οὖν ἄν, ὥσπερ εἶπον ἐν ἀρχῇ, καὶ διὰ τὴν ἐκείνου χάριν· οὐ μὴν ἀλλὰ καὶ ὑμῖν νομίζων συμφέρειν τὰς παρὰ τοῖς ἔξω γιγνομένας ἐπιτιμήσεις εἰδέναι, πολλῷ προθυμότερον πρὸς τὸ πέμψαι τὴν ἐπιστολὴν ἔσχον. παραιτοῦμαι δὲ τοὺς ἰδίᾳ πρὸς ἐκεῖνον ἔχοντας δυσκόλως, ὑπομεῖναι τἀληθῆ καὶ τὰ δίκαι’ ἀκούειν ὑπὲρ αὐτοῦ. εὖ γὰρ ἴστ’, ὦ ἄνδρες Ἀθηναῖοι, ὅτι νῦν ἐκ τῶν περὶ τοὺς παῖδας αὐτοῦ γεγενημένων φαύλην δόξαν ἡ πόλις λαμβάνει.", "st": "63.3.5"}, {"sp": "N", "t": "οὐδεὶς γὰρ τῶν Ἑλλήνων ἀγνοεῖ ὅτι ζῶντα Λυκοῦργον ἐτιμᾶθ’ ὑμεῖς εἰς ὑπερβολήν, καὶ πολλῶν αἰτιῶν ἐπενεχθεισῶν ὑπὸ τῶν φθονούντων αὐτῷ οὐδεμίαν πώποθ’ ηὕρετ’ ἀληθῆ, οὕτω δ’ ἐπιστεύετ’ αὐτῷ καὶ δημοτικὸν παρὰ πάντας ἡγεῖσθε, ὥστε πολλὰ τῶν δικαίων ἐν τῷ φῆσαι Λυκοῦργον ἐκρίνετε καὶ τοῦθ’ ὑμῖν ἐξήρκει· οὐ γὰρ ἂν ἦν τοιοῦτον μὴ δοκοῦν ὑμῖν.", "st": "63.3.6"}, {"sp": "N", "t": "νῦν τοίνυν ἅπαντες ἀκούοντες τοὺς υἱεῖς αὐτοῦ δεδέσθαι τὸν μὲν τεθνεῶτ’ ἐλεοῦσιν, τοῖς παισὶν δ’ ὡς ἀνάξια πάσχουσιν συνάχθονται, ὑμῖν δ’ ἐπιτιμῶσιν πικρῶς, ὡς οὐκ ἂν τολμήσαιμι γράφειν ἐγώ· ἃ γὰρ ἄχθομαι τοῖς λέγουσι καὶ ἀντιλέγω καθ’ ὅσον δύναμαι βοηθῶν ὑμῖν, ταῦτ’ ἄχρι μὲν τοῦ δῆλον ὑμῖν ποιῆσαι ὅτι πολλοὶ μέμφονται, συμφέρειν ὑμῖν νομίζων εἰδέναι, γέγραφα, ἀκριβῶς δὲ διεξιέναι δυσχερὲς κρίνω.", "st": "63.3.7"}, {"sp": "N", "t": "ὅσα μέντοι λοιδορίας χωρίς ἐστιν ὧν λέγουσίν τινες, καὶ ἀκηκοέναι συμφέρειν ὑμῖν ἡγοῦμαι, ταῦτα δηλώσω. οὐδεὶς γὰρ ὑπείληφεν ὡς ἄρ’ ἠγνοήκατε καὶ διεψεύσθητε τῆς ἀληθείας περὶ αὐτοῦ Λυκούργου. τό τε γὰρ τοῦ χρόνου πλῆθος, ὃν ἐξεταζόμενος οὐδὲν πώποθ’ ηὑρέθη περὶ ὑμᾶς οὔτε φρονῶν οὔτε ποιῶν ἄδικον, καὶ τὸ μηδέν’ ἀνθρώπων εἰς μηδὲν τῶν ἄλλων ἀναισθησίαν ὑμῶν καταγνῶναι, εἰκότως ἀναιρεῖ τὴν ὑπὲρ τῆς ἀγνοίας σκῆψιν.", "st": "63.3.8"}, {"sp": "N", "t": "λείπεται τοίνυν ὃ πάντες ἂν εἶναι φαύλων ἀνθρώπων [ἔργον] φήσαιεν, ὅσον ἂν χρῆσθε χρόνον, τοσοῦτον ἑκάστου φροντίζειν δοκεῖν, μετὰ ταῦτα δὲ μηδέν’ ἔχειν λόγον. εἰς τί γὰρ τῶν ἄλλων χρὴ προσδοκᾶν τῷ τετελευτηκότι τὴν παρ’ ὑμῶν ἔσεσθαι χάριν, ὅταν εἰς τοὺς παῖδας καὶ τὴν εὐδοξίαν τἀναντί’ ὁρᾷ τις γιγνόμενα, ὧν μόνων καὶ τελευτῶσι πᾶσιν ὅπως ἕξει καλῶς μέλει;", "st": "63.3.9"}, {"sp": "N", "t": "καὶ μὴν οὐδὲ χρημάτων ποιεῖν ἕνεκα ταῦτα δοκεῖν τῶν καλῶν [κἀγαθῶν] ἐστιν. οὔτε γὰρ τῆς μεγαλοψυχίας οὔτε τῆς ἄλλης προαιρέσεως τῆς ὑμετέρας ἀκόλουθον ἂν φανείη. εἰ γὰρ ὑμᾶς λύσασθαι παρ’ ἑτέρων ἔδει δόντας ἐκ τῶν προσιόντων τὰ χρήματα ταῦτα, πάντας ἂν ἡγοῦμαι προθύμους εἶναι· τίμημα δ’ ὁρῶν ὀκνοῦντας ἀφεῖναι, ὃ λόγῳ καὶ φθόνῳ γέγονεν, οὐκ ἔχω τί καταγνῶ, εἰ μὴ ὅλως πικρῶς καὶ ταραχωδῶς ἔχειν πρὸς τοὺς δημοτικοὺς ὡρμήκατε. εἰ δὲ τοῦτ’ ἔστιν, οὔτ’ ὀρθῶς οὔτε συμφερόντως [βουλεύεσθαι] ἐγνώκατε.", "st": "63.3.10"}, {"sp": "N", "t": "θαυμάζω δ’ εἰ μηδεὶς ὑμῶν ἐννοεῖ, ὅτι τῶν αἰσχρῶν ἐστιν τὸν δῆμον τὸν Ἀθηναίων, συνέσει καὶ παιδείᾳ πάντων προέχειν δοκοῦντα, ὃς καὶ τοῖς ἀτυχήσασιν ἀεὶ κοινὴν ἔχει καταφυγήν, ἀγνωμονέστερον φαίνεσθαι Φιλίππου, ὃς ἀνουθέτητος ὢν εἰκότως,", "st": "63.3.11"}, {"sp": "N", "t": "τραφείς γ’ ἐν ἐξουσίᾳ, ὅμως ᾤετο δεῖν, ἡνίκ’ ηὐτύχησεν μάλιστα, τότ’ ἀνθρωπινώτατα πράττων φαίνεσθαι, καὶ τοὺς παραταξαμένους, πρὸς οὓς περὶ τῶν ὅλων διεκινδύνευσεν, οὐκ ἐτόλμησεν δῆσαι τὸ τίνων καὶ τίνες εἰσὶν ἐξετάσας· οὐ γὰρ ὡς ἔοικεν ὁμοίως τῶν παρ’ ὑμῖν ῥητόρων ἐνίοις οὔτε δίκαι’ ἂν εἶναι πρὸς ἅπαντας ταὔτ’ οὔτε κάλ’ ἡγεῖτο, ἀλλὰ τὴν τῆς ἀξίας προσθήκην συλλογιζόμενος τὰ τοιαῦτ’ ἐπέκρινεν.", "st": "63.3.12"}, {"sp": "N", "t": "ὑμεῖς δέ, ὄντες Ἀθηναῖοι καὶ ἐν παρρησίᾳ ζῶντες ἣ καὶ τοὺς ἀναισθήτους ἀνεκτοὺς ποιεῖν δοκεῖ δύνασθαι, πρῶτον μέν, ὃ πάντων ἀγνωμονέστατόν ἐστιν, ὑπὲρ ὧν τὸν πατέρ’ αἰτιῶνταί τινες, τοὺς υἱεῖς δεδέκατε, εἶτα τὸ ταῦτα ποιεῖν ἴσον εἶναί φατε, ὥσπερ ὑπὲρ σταθμῶν ἢ μέτρων τὸ ἴσον σκοπούμενοι, ἀλλ’ οὐχ ὑπὲρ ἀνδρῶν προαιρέσεως καὶ πολιτείας βουλευόμενοι,", "st": "63.3.13"}, {"sp": "N", "t": "ἐν οἷς ἐξεταζομένοις εἰ μὲν χρηστὰ καὶ δημοτικὰ καὶ ἐπ’ εὐνοίᾳ τὰ Λυκούργῳ πεπραγμένα φαίνεται, μηδενὸς κακοῦ ἀλλὰ καὶ πάντων τῶν ἀγαθῶν τοὺς παῖδας αὐτοῦ δίκαιόν ἐστιν τυγχάνειν παρ’ ὑμῶν· εἰ δὲ τἀναντία τούτων, ἐκεῖνον, ὅτ’ ἔζη, ἔδει δίκην διδόναι, τούτους δὲ μηδ’ οὕτως, ἐφ’ οἷς ἐκείνῳ τις ἐγκαλεῖ, τυγχάνειν ὀργῆς· πᾶσι γὰρ πάντων τῶν ἁμαρτημάτων ὅρος ἐστὶ τελευτή.", "st": "63.3.14"}, {"sp": "N", "t": "ἐπεὶ εἴ γ’ οὕτως ἕξετε, ὥσθ’ οἱ μὲν ἀχθεσθέντες τι τοῖς ὑπὲρ τοῦ δήμου πολιτευομένοις μηδὲ πρὸς τελευτήσαντας διαλλαγήσονται, ἀλλὰ καὶ τοῖς παισὶ τὴν ἔχθραν διαφυλάξουσιν, ὁ δὲ δῆμος, ᾧ συναγωνίζεται τῶν δημοτικῶν ἕκαστος, μέχρι τοῦ παρόντι χρῆσθαι μνημονεύσει τὰς χάριτας, μετὰ ταῦτα δὲ μηδὲν φροντιεῖ, οὐδὲν ἀθλιώτερον ἔσται τοῦ τὴν ὑπὲρ τοῦ δήμου τάξιν αἱρεῖσθαι.", "st": "63.3.15"}, {"sp": "N", "t": "εἰ δὲ Μοιροκλῆς ἀποκρίνεται ταῦτα μὲν σοφώτερ’ ἢ καθ’ ἑαυτὸν εἶναι, ἵνα δὲ μὴ ἀποδρῶσιν, αὐτὸς αὐτοὺς δῆσαι, ἐρωτήσατ’ αὐτόν, ἡνίκα Ταυρέας καὶ Πάταικος καὶ Ἀριστογείτων καὶ αὐτὸς εἰς τὸ δεσμωτήριον παραδοθέντες οὐ μόνον οὐκ ἐδέδεντο, ἀλλὰ καὶ ἐδημηγόρουν, τί δήποτ’ οὐχ ἑώρα τὰ δίκαια ταῦτα.", "st": "63.3.16"}, {"sp": "N", "t": "εἰ δὲ μὴ φήσει τότ’ ἄρχειν, οὐδὲ λέγειν ἔκ γε τῶν νόμων αὐτῷ προσῆκεν. ὥστε πῶς ἴσον ἐστὶν τοὺς μὲν ἄρχειν, οἷς μηδὲ λέγειν ἔξεστιν, τοὺς δὲ δεδέσθαι, ὧν πολλὰ χρήσιμος ἦν ὑμῖν ὁ πατήρ; ἐγὼ μὲν οὐκ ἔχω συλλογίσασθαι,", "st": "63.3.17"}, {"sp": "N", "t": "εἰ μὴ τοῦτο δεῖξαι δημοσίᾳ βούλεσθε, ὅτι βδελυρία καὶ ἀναίδεια καὶ προαίρεσις πονηρίας ἐν τῇ πόλει ἰσχύει καὶ διασωθῆναι πλείω προσδοκίαν ἔχει, κἄν τι συμβῇ χαλεπὸν τοῖς τοιούτοις, ἀπόλυσις γίγνεται, ἐν δὲ προαιρέσει χρηστῇ καὶ βίῳ σώφρονι καὶ δημοτικῷ προελέσθαι ζῆν σφαλερόν, κἄν τι γένηται πταῖσμα, ἄφυκτον ἔσται.", "st": "63.3.18"}, {"sp": "N", "t": "ἔτι τοίνυν τὸ μὲν μὴ δίκαιον εἶναι τὴν ἐναντίαν δόξαν ἔχειν ὧς περὶ ζῶντος εἴχετ’ ἐκείνου, καὶ τὸ τῶν τετελευτηκότων ἢ τῶν παρόντων πλείω ποιεῖσθαι λόγον δίκαιον εἶναι, καὶ πάντα τὰ τοιαῦτα, ἐάσω· παρὰ γὰρ πᾶσιν ὁμολογεῖσθαι ταῦθ’ ὑπείληφα· ὅσοις μέντοι πατρικὰς εὐεργεσίας ἀπεμνημονεύσατε τῶν ἄλλων, ἡδέως ἂν ἴδοιμ’ ὑμᾶς ἀναμνησθέντας, οἷον τοῖς Ἀριστείδου καὶ τοῖς Θρασυβούλου καὶ τοῖς Ἀρχίνου καὶ πολλῶν ἑτέρων ἀπογόνοις.", "st": "63.3.19"}, {"sp": "N", "t": "οὐχ ὡς ἐπιτιμῶν δὲ ταῦτα παρήνεγκα. τοσούτου γὰρ δέω τοῦτο ποιεῖν ὥστε συμφέρειν μάλιστα τῇ πόλει τὰ τοιαῦτα κρίνω· προκαλεῖσθε γὰρ πάντας ἐκ τούτων δημοτικοὺς εἶναι, ὁρῶντας ὅτι κἂν ἐν τῷ καθ’ ἑαυτοὺς βίῳ ταῖς προσηκούσαις αὐτῶν τιμαῖς ὁ φθόνος ἀντιστῇ, τοῖς γε παισὶν ὑπάρξει τὰ προσήκοντα παρ’ ὑμῶν κομίσασθαι.", "st": "63.3.20"}, {"sp": "N", "t": "πῶς οὖν οὐκ ἄτοπον, μᾶλλον δὲ καὶ αἰσχρόν, τῶν μὲν ἄλλων τισί, καὶ παλαιῶν ὄντων τῶν χρόνων καθ’ οὓς ἐγένοντο χρήσιμοι, καὶ δι’ ὧν ἀκούετε τὰς εὐεργεσίας, οὐκ ἐξ ὧν ἑοράκαθ’ ὑπειληφότας, ὅμως τὴν δικαίαν εὔνοιαν διασῴζειν, Λυκούργῳ δ’ οὕτως ὑπογύου καὶ τῆς πολιτείας καὶ τῆς τελευτῆς γεγονυίας, μηδ’ εἰς ἃ καὶ τοῖς ἀγνῶσιν καὶ ὑφ’ ὧν ἀδικοῖσθ’ ἕτοιμοι τὸν ἄλλον ἦτε χρόνον,", "st": "63.3.21"}, {"sp": "N", "t": "εἰς ἔλεον καὶ φιλανθρωπίαν, μηδ’ εἰς ταῦθ’ ὑμᾶς αὐτοὺς ὁμοίους παρέχειν, καὶ ταῦτ’ εἰς τοὺς παῖδας αὐτοῦ γιγνομένης τῆς τιμωρίας, οὓς κἂν ἐχθρός, εἴπερ μέτριος εἴη καὶ λογισμὸν ἔχων, ἐλεήσαι;", "st": "63.3.22"}, {"sp": "N", "t": "θαυμάζω τοίνυν καὶ τοῦτ’ εἴ τις ὑμῶν ἀγνοεῖ, ὡς οὐδὲ τοῦτο συμφέρει τῇ πολιτείᾳ φανερὸν γιγνόμενον, ὅτι τοῖς μὲν ἄλλην τινὰ κτησαμένοις φιλίαν καὶ κατορθοῦσιν ἐν πᾶσιν πλεονεκτεῖν ὑπάρχει, κἂν ἀτυχήσωσίν τι, ῥᾳδίους εἶναι τὰς λύσεις, τοῖς δ’ εἰς τὸν δῆμον ἀναρτήσασιν ἑαυτοὺς οὐ μόνον κατὰ τἄλλ’ ἔλαττον ἔχειν ὑπάρξει, ἀλλὰ καὶ τὰς συμφορὰς βεβαίους τούτοις μόνοις τῶν ἄλλων μένειν. ἀλλὰ μὴν ὅτι τοῦθ’ οὕτως γίγνεται ῥᾴδιον δεῖξαι.", "st": "63.3.23"}, {"sp": "N", "t": "τίς γὰρ οὐκ οἶδεν ὑμῶν Λάχητι τῷ Μελανώπου ἁλῶναι μὲν ὁμοίως ἐν δικαστηρίῳ συμβὰν ὡς καὶ νῦν τοῖς Λυκούργου παισίν, ἀφεθῆναι δὲ πᾶν τὸ ὄφλημ’ ἐπιστείλαντος Ἀλεξάνδρου; καὶ πάλιν Μνησιβούλῳ τῷ Ἀχαρνεῖ ἁλῶναι μὲν ὁμοίως καταγνόντος αὐτοῦ τοῦ δικαστηρίου ὥσπερ καὶ τῶν Λυκούργου παίδων, ἀφεῖσθαι δὲ καλῶς ποιοῦντι;", "st": "63.3.24"}, {"sp": "N", "t": "ἄξιος γὰρ ἁνήρ. καὶ οὐδεὶς ἐπὶ τούτοις τοὺς νόμους ἔφη καταλύεσθαι τῶν νῦν βοώντων. εἰκότως· οὐδὲ γὰρ κατελύοντο, εἴπερ ἅπαντες οἱ νόμοι τῶν δικαίων εἵνεκα καὶ σωτηρίας τῶν χρηστῶν ἀνθρώπων τίθενται, καὶ μήτ’ ἀϊδίους τοῖς ἀτυχήσασι καθιστάναι τὰς συμφορὰς συμφέρει, μήτ’ ἀχαρίστους ὄντας φαίνεσθαι.", "st": "63.3.25"}, {"sp": "N", "t": "ἀλλὰ μὴν εἴ γε ταῦθ’ οὕτως, ὥσπερ ἂν φήσαιμεν, ἔχειν συμφέρει, οὐ μόνον τοὺς νόμους οὐ κατελύετε, ἡνίκ’ ἐκείνους ἀφίετε, ἀλλὰ καὶ τοὺς λογισμοὺς ἐσῴζετε τῶν τοὺς νόμους θεμένων ἀνθρώπων, Λάχητα μὲν πρὸς χάριν δεηθέντος Ἀλεξάνδρου ἀφέντες, Μνησίβουλον δὲ τῇ τοῦ βίου σωφροσύνῃ σῴσαντες.", "st": "63.3.26"}, {"sp": "N", "t": "μὴ τοίνυν τὸ κτήσασθαί τιν’ ἔξωθεν φιλίαν λυσιτελέστερον δείκνυτ’ ἢ τὸ τῷ δήμῳ παρακαταθέσθαι ἑαυτόν, μηδὲ τὸ τῶν ἀγνώτων εἶναι κρεῖττον ἢ τοῖς πολλοῖς ὑμῖν τὰ συμφέροντα πολιτευόμενον γιγνώσκεσθαι. τὸ μὲν γὰρ πᾶσιν ἀρέσκειν τὸν συμβουλεύοντα καὶ τὰ κοινὰ πράττοντ’ ἀδύνατον· ἐὰν δ’ ἐπ’ εὐνοίᾳ ταὐτὰ τῷ δήμῳ τις φρονῇ, δίκαιός ἐστιν σῴζεσθαι. εἰ δὲ μή, καὶ θεραπεύειν ἑτέρους μᾶλλον ἢ τὸν δῆμον ἅπαντας διδάξετε, καὶ φεύγειν τὸ τῶν ὑμῖν συμφερόντων ποιοῦντά τι γνωσθῆναι.", "st": "63.3.27"}, {"sp": "N", "t": "ὅλως δὲ κοινόν ἐστιν ὄνειδος ἁπάντων, ἄνδρες Ἀθηναῖοι, καὶ ὅλης τῆς πόλεως συμφορά, τὸν φθόνον δοκεῖν μεῖζον ἰσχύειν παρ’ ὑμῖν ἢ τὰς τῶν εὐεργεσιῶν χάριτας, καὶ ταῦτα τοῦ μὲν νοσήματος ὄντος, τῶν δ’ ἐν τοῖς θεοῖς ἀποδεδειγμένων.", "st": "63.3.28"}, {"sp": "N", "t": "καὶ μὴν οὐδὲ τὸν Πυθέαν παραλείψω τὸν μέχρι τῆς παρόδου δημοτικόν, μετὰ ταῦτα δ’ ἕτοιμον εἰς τὰ καθ’ ὑμῶν πάντα. τίς γὰρ οὐκ οἶδεν τοῦτον, ὅτε μὲν τὴν ὑπὲρ ὑμῶν τάξιν ἔχων εἰς τὸ πολιτεύεσθαι παρῄει, ὡς δοῦλον ἐλαυνόμενον καὶ γραφὴν ξενίας φεύγοντα καὶ μικροῦ πραθένθ’ ὑπὸ τούτων οἷς νῦν ὑπηρετῶν τοὺς κατ’ ἐμοῦ λόγους ἔγραφεν,", "st": "63.3.29"}, {"sp": "N", "t": "ἐπειδὴ δ’ ἃ κατηγόρει τότε τῶν ἄλλων, νῦν αὐτὸς πράττει, εὐποροῦντα μὲν οὕτως ὥστε δύ’ ἔχειν ἑταίρας, αἳ μέχρι φθόης καλῶς ποιοῦσαι προπεπόμφασιν αὐτόν, πέντε τάλαντα δ’ ὀφλόντα ῥᾷον ἐκτεῖσαι ἢ πέντε δραχμὰς ἂν ἔδειξε πρότερον, πρὸς δὲ τούτοις παρ’ ὑμῶν, τοῦ δήμου, οὐ μόνον τῆς πολιτείας μετειληφότα, ὃ κοινὸν ὄνειδός ἐστιν ἅπασιν, ἀλλὰ καὶ θύονθ’ ὑπὲρ ὑμῶν τὰς πατρίους θυσίας ἐν Δελφοῖς;", "st": "63.3.30"}, {"sp": "N", "t": "ὅταν οὖν τοιαῦτα καὶ τηλικαῦτα πᾶσιν ἰδεῖν ᾖ παραδείγματα, ἀφ’ ὧν ἃ λυσιτελεῖ προελέσθαι πᾶς τις ἂν κρίναι, φοβοῦμαι μήποτ’ ἔρημοι τῶν ὑπὲρ ὑμῶν ἐρούντων γένησθε, ἄλλως τε καὶ ὅταν τῶν δημοτικῶν τοὺς μὲν ἡ καθήκουσα μοῖρα καὶ ἡ τύχη καὶ ὁ χρόνος παραιρῆται, οἷον Ναυσικλέα καὶ Χάρητα καὶ Διότιμον καὶ Μενεσθέα καὶ Εὔδοξον, ἔτι δ’ Εὐθύδικον καὶ Ἐφιάλτην καὶ Λυκοῦργον, τοὺς δ’ ὑμεῖς προῆσθε, ὥσπερ Χαρίδημον καὶ Φιλοκλέα καὶ ἐμέ.", "st": "63.3.31"}, {"sp": "N", "t": "ὧν ἑτέρους εὐνουστέρους οὐδ’ αὐτοὶ νομίζετε· εἰ δ’ ὁμοίους τινάς, οὐ φθονῶ, βουλοίμην δ’ ἄν, εἴπερ ὑμεῖς δικαίως αὐτοῖς προσοίσεσθε καὶ μὴ ταὔθ’ ἅπερ ἡμεῖς πείσονται, ὡς πλείστους αὐτοὺς γενέσθαι. ἀλλ’ ὅταν γε τοιαῦθ’ οἷα τὰ νῦν, παραδείγματ’ ἐκφέρητε, τίς ἔστιν ὅστις εἰς ταύτην τὴν τάξιν ἑαυτὸν γνησίως ὑμῖν ἐθελήσει δοῦναι;", "st": "63.3.32"}, {"sp": "N", "t": "ἀλλὰ μὴν τῶν γε προσποιησομένων οὐκ ἀπορήσετε· οὐδὲ γὰρ πρότερον. μὴ γένοιτο δ’ ἰδεῖν ἐξελεγχθέντας αὐτοὺς ὁμοίως ἐκείνοις, οἳ φανερῶς ἃ τότ’ ἠρνοῦντο νῦν πολιτευόμενοι οὐδέν’ ὑμῶν οὔτε δεδοίκασιν οὔτ’ αἰσχύνονται. ἃ χρὴ λογιζομένους, ὦ ἄνδρες Ἀθηναῖοι, μήτε τῶν εὔνων ὀλιγωρεῖν μήτε τοῖς προάγουσιν ἐς πικρίαν καὶ ὠμότητα τὴν πόλιν πείθεσθαι.", "st": "63.3.33"}, {"sp": "N", "t": "πολὺ γὰρ μᾶλλον εὐνοίας καὶ φιλανθρωπίας τὰ παρόντα πράγματα δεῖται ἢ ταραχῆς καὶ δυσμενείας, ὧν ὑπερβολῇ χρώμενοί τινες ἐργολαβοῦσι καθ’ ὑμῶν εἰς ὑποδοχὴν πραγμάτων, ὧν διαψεύσειεν αὐτοὺς ὁ λογισμός. εἰ δέ τις ὑμῶν διασύρει ταῦτα, πολλῆς ἐστιν εὐηθείας μεστός. εἰ γάρ, ἃ μηδεὶς ἂν ἤλπισεν, ὁρῶν γεγενημένα, ἃ καὶ πρότερον γέγονε τοῦ δήμου πρὸς τοὺς ὑπὲρ αὐτοῦ λέγοντας ὑπ’ ἀνθρώπων ἐγκαθέτων διαβληθέντος, νῦν μὴ ἂν οἴεται γενέσθαι, πῶς οὐ τετύφωται;", "st": "63.3.34"}, {"sp": "N", "t": "ταῦτ’ εἰ μὲν παρῆν, λέγων ἂν ὑμᾶς ἐδίδασκον· ἐπειδὴ δ’ ἐν τοιούτοις εἰμὶ ἐν οἷς, εἴ τις ἐμοῦ κατέψευσται ἐφ’ οἷς ἀπόλωλα, γένοιτο, γράψας ἐπέσταλκα, πρώτου μὲν καὶ πλεῖστον λόγον ποιούμενος τοῦ καλοῦ καὶ τοῦ συμφέροντος ὑμῖν, δεύτερον δ’ ὅτι τὴν αὐτὴν εὔνοιαν ἣν πρὸς ζῶντα Λυκοῦργον εἶχον, δίκαιον εἶναι νομίζω καὶ πρὸς τοὺς παῖδας αὐτοῦ φαίνεσθαι ἔχων.", "st": "63.3.35"}, {"sp": "N", "t": "εἰ δέ τῳ παρέστηκεν ὡς πολύ μοι περίεστιν τῶν ἐμαυτοῦ πραγμάτων, οὐκ ἂν ὀκνήσαιμι πρὸς τοῦτον εἰπεῖν ὅτι τῶν συμφερόντων ὑμῖν καὶ τοῦ μηδένα τῶν φίλων ἐγκαταλείπειν ὁμοίως ὥσπερ τῆς ἐμαυτοῦ σωτηρίας φροντίζω. οὔκουν ἐκ τοῦ περιόντος ταῦτα ποιῶ, ἀλλ’ ἀπὸ τῆς αὐτῆς σπουδῆς καὶ προαιρέσεως καὶ ταῦτα κἀκεῖνα μιᾷ γνώμῃ πραγματεύομαι. περίεστιν δέ μοι τοιαῦτα, οἷα τοῖς κακόν τι νοοῦσιν ὑμῖν περιγένοιτο. καὶ περὶ μὲν τούτων ἱκανά.", "st": "63.3.36"}, {"sp": "N", "t": "ἡδέως δ’ ἂν ὑμῖν ἐπ’ εὐνοίᾳ καὶ φιλίᾳ μέμψιν ποιησαίμην νῦν μὲν ἐν κεφαλαίῳ, μικρὸν δ’ ὕστερον δι’ ἐπιστολῆς μακρᾶς, ἣν ἐάνπερ ἐγὼ ζῶ προσδοκᾶτε, ἂν μὴ τὰ δίκαια γένηται μοι παρ’ ὑμῶν πρότερον· οἵτινες, ὦ ʽτί ἂν εἰπὼν μήθ’ ἁμαρτεῖν δοκοίην μήτε ψευσαίμην;’ λίαν ὀλίγωροι, οὔτε τοὺς ἄλλους οὔθ’ ὑμᾶς αὐτοὺς αἰσχύνεσθε, ἐφ’ οἷς Ἀριστογείτον’ ἀφείκατε, ἐπὶ τούτοις Δημοσθένην ἐκβεβληκότες,", "st": "63.3.37"}, {"sp": "N", "t": "καὶ ἃ τοῖς τολμῶσιν μηδὲν ὑμῶν φροντίζειν μηδὲ λαβοῦσι παρ’ ὑμῶν ἔξεστιν ἔχειν, ταῦτ’ οὐ διδόντες ἐμοί, ἵνα, ἂν οἷός τ’ ὦ, τά τ’ ὀφειλόμεν’ εἰσπράξας καὶ τοὺς φίλους ἐρανίσας τὰ πρὸς ὑμᾶς διοικήσω, καὶ μὴ γῆρας καὶ φυγὴν ἐπίχειρα τῶν ὑπὲρ ὑμῶν πεπονημένων ἔχων, κοινὸν ὄνειδος τῶν ἀδικησάντων, ἐπὶ ξένης περιιὼν ὁρῶμαι.", "st": "63.3.38"}, {"sp": "N", "t": "βουλομένου δέ μου ἐν μὲν ὑμετέρας χάριτος καὶ μεγαλοψυχίας τάξει τὴν οἴκαδέ μοι ἄφιξιν γενέσθαι, ἐμαυτῷ δὲ λύσιν τῆς γεγονυίας οὐ δικαίως βλασφημίας πορίσασθαι, καὶ μόνον αἰτοῦντος ἄδειαν ὅσονπερ χρόνον τὴν ἔκτεισιν δεδώκατε, ταῦτα μὲν οὐ συγχωρεῖτε, ἐρωτᾶτε δέ, ὡς ἀπαγγέλλεται πρὸς ἐμέ, \"τίς οὖν αὐτὸν κωλύει παρεῖναι καὶ ταῦτα πράττειν;\"", "st": "63.3.39"}, {"sp": "N", "t": "τὸ ἐπίστασθαι αἰσχύνεσθαι, ὦ ἄνδρες Ἀθηναῖοι, καὶ τὸ ἀναξίως τῶν ὑπὲρ ὑμῶν πεπολιτευμένων πράττειν, καὶ τὸ τὰ ὄντ’ ἀπολωλεκέναι διὰ τούτους ⟨οἷς⟩, ἵνα μὴ διπλᾶ καταθῶνται ἃ οὐκ ἠδύνανθ’ ἁπλᾶ, ἐπείσθην ὑπογράψασθαι ⟨πρὸς⟩ τὴν ἀρχὴν τὰς καταβολάς· παρ’ ὧν μετὰ μὲν τῆς ὑμετέρας εὐνοίας ἀφικόμενος μέρος, εἰ καὶ μὴ πάντα, ἴσως ἂν κομισαίμην, ὥστε μηδὲν ἀσχημονεῖν τὸ λοιπὸν τοῦ βίου, ἂν δ’ ὡς οἱ ταῦτα λέγοντες ἀξιοῦσί μ’ ἔλθω, ἅμ’ ἀδοξίᾳ καὶ ἀπορίᾳ καὶ φόβῳ συνέξομαι.", "st": "63.3.40"}, {"sp": "N", "t": "ὧν οὐδὲν ὑμεῖς συλλογίζεσθε, ἀλλὰ ῥημάτων μοι καὶ φιλανθρωπίας φθονοῦντες, ἂν οὕτω τύχῃ, δι’ ὑμᾶς περιόψεσθ’ ἀπολόμενον· οὐ γὰρ ἂν δεηθείην ἄλλων ἢ ὑμῶν. καὶ τότε φήσετε δεινὰ πεπονθέναι με, ἀκριβῶς οἶδα, ὅτ’ οὔτ’ ἐμοὶ πλέον οὐδὲν οὔθ’ ὑμῖν ἔσται. οὐ γὰρ δὴ χρήματά γ’ εἶναι μοι προσδοκᾶτ’ ἔξω τῶν φανερῶν, ὧν ἀφίσταμαι. καὶ τὰ λοιπὰ βούλομαι συναγαγεῖν, ἐάν μοι μὴ φιλονίκως, ἀλλ’ ἀνθρωπίνως δῶτε τὸ πρὸς τούτοις ἀσφαλῶς εἶναι.", "st": "63.3.41"}, {"sp": "N", "t": "οὐ μὴν οὐδὲ παρ’ Ἁρπάλου με λαβόντα δείξετε· οὔτε γὰρ ἠλέγχθην οὔτ’ ἔλαβον. εἰ δὲ τὸ περιφανὲς ἀξίωμα τῆς βουλῆς [ἢ τὸν Ἄρειον πάγον] προσβλέπετε, τῆς Ἀριστογείτονος κρίσεως ἀναμνησθέντες ἐγκαλύψασθε· οὐ γὰρ ἔχω τούτου πραότερον πρόσταγμα τοῖς τοιαῦτ’ ἐξημαρτηκόσιν εἰς ἐμέ.", "st": "63.3.42"}, {"sp": "N", "t": "οὐ γὰρ δήπου τοῖς αὐτοῖς γε λόγοις ὑπὸ τῆς αὐτῆς βουλῆς ἀποφανθέντ’ ἐκεῖνον μὲν ἀφεῖσθαι δίκαιον εἶναι φήσετε, ἐμὲ δ’ ἀπολωλέναι· οὐχ οὕτως ὑμεῖς ἀλογίστως ἔχετε. οὔτε γὰρ ἄξιος οὔτ’ ἐπιτήδειος οὔτε χείρων, ἀτυχὴς μέντοι δι’ ὑμᾶς, ὁμολογῶ· πῶς γὰρ οὐκ ἀτυχής, ᾧ πρὸς τοῖς ἄλλοις κακοῖς καὶ πρὸς Ἀριστογείτον’ ἐμαυτὸν ἐξετάζειν συμβαίνει, καὶ ταῦτ’ ἀπολωλότι πρὸς σωτηρίας τετυχηκότα;", "st": "63.3.43"}, {"sp": "N", "t": "καὶ μή μ’ ὑπολαμβάνετ’ ὀργίζεσθαι τοῖς λόγοις τούτοις· οὐ γὰρ ἂν πάθοιμι τοῦτο πρὸς ὑμᾶς ἐγώ· ἀλλ’ ἔχει τινὰ τις ἀδικουμένοις ῥᾳστώνην τὸ λέγειν ἃ πάσχουσιν, ὥσπερ τοῖς ἀλγοῦσι τὸ στένειν, ἐπεὶ τῇ γ’ εὐνοίᾳ οὕτως ἔχω πρὸς ὑμᾶς ὡς ὑμᾶς ἂν εὐξαίμην πρὸς ἐμέ. καὶ τοῦτ’ ἐν πᾶσιν πεποίηκα καὶ ποιήσω φανερόν.", "st": "63.3.44"}, {"sp": "N", "t": "ἔγνωκα γὰρ ἐξ ἀρχῆς παντὶ τῷ πολιτευομένῳ προσήκειν, ἄνπερ ᾖ δίκαιος πολίτης, ὥσπερ οἱ παῖδες πρὸς τοὺς γονέας, οὕτως πρὸς ἅπαντας τοὺς πολίτας ἔχειν, εὔχεσθαι μὲν ὡς εὐγνωμονεστάτων τυγχάνειν, φέρειν δὲ τοὺς ὄντας εὐμενῶς· ἡ γὰρ ἐν τοῖς τοιούτοις ἧττα καλὴ καὶ προσήκουσα νίκη παρὰ τοῖς εὖ φρονοῦσι κρίνεται. εὐτυχεῖτε.", "st": "63.3.45"}, {"sp": "SEC", "t": "4. Περὶ τῆς Θηραμένους βλασφημίας", "st": "63.4"}, {"sp": "N", "t": "Δημοσθένης τῇ βουλῇ καὶ τῷ δημῷ χαίρειν. ἀκούω περὶ ἐμοῦ Θηραμένην ἄλλους τε λόγους βλασφήμους εἰρηκέναι καὶ δυστυχίαν προφέρειν. τὸ μὲν οὖν τοῦτον ἀγνοεῖν ὅτι λοιδορίας, ἣ μηδεμίαν κακίαν, καθ’ ὅτου λέγεται, δείκνυσιν, οὐδέν ἐστ’ ὄφελος παρ’ εὖ φρονοῦσιν ἀνθρώποις, οὐχὶ θαυμάζω· τὸν γὰρ θρασὺν μὲν τῷ βίῳ, μὴ πολίτην δὲ τὴν φύσιν, ἐν ἐργαστηρίῳ δὲ τεθραμμένον ἐκ παιδός, αἰσθάνεσθαί τι τῶν τοιούτων ἀλογώτερον ἦν ἢ μὴ συνιέναι.", "st": "63.4.1"}, {"sp": "N", "t": "τούτῳ μὲν οὖν, ἐὰν ἀφίκωμαί ποτε καὶ σωθῶ, πειράσομαι διαλεχθῆναι περὶ ὧν εἰς ἐμὲ καὶ περὶ ὧν εἰς ὑμᾶς παροινεῖ, καὶ νομίζω, καίπερ οὐδὲν μετέχοντα τοῦ αἰσχύνεσθαι, μετριώτερον αὐτὸν ποιήσειν· ὑμῖν δὲ τοῦ κοινῇ συμφέροντος ἕνεκα βούλομαι δι’ ἐπιστολῆς, οὓς περὶ τούτων ἔχω λόγους, δηλῶσαι. οἷς πάνυ τὸν νοῦν προσέχοντες ἀκούσατε· οἴομαι γὰρ αὐτοὺς οὐκ ἀκοῆς μόνον, ἀλλὰ καὶ μνήμης ἀξίους εἶναι.", "st": "63.4.2"}, {"sp": "N", "t": "ἐγὼ τὴν πόλιν τὴν ὑμετέραν εὐτυχεστάτην πασῶν πόλεων ὑπολαμβάνω καὶ θεοφιλεστάτην, καὶ ταῦτ’ οἶδα καὶ τὸν Δία τὸν Δωδωναῖον καὶ τὴν Διώνην καὶ τὸν Ἀπόλλω τὸν Πύθιον ἀεὶ λέγοντας ἐν ταῖς μαντείαις καὶ προσεπισφραγιζομένους τὴν ἀγαθὴν τύχην ἐν τῇ πόλει εἶναι παρ’ ὑμῖν. ὅσα τοίνυν περὶ τῶν ἐπιόντων δηλοῦσιν οἱ θεοί, δῆλον ὡς προλέγουσιν· τὰς δ’ ἀπὸ τῶν παρεληλυθότων προσηγορίας ἐπὶ ταῖς γεγονυίαις πράξεσι τίθενται.", "st": "63.4.3"}, {"sp": "N", "t": "ἃ τοίνυν ἐγὼ πεπολίτευμαι παρ’ ὑμῖν, τῶν ἤδη γεγενημένων ἐστίν, ἀφ’ ὧν εὐτυχεῖς ὑμᾶς προσηγορεύκασιν οἱ θεοί. πῶς οὖν δίκαιον τοὺς μὲν πεισθέντας εὐτυχεῖς ὀνομάζεσθαι, τὸν δὲ πείσαντα τῆς ἐναντίας προσηγορίας τυγχάνειν; πλὴν εἰ τοῦτό τις εἴποι, τὴν μὲν κοινὴν εὐτυχίαν, ἧς ἐγὼ σύμβουλος, θεοὺς τοὺς λέγοντας εἶναι, οἷς οὐ θέμις ψεύδεσθαι, τὴν δ’ ἰδίαν βλασφημίαν, ᾗ κατ’ ἐμοῦ κέχρηται Θηραμένης, θρασὺν καὶ ἀναιδῆ καὶ οὐδὲ νοῦν ἔχοντ’ ἄνθρωπον εἰρηκέναι.", "st": "63.4.4"}, {"sp": "N", "t": "οὐ τοίνυν μόνον ταῖς παρὰ τῶν θεῶν μαντείαις ἀγαθὴν οὖσαν εὑρήσεθ’ ᾗ κέχρησθε τύχῃ, ἀλλὰ καὶ ἐξ αὐτῶν τῶν ἔργων θεωροῦντες, ἂν ἐξετάζητ’ ὀρθῶς. ὑμεῖς γὰρ εἰ μὲν ὡς ἄνθρωποι τὰ πράγματα βούλεσθε θεωρεῖν, εὐτυχεστάτην εὑρήσετ’ ἀφ’ ὧν ἐγὼ συνεβούλευσα τὴν πόλιν γεγονυῖαν· εἰ δ’ ἃ τοῖς θεοῖς ἐξαίρεθ’ ὑπάρχει μόνοις, τούτων ἀξιώσετε τυγχάνειν, ἀδυνάτων ἐφίεσθε.", "st": "63.4.5"}, {"sp": "N", "t": "τί οὖν ἐστιν θεοῖς ἐξαίρετον, ἀνθρώποις δ’ οὐ δυνατόν; ἁπάντων τῶν ἀγαθῶν ἐγκρατεῖς ὄντας κυρίους εἶναι καὶ αὐτοὺς ἔχειν καὶ δοῦναι τοῖς ἄλλοις, φλαῦρον δὲ μηδὲν μηδέποτ’ ἐν παντὶ τῷ αἰῶνι μήτε παθεῖν μήτε μελλῆσαι. καὶ μὴν ὑποκειμένων τούτων, ὥσπερ προσήκει, σκοπεῖτε τὰ ὑμέτερ’ αὐτῶν πρὸς τὰ τῶν ἄλλων ἀνθρώπων.", "st": "63.4.6"}, {"sp": "N", "t": "οὐδεὶς γὰρ οὕτως ἐστὶν ἀγνώμων, ὅστις ἂν ἢ τὰ Λακεδαιμονίοις συμβεβηκότα, οἷς οὐκ ἐγὼ συνεβούλευον, ἢ τὰ Πέρσαις, πρὸς οὓς οὐδ’ ἀφικόμην πώποτε, αἱρετώτερα φήσειεν εἶναι τῶν ὑμῖν παρόντων. καὶ ἐῶ Καππαδόκας καὶ Σύρους καὶ τοὺς τὴν Ἰνδικὴν χώραν κατοικοῦντας ἀνθρώπους ἐπ’ ἔσχατα γῆς· οἷς ἅπασι συμβέβηκε πολλὰ καὶ δεινὰ πεπονθέναι καὶ χαλεπά.", "st": "63.4.7"}, {"sp": "N", "t": "ἀλλὰ νὴ Δία τούτων μὲν ἄμεινον ὑμᾶς πράττειν ἅπαντες ὁμολογήσουσι, Θετταλῶν δὲ καὶ Ἀργείων καὶ Ἀρκάδων χεῖρον, ἤ τινων ἄλλων, οἷς ἐν συμμαχίᾳ συνέβη γενέσθαι Φιλίππῳ. ἀλλὰ τούτων καὶ πολὺ βέλτιον ἀπηλλάχατε, οὐ μόνον τῷ μὴ δεδουλευκέναι ʽκαίτοι τί τηλικοῦθ’ ἕτερον;’, ἀλλὰ καὶ τῷ τοὺς μὲν πάντας αἰτίους εἶναι δοκεῖν τῶν τοῖς Ἕλλησι κακῶν συμβεβηκότων διὰ Φιλίππου καὶ τῆς δουλείας, ἐξ ὧν εἰκότως μισοῦνται,", "st": "63.4.8"}, {"sp": "N", "t": "ὑμᾶς δ’ ὁρᾶσθαι ὑπὲρ τῶν Ἑλλήνων καὶ σώμασι καὶ χρήμασι καὶ πόλει καὶ χώρᾳ καὶ πᾶσιν ἠγωνισμένους, ἀνθ’ ὧν εὔκλειαν εἰκὸς ὑπάρχειν καὶ χάριν ἀθάνατον παρὰ τῶν τὰ δίκαια βουλομένων ποιεῖν. οὐκοῦν ἀφ’ ὧν ἐγὼ συνεβούλευσα, τῶν μὲν ἀντιστάντων ἄριστα πράττειν τῇ πόλει συμβέβηκεν, τῶν δὲ συνηγωνισμένων ἐνδοξοτέραν εἶναι περίεστιν.", "st": "63.4.9"}, {"sp": "N", "t": "τοιγαροῦν ἐπὶ τούτοις οἱ θεοὶ τὰς μὲν μαντείας τὰς ἀγαθὰς ὑμῖν διδόασι, τὴν δ’ ἄδικον βλασφημίαν εἰς κεφαλὴν τῷ λέγοντι τρέπουσιν. γνοίη δ’ ἄν τις, εἰ προέλοιτ’ ἐξετάσαι τὰ ἐπιτηδεύματ’ ἐν οἷς ζῇ.", "st": "63.4.10"}, {"sp": "N", "t": "ἃ γὰρ ἂν καταράσαιτό τις αὐτῷ, ταῦτ’ ἐκ προαιρέσεως ποιεῖ. ἐχθρὸς μέν ἐστι τοῖς γονεῦσι, φίλος δὲ Παυσανίᾳ τῷ πόρνῳ· καὶ θρασύνεται μὲν ὡς ἀνήρ, πάσχει δ’ ὡς γυνή· καὶ τοῦ μὲν πατρός ἐστι κρείττων, τῶν δ’ αἰσχρῶν ἥττων· οἷς δ’ ὑπὸ πάντων δυσχεραίνεται, τούτοις τὴν διάνοιαν ἀγάλλεται, αἰσχρορρημοσύνῃ καὶ τῷ διηγεῖσθαι ταῦτ’ ἐφ’ οἷς ἀλγοῦσιν οἱ ἀκούοντες· ὁ δ’, ὡς ἀφελὴς καὶ παρρησίας μεστός, οὐ παύεται.", "st": "63.4.11"}, {"sp": "N", "t": "καὶ ταῦτ’ οὐκ ἂν ἔγραψα, εἰ μὴ κινῆσαι τὴν ἐν ὑμῖν μνήμην τῶν προσόντων αὐτῷ κακῶν ἠβουλόμην. ἃ γὰρ εἰπεῖν ἄν τις ὀκνήσαι καὶ γράψαι φυλάξαιτ’ ἄν, οἶμαι δὲ κἂν ἀκούσαντα δυσχερᾶναι, ταῦτ’ ἀπὸ τούτων μνησθεὶς οἶδεν ἕκαστος ὑμῶν πολλὰ καὶ δεινὰ καὶ αἰσχρὰ τούτῳ προσόντα, ὥστ’ ἐμοί τε μηδὲν ἀναιδὲς εἰρῆσθαι, καὶ τοῦτον ὑπόμνημα τῶν ἑαυτοῦ κακῶν ὀφθέντα πᾶσιν εἶναι. εὐτυχεῖτε.", "st": "63.4.12"}, {"sp": "SEC", "t": "5. Πρὸς Ἡρακλεόδωρον", "st": "63.5"}, {"sp": "N", "t": "Δημοσθένης Ἡρακλεοδώρῳ εὖ πράττειν. οὔθ’ ὅπως χρὴ πιστεύειν οἷς ἀπήγγελλέ μοι Μενεκράτης οὔθ’ ὅπως ἀπιστεῖν, ἔχω. ἔφη γὰρ Ἐπίτιμον ἐνδεδεῖχθαι μὲν καὶ ἀπῆχθαι ὑπ’ Ἀράτου, σὲ δ’ ἀγωνίζεσθαι καὶ ἁπάντων αὐτῷ χαλεπώτατον εἶναι. δέομαι δή σου πρὸς Διὸς ξενίου καὶ πάντων τῶν θεῶν, μή με καταστήσῃς ἀηδεῖ καὶ δεινῷ μηδενὶ περιπετῆ.", "st": "63.5.1"}, {"sp": "N", "t": "εὖ γὰρ ἴσθι, χωρὶς τοῦ μέλειν μοι τῆς Ἐπιτίμου σωτηρίας καὶ νομίσαι μεγάλην ἂν συμφοράν, εἴ τι πάθοι καὶ τούτου σὺ συναίτιος εἴης, αἰσχύνομαι τοὺς συνειδότας μοι τοὺς λόγους οὓς ἐγὼ περὶ σοῦ πρὸς ἅπαντας ἀνθρώπους ἔλεγον, πεπεικὼς ἐμαυτὸν ἀληθῆ λέγειν, οὐκ ἐκ τοῦ πεπλησιακέναι σοι πεῖραν ἔχων,", "st": "63.5.2"}, {"sp": "N", "t": "ἀλλ’ ὁρῶν ὅτι δόξης ἐπιτυγχάνων καὶ παιδείαν ἀπεδέχου, καὶ ταῦτα τὴν ἀπὸ τῆς Πλάτωνος διατριβῆς, ἥπερ ἐστὶν ὡς ἀληθῶς τῶν μὲν πλεονεκτημάτων καὶ τῶν περὶ ταῦτα σοφισμάτων ἔξω, τοῦ βελτίστου δὲ καὶ τοῦ δικαιοτάτου πάνθ’ ἕνεκ’ ἐξητασμένη· ἧς μὰ τοὺς θεοὺς τῷ μετασχόντι μὴ οὐχὶ ἀψευδεῖν καὶ πρὸς ἅπαντας ἀγαθῷ εἶναι οὐχ ὅσιον ἡγοῦμαι.", "st": "63.5.3"}, {"sp": "N", "t": "γένοιτο δ’ ἄν μοι κἀκεῖνο τῶν χαλεπωτάτων, εἰ παρωρμηκὼς ἐμαυτὸν εὐνοϊκῶς ἔχειν σοι τὴν ἐναντίαν γνώμην μεταλαβεῖν ἀναγκασθείην, οἷα δὴ ὑπολαμβάνων παρεωρᾶσθαι καὶ πεφενακίσθαι. κἂν μὴ φῶ, νόμιζέ μ’ οὕτως ἕξειν.", "st": "63.5.4"}, {"sp": "N", "t": "εἰ δ’ ἡμῶν καταπεφρόνηκας ὅτι τῶν πρώτων οὐκ ἐσμέν πω, λόγισαι ὅτι καὶ σύ ποτ’ ἦσθα νέος καὶ τὴν ἡλικίαν εἶχες ἣν ἡμεῖς νῦν, ἐκ δὲ τοῦ συμβουλεύειν καὶ πράττειν γεγένησαι τηλικοῦτος. κἂν ἡμῖν τοῦτο συμβαίη. τὸ μὲν γὰρ εὖ βουλεύεσθαι πάρεστιν, τῆς δὲ τύχης συλλαμβανούσης καὶ τοὔργον γένοιτ’ ἄν. καλὸς οὖν ἔρανος χάρις δικαία· ἣν καὶ σὺ ποίησαι πρὸς ἐμέ.", "st": "63.5.5"}, {"sp": "N", "t": "καὶ μηδ’ ὑφ’ ἑνὸς τῶν σοῦ φρονούντων χεῖρον ἄγου μηδ’ ἡττῶ, ἀλλ’ ἐκείνους ἄγ’ ἐπὶ τὰ σοὶ δοκοῦντα· καὶ πρᾶττε οὕτως ὅπως μηδενὸς τῶν ὁμολογηθέντων στερηθῶμεν, ἀλλ’ Ἐπιτίμῳ γένηται σωτηρία τις καὶ ἀπαλλαγὴ τῶν κινδύνων. παρέσομαι δ’ εἰς τὸν χρόνον κἀγώ, καθ’ ὃν ⟨ἂν⟩ σὺ φῇς καιρὸν εἶναι. γράψας δέ μοι πέμψον, ἢ καὶ ὡς φίλῳ ἐπίστελλε. εὐτύχει.", "st": "63.5.6"}, {"sp": "SEC", "t": "6. Πρὸς τὴν βουλὴν καὶ τὸν δῆμον τὸν Ἀθηναίων", "st": "63.6"}, {"sp": "N", "t": "Δημοσθένης τῇ βουλῇ καὶ τῷ δημῷ χαίρειν. ἦλθεν ἐπιστολὴ παρ’ Ἀντιφίλου πρὸς τοὺς τῶν συμμάχων συνέδρους, τοῖς μὲν βουλομένοις ἀγαθὰ προσδοκᾶν ἱκανῶς γεγραμμένη, τοῖς δ’ ὑπηρετοῦσιν Ἀντιπάτρῳ πολλοὺς καὶ δυσχερεῖς ἀπολείπουσα λόγους, οἳ παραλαβόντες τὰ παρ’ Ἀντιπάτρου γράμματα πρὸς Δείναρχον εἰς Κόρινθον ἐλθόντα, ἁπάσας τὰς ἐν Πελοποννήσῳ πόλεις τοιούτων λόγων ἔπλησαν οἵων εἰς κεφαλὴν αὐτοῖς τρέψειαν οἱ θεοί.", "st": "63.6.1"}, {"sp": "N", "t": "ἀφικομένου δὲ τοῦ νῦν ἥκοντος μετὰ τοῦ παρ’ ἐμοῦ φέροντος γράμματα παρὰ Πολεμαίστου πρὸς τὸν ἀδελφὸν Ἐπίνικον, ἄνδρ’ ὑμῖν εὔνουν καὶ ἐμοὶ φίλον, κἀκείνου πρὸς ἔμ’ ἀγαγόντος, ἀκούσαντί μοι ἃ ἔλεγεν ἐδόκει πρὸς ὑμᾶς αὐτὸν ἀποστεῖλαι, ὅπως πάντα σαφῶς ἀκούσαντες τὰ ἐν τῷ στρατοπέδῳ γεγονότα τοῦ περὶ τὴν μάχην παραγεγενημένου τό τ’ εἰς τὸ παρὸν θαρρῆτε, καὶ τὰ λοιπὰ τῶν θεῶν θελόντων ὡς βούλεσθ’ ἕξειν ὑπολαμβάνητε. εὐτυχεῖτε.", "st": "63.6.2"}], []);})();
